import Foundation

// 이 파일은 Scripts/import_topic_guides.py가 검토본 docx에서 처음 만들었고,
// 그 뒤 치료적 관계 설명을 한다체로 고쳤다. 이후 수정은 이 파일에서 직접 한다.
// 본문은 줄 단위의 간단한 표기를 쓴다: "# 소제목", "- 목록"(두 칸 들여쓰기마다 한 수준),
// 문장 안의 **굵게**. TopicGuideView가 이 표기를 화면에 그린다.

/// 주제별 설명. topics에 들어 있는 주제(StudyTopics의 주제 이름)에서 이 설명을 보여 준다.
struct TopicGuide: Identifiable {
    let topics: [String]
    let title: String
    let body: String
    var id: String { title }
}

enum TopicGuides {
    static func guide(for topic: String) -> TopicGuide? {
        all.first { $0.topics.contains(topic) }
    }

    static let all: [TopicGuide] = [
        // 2026-71 아래에 붙은 설명
        TopicGuide(
            topics: ["치료적 관계의 단계와 자기인식"],
            title: "단계별 과업 (국시 기준)",
            body: #"""
            # 국시 출제 경향
            - 2020~2026년에 **매년 1문항씩, 모두 7문항**이 나왔다. 대개 2교시 73·74번 자리이고, 2026년에는 첫 문항(71번)으로 나왔다.
            - **어느 단계인지 고르기**(3문항): 단계의 특징을 주고 단계 이름을 고른다.
              - 2025-74 상실감을 경험하며 퇴행이 나타날 수 있다 → **종결 단계**
              - 2020-73 대상자와 간호사 모두 이별로 인한 상실을 극복하는 과정을 배우고, 부정적 경험이 있던 대상자는 퇴행할 수 있다 → **종결 단계**
              - 2024-74 저항을 극복하고 문제행동 변화에 초점을 둔다 → **활동 단계**
            - **단계에 해당하는 과업 고르기**(3문항): 단계 이름을 주고 과업을 고른다.
              - 2023-73 오리엔테이션(초기) 단계 → **비밀보장에 대한 계약 설정**
              - 2021-73 활동 단계 → **대상자의 통찰력이 늘어 건설적인 적응기전을 기른다**
              - 2022-73 종결 단계 → **치료적 관계 동안 일어났던 상황을 검토한다**
            - **자기인식**(1문항): 2026-71 대상자를 이해하려고 간호사가 자신의 가치관·신념·태도·감정을 먼저 파악하는 원리 → **자기인식**
            - **종결 단계가 3번**으로 가장 많이 나왔다. 상실감·분리불안·퇴행·관계 검토는 종결 단계의 핵심어이다.
            - 오답 보기는 **다른 단계의 과업**을 섞어 만든다. 예를 들어 2023-73에서는 자기탐색(상호작용 전), 통찰력 증진·행동 변화·건설적 대처기전(활동)이 오답이었다.

            # 풀이 요령
            - 단계마다 핵심어를 하나씩 짝지어 둔다.
              - 상호작용 전: 간호사의 **자기탐색·자기인식**, 선입견 확인
              - 오리엔테이션: **신뢰·라포**, **계약**(비밀보장 범위 포함), 문제 확인, 목표 설정
              - 활동: **저항 극복**, **통찰**, **행동 변화**, 건설적 대처기전
              - 종결: **상실감·퇴행**, 목표 달성 평가, 관계 동안의 상황 **검토**
            - 보기에 "간호사 자신"이 주어로 나오면 상호작용 전 단계, "계약·목표 설정"이면 오리엔테이션 단계일 가능성이 높다.
            - "도입 단계", "오리엔테이션 전 단계"처럼 없는 단계 이름이 오답 보기로 나온다(2024-74, 2025-74).

            # 1. 상호작용 전 단계: 대상자를 만나기 전
            - **간호사의 자기인식·자기탐색**: 이 단계에서 가장 중요한 과업이다.
              - 자신의 가치관, 신념, 편견, 불안, 두려움을 점검한다.
              - 예: "자살 시도 환자를 만나는 것이 두렵다"
            - 대상자에 대한 정보를 모은다(기록, 다른 의료진).
            - 첫 만남의 시간과 장소를 계획한다.
            - 국시: **2026-71** (자기인식)

            # 2. 오리엔테이션(초기) 단계: 관계의 시작
            - **신뢰와 라포 형성**: 수용하는 태도와 개방적 의사소통으로 쌓는다.
            - **치료적 계약**을 맺는다.
              - 서로의 이름과 역할
              - 만남의 시간, 장소, 횟수, 기간
              - 종결 조건
              - **비밀보장의 범위**: 치료팀과는 정보를 공유한다는 점을 포함한다.
            - 대상자가 도움을 구하는 이유를 **사정**하고, 문제를 확인해 **간호진단**을 내린다.
            - 대상자와 함께 **목표를 정한다**.
            - 대상자의 반응: 간호사를 시험하는 행동(testing), 불안, 저항이 흔하다.
            - 국시: **2023-73** (비밀보장 계약)

            # 3. 활동(작업) 단계: 관계의 핵심
            - 대상자의 스트레스원과 문제를 **탐색**한다.
            - **통찰을 높여** 건설적인 대처기전을 기르도록 돕는다.
            - 새로운 대처 행동을 연습하게 하고, **행동 변화**를 이끌어 낸다.
            - **저항을 극복**한다. 전이와 역전이를 알아차리고 다룬다.
            - 대상자가 점점 **스스로 해 나가도록** 돕는다. 원전의 '이용' 단계에서 강조하는 '놓아주기'이다.
            - 국시: **2024-74** (저항 극복·행동 변화), **2021-73** (통찰 증진·건설적 적응기전)

            # 4. 종결 단계: 관계의 마무리
            - 종결은 **관계 초기부터 예고**하고, 종결 시점을 미리 알린다.
            - 목표 달성을 대상자와 함께 **평가**하고, 관계 동안 있었던 일을 **돌아본다**.
            - 이별에 대한 감정 표현을 돕는다.
              - 대상자는 **상실감, 분리불안, 분노, 거부감**을 느낄 수 있다.
              - **퇴행**이 나타나거나 이전 증상이 다시 보일 수 있다.
              - 과거에 이별 경험이 부정적이었던 대상자에게서 특히 두드러진다.
            - 간호사도 상실을 경험한다. 대상자와 간호사 **모두 이별을 극복하는 과정을 배운다**.
            - 퇴원 뒤를 계획하고, 지역사회 자원을 연결한다.
            - 국시: **2025-74** (상실감·퇴행), **2022-73** (관계 동안의 상황 검토), **2020-73** (서로 이별을 극복, 퇴행)
            """#
        ),
        // 2026-72 아래에 붙은 설명
        TopicGuide(
            topics: ["방어기제"],
            title: "방어기제 정리",
            body: #"""
            방어기제는 스트레스와 갈등에서 생기는 불안으로부터 자신을 보호하려는 반응 양식이다. **억제만 의식적**이고 나머지는 모두 무의식적으로 작동한다. 방어기제를 지나치게 쓰면 특정 정신장애와 관련된다.

            # 국시 출제 경향
            - 2020~2026년에 **8문항**이 나왔다. 매년 1문항 이상이고, 2025년에는 2문항이 나왔다.
            - 대개 정신간호학 첫머리(2교시 71·72번)에 나오고, 질환 문항(2024-87, 2025-93) 속에서도 나온다.
            - **사례를 보고 방어기제 고르기**가 가장 많다(5문항).
              - 2026-72 남편에게 맞고 화가 나면 아이에게 소리를 지른다 → **전치**
              - 2024-87 아들의 입시 실패가 자기 죄 때문이라며 운다(우울증) → **함입**
              - 2021-71 술을 마신 것이 아내의 잔소리 때문이라고 한다 → **투사**
              - 2020-72 아침에 부인과 싸운 남편이 선물을 사 간다 → **취소**
              - 2022-72 "작은 고추가 맵다" → **보상**
            - **질환·발달과 짝짓기**(2문항)
              - 2025-93 강박장애 환자가 불안을 줄이려고 쓰는 방어기제 → **취소**
              - 2025-72 남근기 오이디푸스 콤플렉스 해결 → **동일시**
            - **정의·특성**(1문항): 2023-71 의식 수준에서 작동하는 방어기제 → **억제**
            - 정답으로 나온 것: 전치, 함입, 투사, 취소(2번), 보상, 동일시, 억제
            - 오답 보기로 자주 나온 것: 전환, 반동형성, 승화, 주지화, 합리화, 퇴행, 격리

            # 풀이 요령
            - 사례 문항은 **감정과 책임이 어디로 향하는지**로 가른다.
              - 다른 대상에게 옮겨 푼다 → 전치
              - 남의 탓으로 돌린다 → 투사
              - 자기 탓으로 돌린다 → 함입(우울증)
              - 그럴듯한 이유를 댄다 → 합리화
              - 행동으로 없던 일로 되돌린다 → 취소
            - 질환과 짝지어 외운다: 강박장애(취소·격리·반동형성), 우울증(함입), 편집증(투사), 전환장애(전환), 해리성 기억상실(억압), 경계성 성격장애(분열)
            - **억제만 의식적**이라는 점은 정의 문항과 오답 가리기에 모두 쓰인다.

            # 억제 (suppression)
            괴로운 생각이나 충동을 의식적으로 밀어내는 것이다. 방어기제 가운데 유일하게 의식 수준에서 작동한다.
            예: 해고가 두려워 상사에게 대들고 싶은 마음을 누른다.
            국시: 2023-71 (의식적인 수준에서 작동하는 방어기제)

            # 격리 (isolation)
            사건 자체는 기억하지만 그에 따른 감정은 분리해 느끼지 않는 것이다. 강박장애에서 흔하다.
            국시: 2026-72 (오답 보기)

            # 동일시 (identification)
            다른 사람의 특성이나 가치를 자기 것으로 삼는 것이다. 남근기의 아동은 동성 부모와 동일시해 오이디푸스 콤플렉스를 해결하고, 성역할과 초자아를 발달시킨다.
            국시: 2025-72 (오이디푸스 콤플렉스 해결)

            # 반동형성 (reaction formation)
            받아들일 수 없는 감정이나 충동을 정반대의 감정이나 행동으로 바꾸어 나타내는 것이다. 강박장애에서도 쓰인다.
            예: 몹시 미워하는 어머니에 대해 훌륭한 분이라고 쓴다. 아이를 때리려다가 머리를 쓰다듬는다.

            # 보상 (compensation)
            신체적·심리적 약점이나 열등감을 다른 영역에서 뛰어난 성취로 메우는 것이다.
            예: "작은 고추가 맵다"
            국시: 2022-72

            # 부정 (denial)
            불쾌한 생각이나 사건을 무시하거나 의식에서 배제하는 것이다.
            예: 새로 암 진단을 받은 환자가 진단이 잘못되었다고 주장한다. 알코올 중독자가 음주 문제를 인정하지 않는다.

            # 분열 (splitting)
            불안을 일으키는 대상을 전부 좋거나 전부 나쁘게만 보는 것이다. 경계성 성격장애에서 흔하다.
            예: 간호사를 "최고"라고 하다가, 그 간호사가 규칙을 지키게 하자 "최악"이라고 한다.

            # 상징화 (symbolization)
            억압된 충동이나 감정을 상징으로 대신 나타내는 것이다.
            예: 누군가를 해치고 싶은 억압된 충동과 관련해 무의식적으로 빨간 옷을 입는다.

            # 승화 (sublimation)
            사회적으로 받아들여지지 않는 성적·공격적 충동을 운동이나 예술처럼 인정되는 방식으로 돌리는 것이다. 가장 성숙한 방어기제이다.
            예: 노출 충동을 무용 안무로 표현한다.

            # 억압 (repression)
            고통스러운 경험이나 용납되지 않는 충동을 무의식적으로 의식 밖으로 밀어내는 것이다. 해리성 기억상실의 주된 방어기제이다.
            예: 근친 성폭력 피해자가 가해자를 미워하지만 그 이유를 기억하지 못한다.

            # 전치 (displacement)
            감정을 원래 대상에게서 덜 위협적인 다른 대상에게 옮겨 표출하는 것이다.
            예: 배우자에게 화가 나서 대신 개를 찬다. 화가 나서 상대가 아닌 책상을 친다.
            국시: 2026-72 (남편에게 맞고 화가 나면 아이에게 소리를 지름)

            # 전환 (conversion)
            억압된 충동과 감정으로 생긴 불안이 감각이나 운동 기능의 신체 증상으로 바뀌는 것이다. 전환장애의 방어기제이다.
            예: 외상 경험을 다루는 치료를 앞두고 심한 두통이 생겨 치료를 취소한다. 화가 나서 한 대 치려는 순간 손이 마비된다.

            # 주지화 (intellectualization)
            감정을 느끼는 대신 지적으로 분석하고 따지며 대처하는 것이다.
            국시: 2025-72 (오답 보기)

            # 취소 (undoing)
            용납되지 않는 행동이나 생각을 상징적인 행동으로 없던 일로 되돌리려는 것이다. 강박장애의 대표적인 방어기제로, 오염에 대한 생각 뒤에 반복해서 손을 씻는 것이 한 예이다.
            예: 아침에 부인과 싸운 남편이 귀가할 때 선물을 사 간다.
            국시: 2020-72, 2025-93 (강박장애 환자가 불안을 줄이려고 사용하는 방어기제)

            # 퇴행 (regression)
            스트레스를 받을 때 이전의 낮은 발달 수준으로 돌아가는 것이다.
            예: 배변 훈련이 끝난 아이가 부모의 이혼 뒤 다시 오줌을 싼다.

            # 투사 (projection)
            받아들이기 어려운 자신의 감정, 충동, 책임을 다른 사람의 것으로 돌리는 것이다. 편집증에서 흔하다.
            예: "내가 그를 미워한다" 대신 "그가 나를 미워한다"고 여긴다.
            국시: 2021-71 (술을 마신 것이 아내의 잔소리 때문이라는 알코올 중독 환자)

            # 함입 (introjection)
            다른 사람이나 외부 사건에 향해야 할 감정과 책임을 자기 자신에게로 향하게 해 받아들이는 것이다. 우울증에서 대표적으로 나타난다. 정신분석에서는 잃어버린 대상에 대한 분노가 외부가 아니라 자신에게 향해 죄책감과 자기 비난이 커진다고 설명한다.
            예: 주요우울장애 환자가 "아들이 대학 입시에 실패한 것은 내가 죄가 많아서예요"라며 운다.
            국시: 2024-87

            # 합리화 (rationalization)
            그럴듯한 이유를 대어 용납되지 않는 행동을 정당화하고 죄책감을 피하는 것이다.
            예: 월세를 내야 하는데 옷을 사고 나서 그럴듯한 이유를 댄다. 알코올 중독자가 "잠이 안 와서 마셨을 뿐"이라고 한다.

            # 해리 (dissociation)
            견디기 어려운 외상 사건에서 떨어져 나온 듯 느끼며 정신적 충격을 차단하는 것이다.
            예: 학대 피해자가 자기 몸 밖에서 상황을 지켜보는 것처럼 느낀다.
            """#
        ),
        // 2026-73 아래에 붙은 설명
        TopicGuide(
            topics: ["치료적 의사소통"],
            title: "치료적 의사소통 정리",
            body: #"""
            치료적 의사소통은 대상자가 자신의 생각과 감정을 표현하고, 문제를 이해하고, 스스로 해결 방법을 찾도록 돕는 목적 있는 의사소통이다. 간호사는 비판단적이고 수용적인 태도로 대상자에게 초점을 맞춘다.

            # 국시 출제 경향
            - 2020~2026년에 **9문항**이 나왔다(매년, 2020년과 2026년은 2문항). 대개 2교시 73·74번 자리이고, 2020년에는 94번에도 나왔다.
            - **사례에서 치료적 반응 고르기**(4문항)
              - 2026-73 재활치료가 효과 없다며 거부하는 축구 선수 → **"잘 회복되지 않는 것 같아 낙심하셨군요"(감정반영)**
              - 2023-74 퇴원을 거부당하자 담당의사를 탓하며 화내는 환자 → **"퇴원이 되지 않아 속상하시군요"(감정반영)**
              - 2020-94 사고에서 혼자 살아남아 죄책감에 시달리는 대상자 → **감정과 생각을 더 말하도록 격려한다**
              - 2020-74 "제 인생은 무의미해요"라며 우는 55세 여자 → **"인생이 의미가 없다고 느끼시는군요"(감정반영)**
            - **지정된 기법에 맞는 말 고르기**(3문항)
              - 2026-74 졸려서 약을 끊은 조현병 환자에게 정보제공하기 → **약물의 효과와 부작용을 설명한다**
              - 2022-74 개방적 질문 → **"오늘은 기분이 어떠세요?"**
              - 2021-74 CT 검사를 앞두고 불안한 환자에게 감정반영 → **"겁이 나고 걱정이 되시는군요"**
            - **기법 이름 맞히기**(2문항)
              - 2025-73 모호한 표현을 확인하거나 언어화하도록 하는 기법 → **명료화**
              - 2024-73 "면접 결과가 나쁠까 봐 불안하군요" → **반영하기**
            - 오답 보기의 구성
              - 2026-73, 2020-74: "힘내세요", "용기를 잃지 마세요", "모든 것이 다 잘 될 거예요"처럼 **상투적 격려와 근거 없는 안심**을 섞는다.
              - 2026-74, 2023-74: "왜 중단하셨나요?", "왜 퇴원이 안 되겠어요?"처럼 **'왜' 질문**을 넣는다.
              - 2023-74: "담당 선생님은 훌륭한 분이세요"처럼 **의사 옹호**로 논쟁을 만든다.
              - 2020-74, 2020-94, 2023-74: 아침식사 묻기, 미래 계획 세우기, 요법 참여 권유처럼 **주제 바꾸기**를 섞는다.
              - 2026-74, 2021-74: 다른 기법(감정반영, 탐색, 정보제공)을 정답 기법 옆에 나란히 둔다.
            - 9문항 중 **5문항**(2026-73, 2024-73, 2023-74, 2021-74, 2020-74)의 정답이 감정반영(반영하기)이다. 나머지 사례형인 2020-94도 감정 표현을 격려하는 보기가 정답이다.

            # 풀이 요령
            - 사례형 문항은 대상자 말 속의 감정을 이름 붙여 되돌려 주는 보기, 곧 **"~하시는군요", "~하셨군요"** 꼴을 먼저 고른다.
            - 비치료적 표현을 먼저 지운다.
              - "힘내세요", "잘 될 거예요", "걱정하지 마세요" → 상투적 격려, 거짓 안심
              - "왜 ~했어요?" → 방어를 일으키는 질문
              - 병원 자랑, 의사 옹호, 훈계 → 감정 무시
              - 식사·계획·요법 이야기로 넘어감 → 주제 바꾸기
            - 기법을 지정한 문항은 그 기법의 정의에 맞는 보기만 고른다.
              - 감정을 되돌려 줌 → 반영하기
              - 모호한 말을 분명히 하도록 물음 → 명료화
              - 필요한 사실(약의 효과·부작용)을 알려 줌 → 정보제공
              - '예/아니요'로 답할 수 없는 질문 → 개방적 질문
            - 죄책감이나 고통을 말하는 대상자에게는 잊으라거나 기뻐하라고 하지 않고 **감정을 더 표현하도록 격려**한다.

            # 치료적 기법

            # 경청 (active listening)
            대상자의 말과 비언어적 표현에 주의를 기울여 듣는 것이다. 모든 기법의 바탕이 된다.

            # 침묵 (silence)
            말하지 않고 곁에 있으면서 대상자가 생각을 정리하고 감정을 느낄 시간을 주는 것이다.
            국시: 2025-87 (딸의 자살 소식 후 말없이 우는 환자 곁에 함께 있어 준다)

            # 수용 (accepting)
            동의하지 않더라도 대상자의 말을 판단 없이 받아들이고 있음을 보여 주는 것이다.
            예: "네, 그러셨군요."

            # 감정반영 (reflecting feelings)
            대상자의 말 속에 담긴 감정을 알아차려 말로 되돌려 주는 것이다. 대상자는 자신의 감정을 인식하고, 이해받는다고 느낀다.
            예: "재활치료를 받아도 잘 회복되지 않는 것 같아 낙심하셨군요."
            국시: 2026-73, 2024-73, 2023-74, 2021-74, 2020-74

            # 내용반영·재진술 (restating)
            대상자가 한 말의 핵심 내용을 간호사의 말로 다시 표현하는 것이다.

            # 명료화 (clarification)
            모호하거나 불분명한 표현을 더 분명하게 말하도록 돕는 것이다.
            예: "그 말씀은 어떤 의미인가요?"
            국시: 2025-73

            # 개방적 질문 (open-ended question)
            '예/아니요'로 답할 수 없어 대상자가 자유롭게 말하게 하는 질문이다.
            예: "오늘은 기분이 어떠세요?"
            국시: 2022-74

            # 탐색 (exploring)
            대상자가 꺼낸 주제를 더 깊이 이야기하도록 이끄는 것이다.
            예: "지금 어떤 감정이나 생각이 드는지 좀 더 말해 보세요."
            국시: 2020-94 (친구를 잃고 혼자 살아남은 대상자의 죄책감)

            # 초점 맞추기 (focusing)
            여러 주제로 흩어지는 대화를 하나의 중요한 주제에 집중시키는 것이다. 조증 환자에게는 한 번에 한 가지 주제로 이야기한다.

            # 정보제공 (giving information)
            대상자가 알아야 할 사실을 알려 주어 스스로 판단하게 돕는 것이다.
            예: "약물의 효과와 부작용을 설명해 드리겠습니다."
            국시: 2026-74

            # 현실제시 (presenting reality)
            환각이나 망상이 있는 대상자에게 간호사가 지각하는 현실을 간단히 알려 주는 것이다. 논쟁하지 않고, 대상자의 괴로움에는 공감한다.
            예: "저는 냄새를 느끼지 않지만 그 냄새 때문에 힘드시겠어요."
            국시: 2026-84, 2023-86, 2022-84, 2020-85

            # 직접적 질문 (자살 사정)
            죽음을 암시하는 말에는 자살에 대해 분명하게 묻는다. 묻는다고 자살 위험이 높아지지 않는다.
            예: "자살을 생각하고 있나요?"
            국시: 2025-81, 2023-82

            # 요약 (summarizing)
            면담에서 나눈 주요 내용을 정리해 확인하는 것이다. 면담의 끝이나 종결 단계에서 쓴다.

            # 비치료적 의사소통

            # 근거 없는 안심 (false reassurance)
            예: "모든 것이 다 잘 될 거예요." "검사는 30분밖에 안 걸리니 걱정하지 마세요."

            # 상투적 격려·충고
            예: "용기를 잃지 마세요." "조금만 더 힘내세요." "긍정적인 마음을 가지세요."

            # '왜' 질문
            대상자를 방어적으로 만든다.
            예: "약물 복용을 왜 중단하셨나요?"

            # 주제 바꾸기
            대상자의 감정을 피하는 것이다.
            예: "오늘 아침식사는 잘 하셨어요?" "지금 요법이 진행 중인데 참여하는 것은 어떨까요?"

            # 비난·훈계·판단
            예: "축구 선수라면서 왜 이렇게 끈기가 부족하세요?" "부정적인 이야기는 하지 마세요."

            # 논쟁·설득·부정
            망상이나 환각에 대해 사실이 아니라고 따지거나 증명을 요구하는 것이다.
            예: "병동에서 그런 냄새가 날 리가 없어요." "그 생각은 사실이 아니라고 말씀드렸잖아요."

            # 동의·동조
            망상이나 환각을 사실처럼 인정하는 것이다.

            # 다른 사람 옹호하기
            대상자의 불만을 들으면서 다른 사람 편을 드는 것이다.
            예: "담당 선생님은 훌륭한 분이세요."

            # 주제와 무관한 자랑
            예: "우리 병원 재활치료는 전국에서 최고 수준입니다."
            """#
