        // 2026-75 아래에 붙은 설명
        TopicGuide(
            topics: ["정신상태검사와 사정 영역"],
            title: "정신간호 사정 영역의 분류",
            body: #"""
            정신간호 사정은 대상자를 신체·심리·사회·문화·영적 측면에서 전인적으로 파악하는 것이다. 교재마다 묶는 방식은 조금 다르지만, 대개 아래 영역으로 나누어 사정한다.

            # 국시 출제 경향
            - 2020~2026년에 **4문항**이 나왔다(2021, 2023년, 2026년 2문항). 2교시 75·76번 자리이다.
            - **속담 해석으로 추상적 사고 평가**(2문항)
              - 2026-75 "발 없는 말이 천 리 간다"를 "발이 없는데 말이 어떻게 가요?"로 답함 → **추상사고가 손상됨**
              - 2021-75 "낫 놓고 기역 자도 모른다"를 해석하게 하는 목적 → **추상적 사고능력**
            - **질문으로 사정 영역 가리기**(2문항)
              - 2026-76 외국인 환자에게 모국의 전통적 신념과 건강관리 방법을 묻는다 → **문화**
              - 2023-76 길에서 주민등록증을 주웠다면 어떻게 하겠느냐고 묻는다 → **판단력**
            - 오답 보기의 구성
              - 2026-75: 병식 손상, 실인증, 보속증, 사고비약처럼 **다른 정신상태 이상 소견**을 섞는다.
              - 2023-76, 2021-75: 정서, 기억, 집중력, 지남력, 통찰력, 판단력처럼 **정신상태검사의 다른 항목**을 서로 바꿔 넣는다.
              - 2026-76: 인지, 정서, 행동, 지지체계처럼 **다른 사정 영역**을 섞는다.
            - 속담 문항은 두 번 나왔고, 한 번은 평가 목적(2021-75)을, 한 번은 구체적으로 답한 결과 해석(2026-75)을 묻는다.

            # 풀이 요령
            - 질문 방법과 평가 영역을 짝지어 외운다.
              - 속담·격언 해석 → 추상적 사고
              - 가상 상황에서 어떻게 할지 물음 → 판단력
              - 자기 병을 인식하는지 → 병식(통찰력)
              - 시간·장소·사람 → 지남력
              - 100에서 7 빼기 → 집중력과 계산능력
              - 최근·과거 사건 회상 → 기억
            - 속담을 문자 그대로 해석하면 **구체적 사고**, 곧 추상사고 손상이다. 조현병, 치매, 지적장애에서 나타난다.
            - 전통적 신념, 민간요법, 종교, 건강에 대한 믿음을 묻는 질문은 **문화** 사정이다.
            - 증상 용어를 구별한다. 같은 말 반복은 보속증, 주제가 빠르게 넘어가면 사고비약, 대상을 알아보지 못하면 실인증이다.

            # 1. 신체(생리) 영역
            현재의 신체 질환, 복용 약물, 수면, 식사·영양, 배설, 활동, 물질 사용(알코올, 약물)을 사정한다. 정신 증상이 신체 질환이나 약물 때문일 수 있으므로 먼저 확인한다.

            # 2. 정신상태검사 영역
            면담하면서 현재의 정신 상태를 관찰하고 질문해 평가한다.

            # 외모와 행동
            옷차림, 위생, 표정, 자세, 눈맞춤, 정신운동 활동(초조, 지연), 면담 태도를 본다.

            # 언어
            말의 속도, 양, 크기, 억양을 본다. 언어압박(조증), 언어빈곤(음성증상)이 여기에 해당한다.

            # 정서 (기분과 정동)
            기분은 대상자가 말하는 지속적인 감정 상태이다. 정동은 간호사가 관찰하는 감정 표현으로, 둔마·부적절·불안정 등을 본다.

            # 사고
            - 사고 형태·흐름: 우원증, 사고이탈, 사고비약, 연상이완, 보속증, 사고차단 등
            - 사고 내용: 망상, 강박사고, 자살·타살 사고 등

            # 지각
            환각(외부 자극 없이 지각)과 착각(실제 자극을 잘못 지각), 이인증, 비현실감을 본다.

            # 인지 (감각과 인지)
            - 의식 수준: 명료, 기면, 혼미, 혼수
            - 지남력: 시간, 장소, 사람
            - 기억: 즉각, 최근, 과거 기억
            - 주의와 집중: 100에서 7 빼기 등
            - 추상적 사고: 속담 해석. "발 없는 말이 천 리 간다"를 문자 그대로 풀면 구체적 사고이다.
            - 지능과 일반 상식

            # 판단력
            가상 상황을 제시하고 어떻게 하겠는지 묻는다.
            예: "길에서 주민등록증을 주웠다면 어떻게 하시겠어요?"

            # 병식 (통찰력)
            자신이 병이 있고 치료가 필요하다는 것을 아는 정도를 본다.

            # 3. 심리사회 영역
            - **대인관계와 지지체계**: 가족, 친구, 이웃 등 도움을 받을 수 있는 사람과 자원
            - **스트레스와 대처**: 최근의 스트레스원, 대처 방식, 방어기제
            - **자아개념**: 자존감, 신체상, 역할
            - **발달 단계**: 나이에 맞는 발달 과업을 이루었는지
            - **사회경제 상태**: 직업, 경제 상황, 주거, 교육

            # 4. 문화·영적 영역
            - **문화**: 출신 문화, 언어, 건강과 질병에 대한 믿음, 민간요법, 전통적 건강관리 방법
            - **영적**: 종교, 삶의 의미, 희망

            # 5. 위험 사정
            - **자살 위험**: 자살 사고, 계획, 수단, 과거 시도, 경고 신호. 직접 묻는다.
            - **폭력 위험**: 타인에 대한 공격성, 과거 폭력력, 전조 행동
            - **학대·방임**: 가정폭력, 아동·노인 학대의 징후
            """#
        ),
        // 2026-77 아래에 붙은 설명
        TopicGuide(
            topics: ["환경요법과 활동요법"],
            title: "환경요법 (milieu therapy)",
            body: #"""
            환경요법은 병동의 물리적 환경과 사람들 사이의 관계, 일상생활 전체를 치료 도구로 활용하는 방법이다. 대상자는 병동 생활 안에서 다른 사람과 어울리고, 책임을 나누고, 새로운 대처 방식을 배우며 사회에 복귀할 준비를 한다. 간호사는 24시간 병동에 머무는 사람으로서 치료적 환경을 만들고 유지하는 핵심 역할을 맡는다.

            # 국시 출제 경향
            - 2020~2026년에 **4문항**이 나왔다(2020, 2022, 2025, 2026년). 모두 2교시 77번 자리이다.
            - **안전이 가장 우선**이라는 문항이 2번 나왔다.
              - 2026-77 환경요법을 적용할 때 우선 고려할 것 → **안전**
              - 2022-77 치료적 환경의 물리적 환경에서 중요한 요소 → **안전과 보호**
            - **환자 참여와 민주적 운영**(1문항)
              - 2025-77 "10시 취침은 너무하다, 자정까지 자유롭게 해 달라"는 환자에게 → **"내일 병동모임에서 이 문제를 제안할 수 있습니다."**
            - **활동요법**(1문항)
              - 2020-77 음악·미술로 에너지를 건설적인 방향으로 이끄는 중재 → **활동치료**
            - 오답 보기의 구성
              - 2026-77·2022-77: 면회, 수면, 의복, 활동요법 / 지지, 민주성, 환자 권익, 직원 상호작용처럼 **환경요법의 다른 요소**를 섞는다. 모두 중요하지만 **물리적 환경에서 먼저 오는 것은 안전**이다.
              - 2025-77: 규칙을 무조건 따르라(권위적), 대답을 피함(회피), 다른 환자를 들어 훈계(비난), 혼자만 예외 허용(일관성 깨짐)
              - 2020-77: 보완대체요법, 인지행동치료, 사회기술훈련, 일상생활기술훈련

            # 풀이 요령
            - "우선", "물리적 환경"이 나오면 **안전**을 고른다.
            - 병동 규칙에 대한 불만이나 요구에는 **병동모임(환자자치회)에서 함께 논의**하게 하는 반응을 고른다. 무조건 따르게 하거나 한 사람만 예외를 허용하는 반응은 오답이다.
            - 음악, 미술, 운동, 작업처럼 **활동을 치료 도구로 쓰는 것**은 활동요법(활동치료)이다.

            # 1. 치료적 환경의 구성

            # 물리적 환경
            가장 중요한 것은 **안전과 보호**이다. 자살, 자해, 폭력 위험이 있는 대상자가 머무는 공간이기 때문이다.
            - 위험 물품(끈, 날카로운 물건, 유리)을 없앤다.
            - 깨지지 않는 유리와 관찰하기 쉬운 구조를 갖춘다.
            - 적절한 조명, 쾌적하고 조용한 공간, 사생활을 지킬 수 있는 공간을 마련한다.
            - 개인 소지품을 허용해 편안함을 준다.

            # 심리사회적 환경
            지지, 민주적 참여, 개방적 의사소통, 직원들 간의 상호작용, 환자의 권익 보장이 해당한다.
            국시 2022-77은 "물리적 환경에서 중요한 요소"를 묻고, 정답은 **안전과 보호**이다. 지지, 민주성, 환자의 권익체계, 직원 간 상호작용은 심리사회적 환경의 요소라서 오답이다.

            # 2. 환경요법의 원리

            # 안전이 최우선이다
            신체적·심리적 안전이 확보된 뒤에야 면회, 수면, 의복, 활동요법 같은 다른 치료적 요소가 의미를 가진다.
            국시: 2026-77 (환경요법에서 우선적으로 고려할 것 → 안전)

            # 환자의 참여와 자율성, 민주적 운영
            대상자가 병동 운영과 의사결정에 참여하게 한다. 규칙에 대한 불만이나 요구는 **병동모임(환자자치회)**에서 함께 논의한다. 이렇게 하면 규칙의 일관성을 지키면서 대상자의 책임감과 자율성도 키울 수 있다.
            국시: 2025-77 (10시 취침 규칙에 불만을 말하는 환자 → "내일 열리는 병동모임에서 이 문제를 제안할 수 있습니다")

            # 일관성과 구조
            일과표, 병동 규칙, 제한설정을 모든 직원이 일관되게 적용한다. 예측할 수 있는 환경이 불안을 줄인다. 한 사람에게만 예외를 두면 규칙이 무너지고, 조종 행동이 강화된다.

            # 개방적 의사소통
            대상자와 직원, 대상자끼리 감정과 생각을 솔직하게 나누도록 격려한다.

            # 사회적 학습의 기회
            병동 생활 자체가 대인관계 기술과 일상생활 기술을 연습하는 장이 된다.

            # 3. 환경요법의 다섯 가지 치료적 기능 (Gunderson)
            - **보호 (containment)**: 신체적 안전을 지키고 자기 통제를 돕는다.
            - **지지 (support)**: 대상자가 편안하고 안전하다고 느끼게 해 자존감을 높인다.
            - **구조 (structure)**: 예측할 수 있는 일과와 규칙을 제공한다.
            - **참여 (involvement)**: 병동 활동과 의사결정에 적극적으로 참여하게 한다.
            - **인정 (validation)**: 대상자를 한 개인으로 존중하고 그 경험을 인정한다.

            # 4. 환경요법에서 쓰는 활동
            - **활동치료(활동요법)**: 음악, 미술, 무용, 작업, 레크리에이션을 통해 에너지를 건설적인 방향으로 표출하게 한다. 사회성과 자존감도 높인다.
              국시: 2020-77 (음악, 미술로 에너지를 건설적으로 유도하는 중재 → 활동치료)
            - **병동모임, 집단활동**
            - **사회기술훈련, 일상생활기술훈련**

            # 5. 대상자에 따라 조절할 점
            - **조증 환자**: 자극을 줄이고, 경쟁적인 활동보다 산책처럼 에너지를 쓰는 비경쟁적 활동을 한다.
            - **공격성이 있는 환자**: 자극이 많은 곳, 경쟁적인 집단 활동, 시끄러운 음악을 피하고 분명한 제한을 둔다.
            - **우울 환자**: 혼자 지내지 않도록 소집단 활동부터 참여시킨다.
            - **섬망·치매 환자**: 자극이 적고 구조화된 환경, 적절한 조명, 시계와 달력, 일관된 간호사를 유지한다.
            """#
        ),
        // 2026-81 아래에 붙은 설명
        TopicGuide(
            topics: ["자살 위험의 사정과 중재"],
            title: "자살 위험의 사정과 중재",
            body: #"""
            자살 위험이 있는 대상자는 정신간호에서 가장 우선하는 안전 문제이다. 자살 위험이 보이면 다른 간호진단보다 **'자살행위의 위험'**이 먼저 온다.

            # 국시 출제 경향
            - 2020~2026년에 **6문항**이 나왔다(2024년을 뺀 매년 1문항). 대개 2교시 81·82번 자리이고, 2021년에는 89번에 나왔다.
            - **간접 표현에 대한 반응**(2문항)
              - 2025-81 "잠에서 깨지 않았으면 좋겠어요"라는 주요우울장애 환자 → **"자살을 의미하는 것인가요?"라고 직접 묻는다**
              - 2023-82 사고로 어머니를 잃고 "사는 것이 의미가 있을까요?"라는 대상자 → **"자살을 생각하고 있나요?"**
            - **자살 위험 인식과 우선순위**(2문항)
              - 2026-81 췌장암 환자가 장기기증을 알아보고 주변을 정리하며 수면제를 모음 → **자살행위의 위험**
              - 2021-89 자살시도를 반복한 우울 환자가 회복기에 접어듦 → **자살위험성을 사정한다**
            - **자살시도 후 입원 환자 중재**(2문항)
              - 2022-81 고부갈등으로 자살시도 후 입원한 주부 → **약물복용 시 면밀히 관찰한다**
              - 2020-82 3일 전 자살시도 후 "조용히 눈 감고 싶어요" → **위험한 물건을 확인하고 제거한다**
            - 오답 보기의 구성
              - 2025-81, 2023-82: "긍정적인 마음을 가지세요", "시간이 지나면 나아질 거예요", "기운을 내세요"처럼 **상투적 위로와 훈계**를 섞는다.
              - 2025-81, 2022-81, 2020-82: 혼자 조용히 생각할 시간, 혼자 있게 하기, 1인실 배정처럼 **고립시키는 보기**를 넣는다.
              - 2022-81, 2020-82: "규칙적인 간격으로 병동을 순회한다"를 두 번 오답으로 냈다. 순회는 불규칙하게 한다.
              - 2022-81, 2020-82: 자살 질문 피하기, 비밀보장 약속, 자유로운 외출 허용처럼 **안전을 허무는 보기**를 섞는다.
              - 2026-81, 2021-89: 신체상 혼란, 비효과적 부정, 퇴원계획, 가족치료처럼 **생명 안전보다 뒤인 진단·중재**를 둔다.

            # 풀이 요령
            - 죽음을 돌려 말하는 표현("잠에서 깨지 않았으면", "사는 게 의미가 있을까", "눈 감고 싶어요")이 나오면 **자살에 대해 직접 묻는 보기**를 고른다. 묻는다고 자살을 부추기지 않는다.
            - 주변 정리, 소유물·장기 넘겨주기, 약 모으기는 구체적 계획의 신호이다. 이때는 **자살행위의 위험**이 다른 진단보다 앞선다.
            - 우울에서 **회복기에 접어들 때** 에너지가 돌아와 자살 실행 위험이 커진다. 퇴원계획보다 자살위험성 재사정을 먼저 한다.
            - 입원 환자 안전 중재의 핵심어를 기억한다.
              - 위험한 물건(끈, 날카로운 물건, 약물) 확인·제거
              - 약을 실제로 삼키는지 관찰
              - 순회는 **불규칙하게**, 혼자 두지 않기, 외출 제한
              - 자살 생각은 비밀보장하지 않고 치료팀과 공유

            # 1. 사정

            # 직접 묻는다
            자살을 암시하는 말이 나오면 자살에 대해 직접적이고 분명하게 묻는다. 묻는다고 자살 위험이 높아지지 않는다. 오히려 대상자가 감정을 털어놓고 도움을 받는 계기가 된다.
            예: "잠에서 깨고 싶지 않다는 것은 자살을 의미하는 것인가요?", "자살을 생각하고 있나요?"
            국시: 2025-81, 2023-82

            # 간접적인 자살 암시 표현
            - "잠에서 깨지 않았으면 좋겠어요."
            - "이렇게 사는 것이 의미가 있을까요?"
            - "조용히 눈 감고 싶어요."
            - "내가 없으면 다들 편해질 거예요."

            # 구체적으로 확인할 내용
            - **자살 사고**: 얼마나 자주, 얼마나 강하게 드는가
            - **계획**: 구체적인 방법, 시기, 장소를 정했는가
            - **수단**: 약, 끈, 무기 등을 가지고 있거나 구할 수 있는가
            - **치명성**: 계획한 방법이 얼마나 위험한가
            - **과거 시도**: 이전 자살 시도가 있는가. 가장 강력한 위험 요인이다.
            계획이 구체적이고, 수단을 구할 수 있고, 방법이 치명적일수록 위험이 높다.

            # 경고 신호 (행동)
            - 주변을 정리하고 소지품을 남에게 나누어 준다.
            - 장기기증, 유서, 보험 등 죽음을 준비하는 행동을 한다.
            - 수면제 같은 약을 모아 둔다.
            - 작별 인사를 한다.
            - 심한 우울 뒤에 **갑자기 평온해진다**. 자살을 결심했다는 신호일 수 있다.
            국시: 2026-81 (췌장암 진단 후 장기기증을 알아보고 주변을 정리하며 수면제를 모아 둔 30세 남자 → 자살행위의 위험)

            # 위험 요인
            - 이전 자살 시도
            - 우울증, 양극성장애, 조현병(명령 환청), 물질 사용, 성격장애
            - 절망감과 무력감
            - 최근의 상실(사별, 이혼, 실직), 말기 질환이나 심한 통증
            - 사회적 고립, 가족의 자살력
            - 충동성, 자살 수단에 쉽게 접근할 수 있음
            - 남성과 노인(자살 사망 위험이 높음)

            # 보호 요인
            가족과 사회적 지지, 치료적 관계, 삶의 이유(자녀, 종교 등), 문제해결 능력

            # 2. 회복기의 위험
            심한 우울 상태에서는 에너지가 없어 자살을 실행하기 어렵다. 회복기에 들어서면 에너지가 먼저 돌아와 오히려 자살을 실행할 위험이 커진다. 항우울제 치료를 시작한 뒤 몇 주가 특히 위험하다. 따라서 회복기에는 자살 위험을 다시 사정해야 한다.
            국시: 2021-89 (자살시도를 반복한 우울 환자가 회복기에 접어들 때 → 자살 위험성 사정)

            # 3. 중재

            # 안전한 환경
            - 주변에서 **위험한 물건을 확인하고 없앤다**. 끈, 벨트, 날카로운 물건, 유리, 약, 비닐봉지 등이 해당한다.
            - 위험도에 따라 관찰 수준을 정한다. 위험이 높으면 **일대일로 계속 관찰**한다.
            - **혼자 두지 않는다**. 1인실보다 관찰하기 쉬운 곳에 배정한다.
            - 순회는 **불규칙한 간격**으로 한다. 규칙적으로 돌면 대상자가 감시 공백을 예측할 수 있다.
            - 외출과 외박을 제한한다.
            국시: 2020-82 (자살 시도 후 "조용히 눈 감고 싶어요" → 위험한 물건을 확인하고 제거)

            # 투약 관리
            약을 줄 때 **실제로 삼키는지 확인**한다. 약을 모아 두었다가 한꺼번에 먹을 수 있기 때문이다. 입안에 숨기지 않았는지도 본다.
            국시: 2022-81 (자살시도 후 입원한 가정주부 → 약물복용 시 면밀히 관찰)

            # 치료적 관계와 의사소통
            - 비판단적으로 경청하고, 대상자가 자살 생각과 감정을 말로 표현하도록 격려한다.
            - 자살 생각을 부정하거나 훈계하지 않는다. "그런 생각 하지 마세요", "용기를 내세요" 같은 말은 비치료적이다.
            - **비밀보장을 약속하지 않는다**. 자살 위험은 치료팀과 반드시 공유해야 한다.
            - 자살하지 않겠다는 약속(자살 금지 계약)만으로 안전을 대신할 수 없다. 관찰과 환경 관리를 함께 한다.

            # 희망과 대처 강화
            - 절망감을 다루고, 삶의 이유와 보호 요인을 함께 찾는다.
            - 현실적인 작은 목표를 세워 성취 경험을 쌓게 한다.
            - 스트레스와 위기에 대처하는 방법을 익히게 한다.

            # 가족과 지역사회 연계
            - 가족에게 경고 신호와 위험한 물건 관리를 교육한다.
            - 퇴원할 때는 위기 시 연락할 곳과 지역사회 자원을 알려 준다. 국내 자살예방상담전화는 **109**이다.
            - 자살 시도자와 유가족을 지원하는 프로그램에 연결한다.
            """#
        ),
        // 2026-82 아래에 붙은 설명
        TopicGuide(
            topics: ["폭력과 학대"],
            title: "가정폭력 피해자의 간호중재",
            body: #"""
            가정폭력 피해자에게 가장 먼저 할 일은 **가해자로부터 안전을 확보하는 것**이다.

            # 국시 출제 경향
            - 2020~2026년에 **5문항**이 나왔다(2021, 2022, 2024, 2025, 2026년). 모두 2교시 82번 자리이다.
            - **피해자의 특성**(2문항)
              - 2024-82 폭력 피해자의 특성 → **학습된 무력감**
              - 2021-82 상습적인 가정폭력 피해자의 특성 → **폭력과 관련된 침습적 생각, 공포반응**
            - **노인 학대의 유형 가리기**(2문항)
              - 2025-82 회복 정도가 제각각인 멍을 옷깃으로 숨긴다 → **신체적 학대**
              - 2022-82 아들에게 국민연금을 빼앗기고 용돈도 받지 못한다 → **경제적(물질적) 학대**
            - **피해자 간호중재**(1문항)
              - 2026-82 아내의 폭행으로 갈비뼈가 골절된 남편 → **아내로부터 안전을 확보하도록 돕는다**
            - 오답 보기의 구성
              - 2024-82: 물질 남용, 강한 소유욕, 통제감 과시, 비합리적 질투처럼 **가해자의 특성**을 섞는다.
              - 2021-82: "심리적으로 더 강해진다", "자존감을 유지한다", "다른 사람을 신뢰한다", "부당함을 인식한다"처럼 **피해자와 반대되는 모습**을 섞는다.
              - 2026-82: 대상자의 잘못 확인(비난), 공개된 장소에서 면담(사생활 침해), 증명하려고 자세히 캐묻기, 가해자에 대한 반감 표현
            - 2026-82는 **남성 피해자**가 나온 문항이다. 피해자의 성별과 관계없이 안전 확보가 먼저이다.

            # 풀이 요령
            - 피해자 특성 문항은 **학습된 무력감, 낮은 자존감, 자기 탓(죄책감), 고립, 외상 후 증상(침습·공포)**을 고른다. 소유욕·질투·통제·물질 남용은 가해자의 특성이다.
            - 노인 학대 유형은 사례의 핵심어로 가른다.
              - 설명되지 않는 멍, 회복 시기가 다른 상처, 숨기려는 행동 → 신체적 학대
              - 연금·재산·돈을 빼앗음 → 경제적(물질적) 학대
              - 폭언, 무시, 위협 → 정서적 학대
              - 돌보지 않고 방치하거나 버림 → 방임·유기
            - 중재 문항은 **안전 확보가 최우선**이다. 비난하지 않고, 사적인 공간에서 면담하고, 신고와 쉼터 같은 자원을 알려 준다.

            # 1. 피해자의 특성

            # 학습된 무력감
            반복된 폭력으로 "무엇을 해도 바꿀 수 없다"고 믿게 된다. 이 때문에 폭력적인 관계를 떠나지 못하는 경우가 많다.
            국시: 2024-82 (폭력 피해자의 특성 → 학습된 무력감)

            # 외상 반응
            폭력과 관련된 침습적 생각, 악몽, 공포 반응, 과각성 같은 외상후 스트레스 증상을 보인다.
            국시: 2021-82 (상습적 가정폭력 피해자의 특성 → 폭력과 관련된 침습적 생각, 공포 반응)

            # 그 밖의 특성
            - 자존감이 낮고, 폭력이 자기 탓이라고 여겨 죄책감과 수치심을 느낀다.
            - 우울, 불안, 물질 사용, 신체 증상을 보인다.
            - 가해자의 통제로 가족과 친구에게서 고립된다.
            - 경제적으로 의존하거나 자녀 때문에 관계를 떠나기 어렵다.
            - 부정하거나 폭력을 축소해서 말한다.

            # 참고: 가해자의 특성
            물질 남용, 강한 소유욕, 통제 욕구, 비합리적 질투는 가해자의 특성이다. 국시에서는 피해자의 특성과 섞어 오답 보기로 나온다.

            # 폭력의 순환
            가정폭력은 흔히 세 단계를 되풀이한다.
            - 긴장 형성기: 사소한 폭력과 긴장이 쌓인다.
            - 폭발기: 심한 폭력이 일어난다.
            - 화해기(밀월기): 가해자가 사과하고 잘해 준다. 피해자는 다시는 폭력이 없을 것이라 믿게 된다.
            이 순환이 반복될수록 간격이 짧아지고 폭력이 심해진다.

            # 2. 사정
            - **가해자와 분리된 사적인 공간에서** 면담한다. 공개된 장소나 가해자가 있는 자리에서는 묻지 않는다.
            - 비판단적이고 직접적으로 묻는다. 예: "집에서 누군가 당신을 다치게 한 적이 있나요?"
            - 설명과 맞지 않는 손상을 확인한다. 회복 정도가 서로 다른 멍, 얼굴·목·가슴·팔의 상처, 반복된 방문 등이 해당한다.
            - 손상과 대상자의 말을 객관적으로 **기록**한다. 나중에 법적 증거가 될 수 있다.
            - 현재의 **위험도**를 평가한다. 폭력이 심해지는지, 무기가 있는지, 목을 조른 적이 있는지, 살해 위협이 있었는지, 자녀도 위험한지를 확인한다.
            - 대상자의 자살 위험도 함께 사정한다.

            # 3. 간호중재

            # 안전 확보가 최우선이다
            - 가해자로부터 즉각적인 안전을 확보하도록 돕는다.
            - **안전 계획**을 함께 세운다. 위험할 때 피할 장소, 연락할 사람, 미리 챙겨 둘 물건(신분증, 돈, 약, 중요 서류)을 정한다.
            - 경찰(112), 여성긴급전화(1366), 가정폭력상담소, 보호시설(쉼터)을 안내한다.
            국시: 2026-82 (아내의 폭행으로 갈비뼈가 골절된 대상자 → 아내로부터 안전을 확보하도록 돕는다)

            # 치료적 관계와 태도
            - 비판단적이고 수용적인 태도를 보인다.
            - **"당신 잘못이 아니다"**라는 것을 알려 죄책감을 덜어 준다. 대상자의 잘못을 확인하거나 따지지 않는다.
            - 대상자가 감정을 말로 표현하도록 돕는다.
            - 가해자에 대한 간호사 자신의 반감이나 분노를 표현하지 않는다.
            - 증명하려고 캐묻지 않는다. 자세한 추궁은 대상자에게 다시 상처를 준다.

            # 대상자의 결정 존중
            관계를 떠날지 말지는 대상자가 결정한다. 당장 떠나지 않더라도 비난하지 않고, 필요할 때 도움을 받을 수 있다는 것을 알려 둔다. 떠나는 시점이 가장 위험할 수 있다는 점도 함께 알린다.

            # 신고와 연계
            - 의료인은 직무 중 가정폭력을 알게 되면 수사기관에 신고할 의무가 있다(가정폭력처벌법).
            - 자녀가 폭력에 노출되었다면 아동학대로도 신고한다.
            - 법률 지원, 의료 지원, 상담, 쉼터 같은 지역사회 자원에 연계한다.

            # 회복 지원
            자존감을 회복하고, 무력감에서 벗어나 스스로 결정할 수 있다는 느낌을 되찾도록 돕는다. 외상 증상이 있으면 정신건강 치료에 연계한다.

            # 4. 관련 주제: 노인학대
            노인학대도 같은 원리로 접근한다. 신체적 학대(회복 정도가 다른 멍을 숨김), 경제적 학대(연금을 빼앗음), 정서적 학대, 방임, 유기를 구별하는 문항이 나온다. 신고는 노인보호전문기관(1577-1389)에 한다.
            국시: 2025-82 (신체적 학대), 2022-82 (경제적 학대)
            """#
        ),
        // 2026-83 아래에 붙은 설명
        TopicGuide(
            topics: ["망상이 있는 환자의 중재"],
            title: "망상이 있는 환자의 간호중재",
            body: #"""
            망상은 사실과 다르고, 논리로 설득해도 바뀌지 않는 고정된 잘못된 믿음이다. 간호의 핵심은 **망상과 논쟁하지 않고, 망상 밑에 있는 감정에 공감하며, 현실과 안전을 제시하는 것**이다.

            # 국시 출제 경향
            - 2020~2026년에 **9문항**이 나왔다(2023년을 뺀 매년, 2021·2024·2026년은 2문항). 대개 2교시 86번 자리이고, 83~85번에도 나왔다.
            - **망상 표현에 대한 반응**(5문항)
              - 2025-86 "형사들이 여기까지 와서 감시해요" → **병원이 안전하다고 알리고 논쟁하지 않는다**
              - 2024-86 "대통령이 될 사람이라 모두 나를 해치려 해요" → **"불안하시군요. 여기 병원은 안전해요."**
              - 2021-85 "국가정보기관이 감시해요, 숨겨 주세요" → **"매우 두렵겠네요. 여기는 병원이라 안전합니다."**
              - 2021-84 같은 병실 환자가 해칠 것 같다며 병실을 바꿔 달라고 함 → **사실보다 그 상황의 감정에 공감한다**
              - 2020-86 병실에 도청장치가 있다며 불안해함 → **불안해하는 느낌에 초점을 맞춘다**
            - **망상 환자 간호의 일반 원칙**(3문항)
              - 2026-86 주변 사람들이 해치려 한다는 망상 → **갑작스러운 신체 접촉을 하지 않는다**
              - 2024-85 망상을 가진 조현병 환자 → **망상에 대해 논쟁하지 않는다**
              - 2022-86 감시당한다는 망상으로 어울리지 않음 → **약속을 잘 지켜 신뢰를 형성한다**
            - **독이 있다며 식사 거부**(1문항)
              - 2026-83 병원 음식에 독이 있다며 거부 → **포장된 음식을 직접 개봉해 먹게 한다**
            - 오답 보기의 구성
              - 2025-86, 2024-85, 2022-86, 2021-84, 2020-86: "사실이 아니라고 설득한다", "논리적으로 설명한다", "생각을 단념시킨다"처럼 **논리적 설득**을 거의 매번 넣는다.
              - 2026-83, 2025-86, 2021-84: "증명해 보라고 한다", "근거를 제시하도록 한다"처럼 **증명 요구**를 섞는다.
              - 2025-86, 2024-86, 2021-85, 2020-86: "누가, 언제, 어떻게 감시하죠?", "망상 내용에 초점을 두고 캐묻는다"처럼 **망상 내용 탐색**을 넣는다.
              - 2026-86, 2022-86: 속삭이기, 귓속말, 신체접촉으로 안심시키기처럼 **의심을 키우는 행동**을 섞는다.
              - 2022-86, 2020-86: 망상에 맞장구치기, 도청장치를 같이 찾아보기처럼 **망상에 동조**하는 보기를 둔다.
            - 반응형 5문항의 정답은 모두 **감정(불안·두려움) 인정 + 안전한 현실 제시** 꼴이다.

            # 풀이 요령
            - 망상 문항은 **논쟁하지 않고, 동조하지도 않고, 밑에 깔린 감정에 초점**을 두는 보기를 고른다.
            - 반응을 고를 때는 "두렵겠네요", "불안하시군요" 같은 감정 인정과 "여기 병원은 안전해요" 같은 현실 제시가 함께 있는 보기를 찾는다.
            - 다음 핵심어가 보이면 지운다.
              - 설득, 설명, 단념, "그럴 리가 없어요" → 논쟁
              - 증명, 근거 제시 → 논쟁
              - 누가·언제·어떻게, 캐묻기, 내용에 초점 → 망상 강화
              - 맞장구, 같이 찾아보기 → 동조
              - 귓속말, 속삭임, 갑작스러운 접촉 → 의심과 공격 유발
            - 피해망상 환자에게는 약속 지키기와 일관된 태도로 **신뢰**를 먼저 쌓는다. 입원 초기에는 집단치료나 경쟁활동보다 일대일 관계가 먼저이다.
            - 독 망상으로 식사를 거부하면 **밀봉·포장 음식을 스스로 개봉**하게 한다. 들고 다니며 먹는 음식은 조증 환자용이다.

            # 1. 망상의 종류
            - **피해망상**: 다른 사람이 자신을 해치거나 감시한다고 믿는다. 가장 흔하다.
              예: "누군가 음식에 독을 탔어요", "국가정보기관이 저를 감시해요"
            - **관계망상**: 자신과 관계없는 일을 자신과 관련된 것으로 해석한다.
              예: "아나운서가 나에 대해 이야기해요", "지나가는 사람들이 모두 나에 대해 수군거려요"
            - **과대망상**: 자신이 특별한 능력, 지위, 지식을 가졌다고 믿는다. 조증에서 흔하다.
              예: "내가 대통령이 될 사람이에요", "세상이 깜짝 놀랄 정보를 가지고 왔어요"
            - **허무망상·빈곤망상·죄책망상**: 우울증에서 나타난다.
            - **신체망상**: 몸에 이상이 있다고 믿는다.
            - **조종망상**: 외부의 힘이 자신을 조종한다고 믿는다.
            - **망상장애**: 망상이 1개월 이상 계속되지만 망상과 관련된 부분 말고는 행동이 뚜렷하게 기이하지 않고 기능이 비교적 유지된다.
            국시(종류 구별): 2023-75, 2022-75, 2021-83, 2020-89, 2025-85

            # 2. 중재 원칙

            # 망상과 논쟁하지 않는다
            망상이 사실이 아니라고 설득하거나, 근거를 대라고 하거나, 증명해 보라고 하지 않는다. 논쟁할수록 방어가 강해지고 망상이 더 굳어지며, 신뢰 관계가 깨진다.

            # 망상에 동조하지 않는다
            망상이 사실인 것처럼 맞장구치거나 인정하지 않는다. 도청장치를 같이 찾아보는 것처럼 망상에 맞춘 행동도 하지 않는다.

            # 망상 내용보다 감정에 초점을 둔다
            망상의 내용을 캐묻거나 망상 자체를 주제로 길게 이야기하면 망상에 더 몰두하게 된다. 대신 망상 때문에 대상자가 느끼는 불안, 두려움, 외로움에 공감한다.
            예: "그렇게 생각하니 매우 두렵겠네요."

            # 현실과 안전을 제시한다
            병원이 안전하다는 것을 알리고, 현실에 근거한 대화와 활동으로 이끈다.
            예: "불안하시군요. 여기 병원은 안전해요."
            국시: 2024-86, 2025-86, 2021-85, 2020-86, 2021-84, 2024-85

            # 3. 피해망상 환자에게 특히 중요한 점

            # 신뢰 관계 형성
            피해망상 환자는 다른 사람을 믿지 못한다. **약속을 잘 지키고**, 일관되고 정직하게 대한다. 간호사가 말한 대로 행동하는 것이 신뢰의 바탕이 된다.
            국시: 2022-86 (감시당한다는 망상으로 사람들과 어울리지 않는 환자 → 약속을 잘 지킨다)

            # 위협으로 느낄 행동을 피한다
            - **갑작스러운 신체 접촉을 하지 않는다**. 공격으로 오해해 폭력으로 이어질 수 있다. 접촉해야 할 때는 미리 설명한다.
            - 환자 앞에서 다른 사람과 **속삭이거나 웃지 않는다**. 의심을 키운다.
            - 적절한 거리를 두고, 환자를 등지거나 구석으로 몰지 않는다.
            국시: 2026-86 (갑작스러운 신체 접촉을 하지 않는다)

            # 음식에 독이 있다고 식사를 거부할 때
            망상과 논쟁하지 않고, 대상자가 안심할 수 있는 방법으로 영양을 확보한다. **밀봉·포장된 음식을 환자가 직접 개봉해서 먹게** 하면 의심을 줄일 수 있다.
            국시: 2026-83

            # 집단 활동은 서두르지 않는다
            의심이 많은 입원 초기에는 집단치료가 부담스럽다. 먼저 일대일 신뢰 관계를 만든다.

            # 4. 안전 관리
            - 망상 때문에 자신이나 남을 해칠 위험이 있는지 사정한다. 피해망상 환자는 "먼저 공격해야 한다"고 생각해 폭력적으로 행동할 수 있다.
            - 망상으로 이웃과 다투는 등 급성으로 악화되었다면 의료기관 연계(진료, 입원)가 우선이다.
              국시: 2026-79

            # 함께 보면 좋은 문항: 망상의 종류와 망상장애
            2025-85 망상장애 · 2023-75 사고장애(피해망상) · 2022-75 관계망상 · 2021-83 관계망상 · 2020-89 과대망상
            """#
        ),
        // 2026-84 아래에 붙은 설명
        TopicGuide(
            topics: ["환각이 있는 환자의 중재"],
            title: "환각이 있는 환자의 간호중재",
            body: #"""
            환각은 외부 자극이 없는데도 무언가를 지각하는 것이다. 간호의 핵심은 **간호사에게는 느껴지지 않는다는 현실을 간단히 알리면서, 환자가 겪는 괴로움에는 공감하는 것**이다.

            # 국시 출제 경향
            - 2020~2026년에 **6문항**이 나왔다(2024년을 뺀 매년 1문항). 대개 2교시 84번 자리이고, 85·86번에도 나왔다.
            - **환각 호소에 현실제시와 공감**(4문항)
              - 2026-84 "시체 썩는 냄새가 나죠?"라고 묻는 환자 → **"저는 냄새를 느끼지 않지만 그 냄새 때문에 힘드시겠어요"**
              - 2023-86 "욕하는 소리가 들리지 않아요?"라고 묻는 환자 → **들리지 않는다고 말하고 불편감에 공감한다**
              - 2022-84 사람들이 싸우는 소리가 들린다고 호소 → **사실이 아니지만 괴로운 경험임을 공감한다**
              - 2020-85 귀에서 삐 소리가 계속 들린다고 호소 → **들리는 소리가 실제가 아님을 말해 준다**
            - **환청 환자의 활동과 사정**(2문항)
              - 2025-84 욕하는 소리가 두려워 병실에서 나오지 않음 → **현실에 기반을 둔 활동에 참여시킨다**
              - 2021-86 허공에 혼잣말하고 손짓하며 배회 → **들리는 소리가 있는지 직접 물어본다**
            - 오답 보기의 구성
              - 2026-84, 2025-84, 2023-86, 2022-84: "그런 냄새가 날 리가 없어요", 사실 여부 논쟁, 논리적 근거로 설득처럼 **논쟁·부정**을 넣는다.
              - 2025-84, 2023-86: 환청이 실재인 것처럼 대하기, 소리가 들린다며 인정하기처럼 **환각에 동조**하는 보기를 둔다.
              - 2023-86, 2022-84, 2020-85: "주 증상이므로 신경 쓰지 않는다", "별일 아니라고 무시한다"처럼 **무시**를 섞는다.
              - 2022-84, 2021-86, 2020-85: 혼자 있게 하기, 조용한 곳에 혼자 두기처럼 **고립**을 넣는다.
              - 2023-86, 2020-85: 위험 행동이 없는데 **억제대 적용**을 섞는다.
              - 2025-84, 2020-85: 환청 내용을 말하지 못하게 하거나 초기에 확인하지 않기처럼 **내용 사정을 막는 보기**를 둔다.

            # 풀이 요령
            - 환각 문항의 정답 공식은 **"나는 느끼지 않는다(현실제시) + 당신은 힘들겠다(공감)"**이다. 두 요소가 함께 있는 보기를 먼저 찾는다.
            - 환각을 인정하지도, 논쟁하지도 않는다. "들린다", "날 리가 없다", "논리적으로 설득"은 모두 오답이다.
            - 혼잣말, 허공에 손짓, 무언가를 듣는 듯한 행동이 보이면 **"무슨 소리가 들리세요?"라고 직접 묻는다**. 명령 환청 여부를 알아야 안전을 지킨다.
            - 환청 내용은 초기부터 확인하고, 말하지 못하게 하지 않는다.
            - 혼자 두기, 무시, 억제대, 경쟁 활동은 지우고 **현실에 기반한 활동**(대화, 산책, 작업)을 고른다.

            # 1. 환각의 종류와 구별

            # 환각의 종류
            - **환청**: 가장 흔하다. 욕하는 소리, 명령하는 소리, 사람들이 대화하는 소리 등이 들린다.
            - **환시**: 섬망, 알코올 금단(진전섬망), 환각제 사용에서 흔하다.
            - **환후·환미**: 이상한 냄새나 맛을 느낀다. 예: 시체 썩는 냄새
            - **환촉**: 피부 위로 벌레가 기어가는 느낌 등이다. 알코올 금단, 자극제 사용에서 나타난다.

            # 착각과의 구별
            착각은 실제로 있는 자극을 잘못 지각하는 것이다. 흔들리는 나뭇잎을 귀신으로 보거나, 벽지 무늬를 뱀으로 보는 것이 예이다. 외부 자극이 없는데 지각하면 환각, 실제 자극을 잘못 보면 착각이다.
            국시: 2025-100, 2020-75 (착각), 2024-75 (벽을 보며 "나를 욕하지 마!" → 환각)

            # 2. 사정

            # 환각의 징후를 관찰한다
            혼잣말, 허공에 대고 말하거나 손짓하기, 무언가를 듣는 듯 고개를 기울이기, 갑자기 웃거나 화내기, 귀를 막기 등이 있다.

            # 직접 묻는다
            환각이 의심되면 "지금 무슨 소리가 들리세요?"처럼 직접 묻는다.
            국시: 2021-86 (허공에 혼잣말하고 손짓하며 배회하는 환자 → 들리는 소리가 있는지 직접 물어본다)

            # 내용을 확인한다, 특히 명령 환청
            "죽으라", "저 사람을 때려라" 같은 명령 환청은 자해나 폭력으로 이어질 수 있다. 그래서 환청의 내용을 초기부터 확인해야 한다. 내용을 말하지 못하게 하거나 확인하지 않는 것은 잘못이다.

            # 위험도를 평가한다
            환각에 반응해 자신이나 남을 해치려 하는지 본다. 환청 때문에 이미 다른 사람에게 주먹을 휘두른다면 우선 간호진단은 **'타인에 대한 폭력의 위험'**이다.
            국시: 2022-83

            # 3. 중재 원칙

            # 현실을 간단히 제시한다
            간호사에게는 그 소리나 냄새가 느껴지지 않는다는 것을 간단하고 분명하게 알린다. 환각을 인정하지 않는다.
            예: "저는 그 소리가 들리지 않아요."

            # 괴로움에 공감한다
            환자에게 환각은 실제로 겪는 괴로운 경험이다. 그 감정을 인정하고 공감한다.
            예: "저는 냄새를 느끼지 않지만 그 냄새 때문에 힘드시겠어요."
            예: "환청은 사실이 아니지만 환자분이 겪는 괴로운 현상이라는 것은 알아요."
            국시: 2026-84, 2023-86, 2022-84, 2020-85

            # 논쟁하지 않는다
            소리가 사실인지 아닌지 따지거나, 논리적인 근거를 대며 설득하지 않는다.

            # 혼자 두지 않고 현실에 기반한 활동에 참여시킨다
            혼자 있으면 환각에 더 몰두한다. 대화, 산책, 작업 같은 현실에 기반한 활동에 참여시켜 환각에 쏠린 주의를 돌린다. 이때 경쟁적인 활동은 긴장을 높이므로 피한다.
            국시: 2025-84 (욕하는 소리가 들려 두렵다며 병실에서 나오지 않는 환자 → 현실에 기반을 둔 활동에 참여시킨다)

            # 환각에 대처하는 방법을 가르친다
            증상이 조금 안정되면 대처 방법을 함께 찾는다. 다른 사람과 이야기하기, 음악 듣기, 흥얼거리기, 소리에게 "그만"이라고 말하기, 간호사에게 알리기 등이 있다. 규칙적인 약물 복용이 중요하다는 것도 교육한다.

            # 알아듣지 못한 말은 솔직하게 말한다
            환자가 알아듣기 힘든 말을 할 때 이해한 척하지 않는다. 이해하지 못했다고 솔직히 말해야 신뢰가 유지된다.

            # 함께 보면 좋은 문항
            - 2024-75: 환각(증상 이름)
            - 2025-100, 2020-75: 착각
            - 2022-83: 환청과 폭력 위험
            """#
        ),
        // 2026-87 아래에 붙은 설명
        TopicGuide(
            topics: ["우울장애"],
            title: "우울증 환자의 간호중재",
            body: #"""
            우울증 환자 간호에서 가장 먼저 할 일은 **자살 위험 사정과 안전 확보**이다. 그 위에서 곁에 있어 주며 신뢰를 쌓고, 작은 성취를 통해 자존감을 회복하게 하고, 영양·수면·자기돌봄 같은 기본 욕구를 채워 준다.

            # 국시 출제 경향
            - 2020~2026년에 **11문항**이 나왔다(매년, 2020·2022·2023·2026년은 2문항). 모두 2교시 87·88번 자리이다.
            - **간호진단 고르기**(4문항)
              - 2024-88 "내가 할 수 있는 건 아무것도 없어요"라며 종일 누워 지냄 → **무력감**
              - 2023-87 활동요법이 뜻대로 안 되자 "잘하는 게 하나도 없어요" → **상황적 자존감 저하**
              - 2022-87 '사회적 고립'을 내릴 수 있는 행동 → **대화가 없고 혼자 있으려고 한다**
              - 2021-87 "누가 저를 좋아하겠어요, 잘한 게 하나도 없어요" → **자존감 저하**
            - **간호중재**(4문항)
              - 2026-88 1개월에 6 kg이 빠진 식욕감퇴 환자 → **기호를 고려한 식사나 기호식품을 제공한다**
              - 2025-87 딸의 자살 소식 후 말없이 울기만 함 → **말을 하지 않더라도 함께 있어 준다**
              - 2022-88 남편 사망 후 우울증으로 입원 → **스스로 현실적인 목표를 설정하도록 돕는다**
              - 2020-88 자존감 저하 진단을 받은 환자 → **성취감을 느낄 수 있는 과제를 부여한다**
            - **증상과 질환 구별**(3문항)
              - 2026-87 주요우울장애의 주 증상 → **일상활동에 대한 흥미가 없다**
              - 2023-88 지속성 우울장애 설명 → **적어도 2년 동안 거의 매일 우울한 기분**
              - 2020-87 우울한 기분, 식욕부진, 불면, 피로가 30개월간 지속된 40세 → **지속성 우울장애**
            - 오답 보기의 구성
              - 2023-88, 2020-87: 조증삽화(양극성·순환성 장애), 월경 1주 전 우울(월경전 불쾌감장애), 주 3회 이상 분노발작(파괴적 기분조절부전장애)처럼 **다른 우울·기분장애의 기준**을 섞는다.
              - 2026-87, 2023-88: 높은 자존감, 오만한 태도, 체중증가 공포처럼 **조증이나 섭식장애의 특징**을 넣는다.
              - 2024-88, 2023-87, 2021-87: 지식부족, 사고과정장애, 만성 혼동, 방어적 대처처럼 **자료가 없는 진단**을 둔다.
              - 2022-87: 불면, 식사 거부, 머리를 감지 않기, 분노 발작처럼 **다른 진단의 근거 행동**을 섞는다.
              - 2026-88, 2025-87, 2022-88: 혼자 식사하기, 혼자 있게 하기, 입원 첫날 집단 프로그램, 대집단부터 시작처럼 **고립 또는 과한 사회적 부담**을 넣는다.
              - 2026-88, 2025-87, 2022-88, 2020-88: "걱정 말라", "울지 말라", "슬픔을 참으라", "좋은 일이 생길 것"처럼 **거짓 안심과 감정 억제**를 섞는다.
            - 자존감 저하 관련 문항이 3번(2023-87, 2021-87, 2020-88) 나왔다.

            # 풀이 요령
            - 진단 문항은 환자의 말에서 핵심어를 찾는다.
              - "할 수 있는 게 아무것도 없다", 수동적으로 누워 지냄 → 무력감
              - "잘하는 게 없다", "누가 좋아하겠어요" → 자존감 저하(특정 상황에 대한 반응이면 상황적)
              - 대화 없음, 혼자 있으려 함 → 사회적 고립
            - 지속성 우울장애는 **성인 2년 이상**의 만성 우울이다. 조증이 있으면 양극성·순환성, 월경 주기와 관련되면 월경전 불쾌감장애, 반복 분노발작이면 파괴적 기분조절부전장애이다.
            - 중재는 **작고 현실적인 목표·과제로 성취감**을 주는 보기를 고른다. 이상적 기준, 비현실적 목표, 모든 결정 요구는 오답이다.
            - 말이 없거나 울기만 하는 환자에게는 재촉하지 않고 **곁에 함께 있어 준다**. 동정, 경쾌한 음악, 울지 말라는 말은 지운다.
            - 식욕이 떨어진 환자에게는 **기호식품**을 주고 다른 사람과 함께 먹게 한다. 체중은 정해진 시간에 잰다.

            # 1. 이해를 위한 기본 내용

            # 핵심 증상
            주요우울장애의 핵심 증상은 **우울한 기분**과 **흥미나 즐거움의 상실**이다. 둘 중 하나 이상이 2주 이상 계속되어야 한다. 식욕과 체중 변화, 불면이나 과다수면, 정신운동 초조나 지연, 피로, 무가치감과 죄책감, 집중력 저하, 죽음에 대한 반복적인 생각이 함께 나타난다.
            국시: 2026-87

            # 지속성 우울장애
            성인에서 우울한 기분이 **2년 이상**, 우울한 날이 그렇지 않은 날보다 많은 만성 우울이다.
            국시: 2023-88, 2020-87

            # 생물학적 요인
            - 세로토닌과 노르에피네프린이 감소한다.
            - 코티솔은 증가한다. 시상하부-뇌하수체-부신 축이 과활성되기 때문이다.
            국시: 2025-76

            # 심리적 설명
            - 정신분석: 잃어버린 대상에 대한 분노가 자신에게로 향한다(함입). 예를 들어 아들의 입시 실패를 자기 죄 때문이라고 여긴다.
              국시: 2024-87
            - 인지이론(Beck): 자신, 세상, 미래를 부정적으로 보는 인지 삼제와 인지왜곡이 우울을 만든다. 과잉일반화, 흑백논리, 예언자적 오류가 대표적이다.

            # 2. 간호진단: 대상자의 말에서 찾는다
            - **자살행위의 위험**: "잠에서 깨지 않았으면 좋겠어요", 약을 모아 둠. **가장 우선**한다.
            - **상황적 자존감 저하**: 특정 상황에 반응해 자신을 부정적으로 평가하는 것이다.
              예: 활동요법이 뜻대로 안 되자 "나는 잘하는 게 하나도 없어요"
              국시: 2023-87
            - **만성적 자존감 저하 / 자존감 저하**: 오랜 기간 자신을 가치 없다고 평가하는 것이다.
              예: "저는 이제까지 잘한 게 하나도 없어요"
              국시: 2021-87
            - **무력감**: "내가 할 수 있는 건 아무것도 없어요"라며 종일 누워 지낸다.
              국시: 2024-88
            - **사회적 고립**: 대화가 없고 혼자 있으려 한다.
              국시: 2022-87
            - **영양 불균형: 신체요구량보다 적음**: 식욕 저하, 체중 감소
            - **수면양상 장애, 자기돌봄 결핍**: 씻지 않고 옷을 갈아입지 않는다.

            # 3. 간호중재

            # 안전: 자살 위험을 먼저 본다
            - 자살을 암시하는 말에는 직접 묻는다.
            - 위험한 물건을 없애고, 약을 먹을 때 삼키는지 확인하고, 혼자 두지 않는다.
            - **회복기에는 자살 위험을 다시 사정한다.** 에너지가 먼저 돌아와 자살을 실행할 위험이 오히려 커지기 때문이다.
            국시: 2025-81, 2021-89

            # 치료적 관계: 곁에 있어 주기
            - 말을 하지 않더라도 곁에 함께 있어 준다. 침묵과 존재만으로도 관심과 지지를 전할 수 있다.
              국시: 2025-87 (딸의 자살 소식 후 말없이 우는 환자)
            - 감정을 말로 표현하도록 격려하고, 감정을 반영해 준다.
              예: "인생이 의미가 없다고 느끼시는군요."
              국시: 2020-74
            - **동정하지 않고 공감한다.** 동정은 대상자를 더 무력하게 만든다.
            - 짧게, 자주 만난다. 대답이 느리면 기다려 준다.
            - 상투적인 격려는 비치료적이다. 예: "기운 내세요", "긍정적으로 생각하세요"

            # 자존감과 무력감
            - **쉽게 성공할 수 있는 작고 현실적인 과제**를 주어 성취감을 느끼게 하고, 해낸 일을 인정해 준다.
              국시: 2020-88
            - 대상자가 **스스로 현실적인 목표를 세우도록** 돕는다.
              국시: 2022-88
            - 엄격하고 이상적인 기준이나 비현실적인 목표는 실패감을 키운다.
            - 부정적인 관점에 동의하지 않는다.
            - 결정 능력이 떨어져 있으므로 **간단한 결정부터** 하게 한다. 모든 결정을 스스로 하라고 요구하지 않는다.

            # 인지적 중재
            "한 번도 제대로 해낸 적이 없다", "이번에도 분명히 망칠 것이다" 같은 부정적 자동사고를 찾아, 근거를 함께 검토하고 더 현실적인 생각으로 바꾸도록 돕는다(인지재구성).
            국시: 2025-88

            # 활동과 사회적 접촉
            - 혼자 지내지 않게 한다. 대인관계는 **일대일이나 소집단부터** 시작하고, 대집단은 나중에 한다.
            - 단순하고 짧으며 성공할 수 있는 활동부터 시작한다. 경쟁적이거나 복잡한 활동은 피한다.
            - 슬픔을 참으라고 하거나 울지 말라고 하지 않는다. 기분에 맞지 않는 억지 기분전환(경쾌한 음악 등)도 피한다.

            # 영양
            - 좋아하는 음식과 기호식품을 **소량씩 자주** 제공한다.
              국시: 2026-88
            - 혼자가 아니라 다른 사람과 함께 식사하게 한다.
            - 섭취량과 체중을 확인한다. 체중은 정해진 시간에 같은 조건에서 잰다.
            - 다 먹으라고 강요하지 않는다.

            # 수면과 자기돌봄
            - 낮 동안 활동하게 하고 낮잠을 줄인다. 취침 전에는 자극을 줄인다.
            - 씻기, 옷 갈아입기 같은 자기돌봄을 단계별로 격려하고 필요한 만큼만 돕는다.

            # 약물과 치료에 대한 교육
            - 항우울제(SSRI 등)는 효과가 나타나기까지 **2~4주** 이상 걸린다. 임의로 끊지 않도록 교육한다.
            - MAO 억제제를 먹을 때는 **티라민이 많은 음식**(숙성 치즈, 와인, 훈제육)을 피해야 한다. 고혈압 위기가 올 수 있다.
              국시: 2021-78
            - 약에 반응하지 않거나 자살 위험이 매우 높으면 전기경련요법(ECT)을 쓸 수 있다.

            # 함께 보면 좋은 문항
            2025-76 세로토닌 감소 · 2025-81 자살 직접 묻기 · 2025-88 인지재구성 · 2024-87 함입 · 2021-89 회복기 자살 위험 · 2021-78 MAO 억제제 · 2020-74 감정반영
            """#
        ),
        // 2026-89 아래에 붙은 설명
        TopicGuide(
            topics: ["조증 환자의 간호"],
            title: "조증 환자의 간호중재",
            body: #"""
            조증 환자 간호의 핵심은 **안전 확보, 자극 줄이기, 단호하고 일관된 태도, 영양과 휴식 보충**이다. 조증 환자는 과다활동으로 지치거나 다칠 수 있고, 좌절하면 공격적으로 변할 수 있다.

            # 국시 출제 경향
            - 2020~2026년에 **11문항**이 나왔다(매년, 2021~2024년은 2문항). 대개 2교시 89·90번 자리이고, 2021년에는 88번에도 나왔다.
            - **사고비약·과다활동에 대한 대화와 일상 간호**(5문항)
              - 2025-89 멈추지 않고 여러 주제를 말함 → **단호하고 차분하게 반응한다**
              - 2024-89 이야기하다 갑자기 다른 주제로 바꿈 → **사고비약**
              - 2023-89 바빠서 밥 먹을 시간이 없다며 돌아다님 → **움직이면서 먹을 수 있는 음식을 제공한다**
              - 2022-89 사고비약을 보이는 환자 → **한 번에 한 가지 주제로 이야기한다**
              - 2020-90 약을 끊고 잠·식사 없이 돌아다니며 수다스러움 → **짧고 간략하게 설명한다**
            - **공격·조종 행동에 대한 제한설정**(4문항)
              - 2024-90 남 탓을 하며 환자와 치료진을 조종함 → **직원 간 일관성 유지**
              - 2023-90 적대적이고 사소한 요구를 반복함 → **단호하고 일관된 태도를 보인다**
              - 2022-90 다른 환자에게 간섭하고 욕설로 위협함 → **단호하고 중립적으로 행동을 제한한다**
              - 2021-90 싸움을 걸고 간호사를 조종함 → **행동에 대해 제한을 설정한다**
            - **간호진단**(2문항)
              - 2026-89 요구가 거절되자 악담하며 주먹으로 벽을 침 → **타인에 대한 폭력의 위험**
              - 2021-88 남의 일에 참견하고 대화에 끼어들어 말다툼함 → **사회적 상호작용 장애**
            - 오답 보기의 구성
              - 2023-90, 2022-90, 2021-90, 2020-90: "경쟁적(신체)활동을 격려한다"를 네 번 오답으로 냈다. 자극이 많은 집단활동, 신나는 음악, 취침 전 격렬한 활동(2025-89, 2022-90, 2020-90)도 같은 **자극 증가** 오답이다.
              - 2023-90, 2022-90, 2020-90, 2022-89: 요구의 옳고 그름 논쟁, 한계 설정 논쟁, 논리적 설득처럼 **논쟁**을 섞는다.
              - 2025-89, 2023-89, 2021-90, 2022-89: 한 주제로 길게 대화, 식사의 중요성 자세히 설명, 긴 시간 토론처럼 **긴 대화**를 넣는다.
              - 2021-90, 2022-89: 요구에 따라 규칙 바꾸기, 무조건 수용, 제한 없이 말하게 하기처럼 **허용적 태도**를 둔다.
              - 2023-89: 간식 금지, 억제대, 식사 중단처럼 **처벌적 조치**를 섞는다.
              - 2024-89: 관계사고, 사고전파, 사고주입, 사고지연처럼 **다른 사고 장애 용어**를 섞는다.

            # 풀이 요령
            - 조증 중재의 정답 핵심어는 **단호, 차분, 일관, 중립, 제한설정, 짧고 간단하게, 한 번에 한 주제**이다.
            - 조종하거나 치료진을 갈라놓으려 하면 **직원 간 일관성**과 제한설정을 고른다. 규칙 변경이나 무조건 수용은 조종을 강화한다.
            - 다음 보기는 지운다.
              - 경쟁적 활동, 자극이 많은 집단활동, 신나는 음악 → 자극 증가
              - 논쟁, 논리적 설득, 긴 토론 → 효과 없고 적대감 증가
              - 무시, 지켜보기, 비난 → 좌절과 폭력 유발
            - 앉아서 먹지 못하는 환자에게는 **들고 다니며 먹는 고칼로리 음식**을 준다. 포장 음식 직접 개봉은 독 망상 환자용이다.
            - 진단 문항은 행동으로 가른다. 벽 치기, 악담처럼 폭력 전조가 있으면 **타인에 대한 폭력의 위험**, 간섭과 말다툼이면 **사회적 상호작용 장애**이다.

            # 1. 이해를 위한 기본 내용

            # 주요 증상
            - 들뜨거나 과민한 기분
            - 과대감(과대망상), 수면 욕구 감소, 말이 많고 빠름(언어압박)
            - **사고비약**: 주제가 빠르게 이 주제 저 주제로 바뀐다.
            - 주의산만, 목표 지향 활동이나 정신운동 초조의 증가
            - 충동적이고 위험한 행동: 과소비, 성적 무분별 등
            - 남의 일에 간섭하고, 요구가 많고, 조종하는 행동
            - 좌절에 대한 인내력이 낮아 쉽게 화내고 공격적으로 변함
            국시: 2024-89 (사고비약), 2020-89 (과대망상)

            # 간호진단
            - **타인에 대한 폭력의 위험**: 공격적 행동이 보이면 가장 우선한다.
              국시: 2026-89 (거절당하자 악담을 퍼붓고 주먹으로 벽을 침)
            - **사회적 상호작용 장애**: 남의 일에 참견하고 대화에 끼어들어 말다툼을 한다.
              국시: 2021-88
            - **영양 불균형: 신체요구량보다 적음**: 돌아다니느라 먹지 않는다.
            - **수면양상 장애, 상해의 위험, 비효과적 대처**

            # 2. 간호중재

            # 안전과 폭력 예방
            - 공격적인 전조(목소리가 커짐, 위협, 물건을 침)를 일찍 알아차린다.
            - 허용되지 않는 행동을 **단호하고 중립적으로 제한**한다.
            - 억제나 격리는 자신이나 남을 해칠 급박한 위험이 있고 다른 방법이 실패했을 때만 쓴다.
            국시: 2022-90 (다른 환자를 위협 → 단호하고 중립적으로 행동을 제한)

            # 자극 줄이기
            - 조용하고 자극이 적은 환경을 제공한다. 1인실이나 조용한 공간이 좋다.
            - 다인실, 시끄러운 음악, 많은 사람, 다양한 자극이 있는 집단활동은 피한다.
            - **경쟁적인 활동은 피한다**. 흥분과 공격성을 높인다. 대신 산책처럼 에너지를 쓸 수 있는 비경쟁적인 활동을 한다.

            # 의사소통
            - **단호하고 차분하며 일관된 태도**로 대한다. 간호사의 차분한 태도가 환자의 흥분을 가라앉힌다.
              국시: 2025-89, 2023-90
            - **짧고 간단하며 구체적으로** 말한다. 추상적인 말은 피한다.
              국시: 2020-90
            - **한 번에 한 가지 주제**로 이야기한다. 사고비약이 있는 환자의 주의를 모으는 데 도움이 된다.
              국시: 2022-89
            - 환자의 말을 무시하지 않는다. 그렇다고 주제마다 모두 반응하거나 제한 없이 말하게 두지도 않는다.
            - 논쟁하지 않는다. 요구가 옳은지 그른지 따지거나, 적대적인 행동을 계속 지적하고 비난하지 않는다.

            # 제한설정과 조종 행동
            - 조증 환자는 다른 환자와 치료진을 조종하거나, 직원들 사이를 갈라놓으려 한다.
            - **모든 직원이 같은 규칙과 제한을 일관되게** 적용한다.
            - 환자의 요구에 따라 규칙을 바꾸거나 요구를 무조건 들어주지 않는다. 그러면 조종 행동이 강화된다.
            - 제한을 둘 때는 무엇이 허용되지 않는지와 그 결과를 분명히 알린다.
            국시: 2024-90 (직원 간 일관성 유지), 2021-90 (행동에 대해 제한을 설정)

            # 영양과 수분
            - 앉아서 식사하기 어려우므로 **들고 다니며 먹을 수 있는 고칼로리·고단백 음식**(finger food)을 준다. 샌드위치, 과일, 치즈, 음료 등이 해당한다.
              국시: 2023-89
            - 충분한 수분을 공급한다.
            - 섭취량과 체중을 확인하고, 먹는 것을 자주 상기시킨다.
            - 식사를 거부한다고 간식을 금지하거나 식사를 주지 않는 것은 처벌이며 잘못이다.

            # 휴식과 수면
            - 낮에 활동과 휴식을 번갈아 하게 한다.
            - 취침 전에는 자극을 줄인다. 잠들기 직전의 격렬한 활동은 피한다.
            - 수면 시간과 양을 관찰한다.

            # 위생과 자기돌봄
            과다활동 때문에 위생과 옷차림을 소홀히 하거나, 지나치게 화려하게 꾸미기도 한다. 필요한 만큼 돕고 격려한다.

            # 약물: 리튬
            - 조증에는 리튬 같은 기분안정제를 쓴다.
            - 치료농도는 약 **0.6~1.2 mEq/L**이며, 1.5 이상이면 독성이다. 치료범위가 좁아 정기적으로 혈중농도를 잰다.
            - 충분한 수분과 **정상적인 염분**을 섭취해야 한다. 탈수, 땀, 구토, 설사, 이뇨제는 리튬 농도를 높여 독성 위험을 키운다.
            - 독성 징후(심한 구토·설사, 거친 떨림, 운동실조, 혼돈)가 나타나면 투약을 멈추고 보고한다.
            - 갑상샘 기능과 신장 기능을 정기적으로 검사한다.
            - 임의로 약을 끊으면 재발한다. 약을 끊은 뒤 조증으로 입원하는 경우가 흔하다.
            국시: 2026-90, 2025-90, 2024-78, 2022-78, 2020-78

            # 함께 보면 좋은 문항
            - 2020-89: 과대망상
            - 리튬 문항: 2026-90, 2025-90, 2024-78, 2022-78, 2020-78
            """#
        ),
        // 2026-90 아래에 붙은 설명
        TopicGuide(
