              - 2024-78, 2020-78: 이뇨제와 함께 써도 된다고 한다. 이뇨제는 리튬 농도를 높인다.
              - 2022-78: 티라민 제한(MAO 억제제), 긴소매 옷(광과민성 항정신병약물)처럼 **다른 약물의 주의사항**을 섞는다.
              - 2025-90, 2020-78: 미세한 손떨림에 즉시 중단, 구토·졸림·이명을 일시적 현상이라며 안심시키기처럼 **부작용과 독성 징후를 거꾸로 다루는 보기**를 섞는다.
            - 5문항 중 3문항의 정답이 **독성 징후를 보고하거나 투약을 중단한다**는 내용이다.

            # 풀이 요령
            - 리튬 문항의 정답은 대개 **독성 징후(구토, 설사, 거친 손떨림, 운동실조, 혼돈)를 즉시 보고하거나 중단한다**이다.
            - 수분·염분은 **충분히 유지**한다. 수분 제한, 무염식, 땀을 많이 흘리는 운동, 이뇨제 병용은 모두 오답이다.
            - 혈중농도 수치는 구간으로 가른다.
              - 약 0.6~1.2 mEq/L → 치료범위(유지기)
              - 1.5 mEq/L 이상 → 경미한 독성(오심, 설사, 거친 손떨림)
              - 2.0 mEq/L 이상 → 중등도 독성(운동실조, 혼돈)
              - 2.5~3.0 mEq/L 이상 → 심한 독성(경련, 혼수)
            - 미세한 손떨림은 흔한 부작용이므로 임의로 끊지 않는다. 장기 복용 시 **갑상샘기능검사와 신기능검사**를 정기적으로 받는다.
            - 티라민 제한은 MAO 억제제, 긴소매 옷은 광과민성 약물의 주의사항이므로 리튬 문항에서는 고르지 않는다.

            # 1. 혈중농도

            # 치료범위
            - 유지 치료: 약 **0.6~1.2 mEq/L**
            - 급성 조증: 약 1.0~1.5 mEq/L
            - 교재에 따라 범위가 조금씩 다르다. 국시 2026-90에서는 **0.9 mEq/L를 "치료혈중농도 범위 안"**으로 보았다.

            # 독성범위
            - **1.5 mEq/L 이상**: 경미한 독성. 오심, 구토, 설사, 거친 손떨림이 나타난다.
            - **2.0 mEq/L 이상**: 중등도 독성. 운동실조, 혼돈, 졸림, 근육 연축, 불분명한 발음이 나타난다.
            - **2.5~3.0 mEq/L 이상**: 심한 독성. 경련, 혼수, 부정맥이 나타나고 생명이 위험하다.

            # 채혈 방법
            - 투약 초기에는 자주(주 1~2회), 안정되면 정기적으로(1~3개월마다) 잰다.
            - 마지막 복용 후 **약 12시간 뒤**, 다음 약을 먹기 전에 채혈한다.

            # 2. 부작용

            # 흔한 초기 부작용 (대개 일시적)
            - 오심, 가벼운 설사
            - **미세한 손떨림**
            - 다뇨와 갈증
            - 체중 증가
            - 금속성 맛
            미세한 손떨림은 흔한 부작용이므로 약을 **임의로 끊지 않고** 보고하게 한다. 반면 **거친 떨림**은 독성 징후이다.

            # 장기 부작용
            - **갑상샘 기능 저하**
            - 신장 기능 저하, 신성 요붕증
            - 임신 초기에 복용하면 태아 심장 기형(엡스타인 기형) 위험이 있다. 가임기 여성에게는 피임과 임신 계획을 상담한다.

            # 3. 간호중재와 교육

            # 혈중농도와 검사
            - 정기적으로 혈중농도를 확인한다(치료약물농도감시, TDM).
            - **갑상샘기능검사와 신장기능검사**를 정기적으로 받게 한다.
              국시: 2025-90 (리튬 복용 환자 교육 → 주기적으로 갑상샘기능검사를 받는다)
            - 투약 전에 신장 기능, 갑상샘 기능, 전해질, 심전도를 확인한다.

            # 수분과 염분
            - 하루 **2~3L의 충분한 수분**을 섭취하게 한다. 수분을 제한하면 안 된다.
            - **정상적인 염분 섭취**를 유지한다. 나트륨이 부족하면 콩팥이 리튬을 더 붙잡아 두어 농도가 올라간다. 저염식이나 무염식을 하지 않게 한다.
            - 탈수를 일으키는 상황을 조심한다. **땀을 많이 흘리는 운동, 더운 날씨, 사우나, 발열, 구토, 설사**가 해당한다. 이럴 때는 수분을 더 보충하고 증상이 계속되면 알린다.

            # 독성 징후를 관찰하고 보고한다
            - **구토, 설사, 거친 떨림, 운동실조, 졸림, 혼돈**이 나타나면 독성일 수 있다.
            - 이때는 **투약을 중단하고 즉시 보고**하며, 혈중농도를 확인한다.
            - 구토와 설사는 그 자체가 독성 신호이면서, 수분과 나트륨을 잃게 해 농도를 더 올린다.
            국시:
            - 2024-78: 구토, 설사를 하면 즉시 보고한다.
            - 2020-78: 운동실조나 설사를 하면 독성 증상일 수 있으니 즉시 보고한다.
            - 2022-78: 독성반응이 나타나면 약물을 중단한다.

            # 약물 상호작용
            리튬 농도를 높이는 약을 함께 쓰지 않도록 교육한다.
            - **이뇨제**, 특히 티아지드계: 나트륨을 빠져나가게 해 리튬 농도를 높인다.
