            - **불안 수준 가리기**(3문항)
              - 2025-91 수술합병증 걱정에만 몰두하지만 간호사가 집중을 유도하면 이해한다 → **중등도 불안**
              - 2024-91 아이를 잃은 엄마가 물어도 반응하지 않고 허둥대다 부딪히며 과호흡을 보인다 → **중증 불안**
              - 2021-92 발표 순서를 기다리며 동료의 격려를 전혀 듣지 못하고 이름이 불리는 것에만 주의한다 → **중등도 불안**
            - **중증 불안의 간호중재**(2문항)
              - 2026-91 수술 전 설명에 전혀 집중하지 못하고 멍하게 있다 → **조용한 상담실로 옮겨서 함께 있어 준다**
              - 2021-91 안절부절못하고 거칠게 호흡하며 손을 떨고 설명에 집중하지 못한다 → **대상자 옆에 함께 있어준다**
            - 오답 보기의 구성
              - 2025-91, 2024-91, 2021-92: 일시적·경증·중등도·중증 불안, 공황(2024-91은 공포 포함)처럼 **인접한 불안 단계**를 나열한다.
              - 2026-91: 다른 간호사가 다시 설명, 수술의 중요성을 더 자세히 설명처럼 **불안이 낮아지기 전에 정보를 더 주는 보기**와 혼자 두기, 다른 환자와 만나게 하기를 섞는다.
              - 2021-91: 새로운 불안관리 기술 개발, 불안 직전의 생각 확인, 걱정을 구체적으로 이야기하기처럼 **불안이 낮아진 뒤에 할 중재**와 공포증 기법인 홍수법을 섞는다.
            - 중재 문항 2개는 모두 **중증 불안** 사례이고 정답은 **곁에 함께 있어 주기**이다.

            # 풀이 요령
            - 사정 문항은 **안내를 받으면 주의를 돌릴 수 있는가**로 가른다.
              - 한 가지 걱정에만 몰두하지만 유도하면 이해한다(선택적 부주의) → 중등도 불안
              - 물어도 반응하지 않고, 목적 없이 허둥대며 과호흡 같은 신체 증상이 있다 → 중증 불안
              - 현실 지각이 무너지고 기능이 마비된다 → 공황
              - 지각 영역이 넓어지고 학습 능력이 오히려 높아진다 → 경증 불안
            - 중증 불안의 중재는 **자극을 줄이고 곁에 함께 있어 준다**를 고른다. 조용한 장소로 옮기기도 같은 방향이다.
            - 설명을 반복하거나 더 자세히 하기, 새 기술 가르치기, 불안의 원인 탐색은 불안이 낮아진 뒤의 일이므로 오답이다.
            - 혼자 두기는 공황으로 악화될 수 있어 오답이고, 홍수법은 공포증 치료 기법이다.

            # 1. 불안 수준별 특성과 중재

            # 경증 불안 (mild)
            - **지각 영역이 넓어진다.** 주의력과 각성이 높아진다.
            - 학습과 문제해결 능력이 오히려 좋아진다. 성장과 창의성의 동기가 된다.
            - 신체 증상은 가볍다. 안절부절이나 손 만지작거리기 정도이다.
            - 중재
              - 불안을 스스로 알아차리게 한다.
              - 이 시기가 교육하고 문제를 해결하기 가장 좋은 때이다.
              - 새로운 대처 방법을 익히게 한다.

            # 중등도 불안 (moderate)
            - **지각 영역이 좁아진다.** 당면한 걱정에만 주의를 기울이고 주변 자극은 놓친다(**선택적 부주의**).
            - **다른 사람이 방향을 제시하면** 주의를 돌려 집중하고 배울 수 있다.
            - 심박과 호흡이 빨라지고, 근육이 긴장하고, 말이 빨라진다.
            - 중재
              - 간호사가 방향을 잡아 주며 집중하게 돕는다.
              - 불안을 말로 표현하게 하고, 불안의 원인과 불안이 생기기 직전의 생각·감정을 함께 찾는다.
              - 이완 기법을 쓰게 하고, 효과적인 대처 방법을 강화한다.
            - 국시
              - 2025-91: 수술 걱정 외에는 관심이 없으나, 간호사가 집중을 유도하면 수술 절차를 이해한다 → 중등도 불안
              - 2021-92: 동료의 격려는 전혀 듣지 못하고 자신의 이름이 불리는 것에만 주의를 기울인다 → 중등도 불안

            # 중증 불안 (severe)
            - **지각 영역이 크게 좁아진다.** 사소한 세부 사항 하나에만 몰두한다.
            - **안내해 주어도 집중하지 못한다.** 새로운 것을 배우거나 문제를 해결할 수 없다.
            - 목적 없는 행동, 허둥댐, 과호흡, 두통, 어지러움, 떨림, 설명에 반응하지 못함이 나타난다.
            - 중재
              - **자극이 적은 조용한 곳으로 옮긴다.**
              - **간호사가 곁에 함께 있어 준다.** 곁에 있는 것만으로 안정감을 준다.
              - 짧고 간단하며 차분한 말로 안심시키고, 천천히 호흡하도록 이끈다.
              - 설명, 교육, 원인 탐색, 새로운 기술 연습은 **불안이 낮아진 뒤로 미룬다**.
              - 혼자 두지 않는다.
              - 필요하면 처방에 따라 항불안제를 쓴다.
            - 국시
              - 2024-91: 아이를 잃어버린 엄마가 질문에 반응하지 못하고, 부딪혀 넘어지며 과호흡한다 → 중증 불안
              - 2026-91: 수술 전 설명을 듣다가 "무슨 말인지도 모르겠어요"라며 멍하게 있다 → 조용한 상담실로 옮겨 함께 있어 준다
              - 2021-91: 초조해서 안절부절못하고 거칠게 호흡하며 설명에 집중하지 못한다 → 옆에 함께 있어 준다

            # 공황 (panic)
            - **현실 지각이 무너지고** 성격이 해체되는 듯한 상태이다. 합리적으로 생각하거나 기능하지 못한다.
            - 극도의 공포, 죽을 것 같은 느낌, 심한 과호흡, 흉통, 비현실감이 나타난다. 도망치거나 얼어붙는다.
            - 오래 계속되면 탈진에 이를 수 있다.
            - 중재
              - **안전을 확보한다.**
              - 조용한 곳으로 옮기고 **곁에 머문다.**
              - 아주 짧고 단순한 말로 안내한다. 예: "제가 여기 있어요. 천천히 숨 쉬세요."
              - 갑작스러운 신체 접촉은 위협으로 느낄 수 있으므로 조심한다.
              - 과호흡이 있으면 천천히 호흡하도록 이끈다.
              - 발작 중에는 원인 탐색, 면담, 교육, 집단활동을 하지 않는다.
            - 국시
              - 2020-92: 활동치료 중 공황발작 → 조용한 장소로 옮기고 곁에 있어 준다
              - 2026-92, 2021-93: 공황발작 중 과호흡 → 봉투를 이용한 호흡

            # 과호흡에 대한 참고
            국시는 봉투 재호흡을 정답으로 인정한다. 그러나 저산소증 위험이 있어 최근 지침(ANZCOR 2023)은 응급처치로 권하지 않는다. 불안으로 인한 과호흡이 확실할 때만 짧게 쓰고, 곁에서 관찰해야 한다.

            # 2. 한눈에 비교

            # 지각 영역
            넓어짐(경증) → 좁아짐(중등도) → 크게 좁아짐(중증) → 현실 지각 상실(공황)

            # 학습과 집중
            좋아짐(경증) → 안내하면 가능(중등도) → 안내해도 불가능(중증) → 기능 상실(공황)

            # 간호의 초점
            - 경증: 교육과 문제해결
            - 중등도: 방향 제시, 원인 탐색, 이완
            - 중증: 자극 감소, 함께 있기, 짧은 말
            - 공황: 안전, 함께 있기, 아주 짧은 말

            # 함께 보면 좋은 문항: 공황발작과 과호흡
            2026-92 봉투 호흡 · 2022-93 공황장애 · 2021-93 봉투 호흡 · 2020-92 조용한 곳에서 곁에 있기
            """#
        ),
        // 2026-92 아래에 붙은 설명
        TopicGuide(
            topics: ["공황발작과 과호흡"],
            title: "공황발작과 과호흡의 간호중재",
            body: #"""
            공황발작 중인 대상자에게는 **안전을 확보하고, 조용한 곳에서 곁에 머물며, 짧고 차분한 말로 천천히 호흡하도록 이끄는 것**이 핵심이다. 발작 중에는 대상자가 생각하거나 배울 수 없으므로 원인 탐색과 교육은 발작이 가라앉은 뒤에 한다.

            # 국시 출제 경향
            - 2020~2026년에 **4문항**이 나왔다(2020, 2021, 2022, 2026년). 2교시 92·93번 자리이다.
            - **공황발작 중 우선 중재**(3문항)
              - 2026-92 공황장애 입원 환자가 면담 중 과호흡하며 죽을 것 같다고 한다 → **종이봉투로 입과 코를 덮어 호흡하게 한다**
              - 2021-93 광장공포증 환자가 활동요법 중 과호흡하며 죽을 것 같다고 한다 → **코와 입을 덮는 봉투로 호흡하게 한다**
              - 2020-92 공황장애 환자가 활동치료 중 공황발작을 일으켰다 → **조용한 장소로 옮기고 곁에 있어 준다**
            - **공황장애 추정**(1문항)
              - 2022-93 터널을 지나다 숨이 막히고 죽을 것 같아 심장병을 의심했으나 검사상 이상이 없다 → **공황장애**
            - 오답 보기의 구성
              - 2021-93, 2020-92: 증상의 원인 탐색, 걱정 이야기하기, 이완기술 교육처럼 **발작이 가라앉은 뒤에 할 중재**를 섞는다.
              - 2026-92, 2021-93: 다양한 자극 제공, 혼자 있게 하기, 계속 말을 시키기, 면담 지속, 집단요법처럼 **자극을 늘리거나 방치하는 보기**를 섞는다.
              - 2026-92: 고농도 산소요법을 넣는다. 과호흡에서는 산소가 부족하지 않다.
              - 2020-92: 신체적 접촉 제공을 넣는다. 공황 상태에서는 접촉이 위협으로 느껴질 수 있다.
              - 2022-93: 강박장애, 해리장애, 사회불안장애, 외상후 스트레스장애처럼 **다른 불안 관련 장애**를 나열한다.
            - 과호흡이 사례에 나오면 3문항 중 2문항에서 **봉투 호흡**이 정답이었다.

            # 풀이 요령
            - 사례에 **과호흡 + 죽을 것 같다**가 나오면 봉투로 입과 코를 덮어 호흡하게 하는 보기를 고른다. 내쉰 이산화탄소를 다시 들이마셔 호흡성 알칼리증을 완화한다.
            - 과호흡 언급 없이 공황발작만 나오면 **조용한 장소로 옮기고 곁에 있어 준다**를 고른다.
            - 발작 중에는 원인 탐색, 대화 유도, 교육이 불가능하므로 오답이다. 자극은 줄이고 혼자 두지 않는다.
            - 갑작스러운 호흡곤란, 죽을 것 같은 공포, 심장병 의심, **검사상 이상 없음** → 공황장애이다. 터널처럼 빠져나가기 어려운 장소는 광장공포증 동반을 시사한다.

            # 1. 이해를 위한 기본 내용

            # 공황발작
            - 갑자기 극심한 공포나 불편감이 몰려와 **수분 안에 최고조**에 이른다.
            - 대개 10분 안팎에서 정점을 찍고 가라앉는다.
            - 증상
              - 심계항진, 발한, 떨림
              - 숨이 막히거나 가쁜 느낌, 질식할 것 같은 느낌
              - 흉통, 오심
              - 어지러움, 손발 저림, 오한이나 열감
              - 비현실감
              - 통제력을 잃거나 미칠 것 같은 두려움, **죽을 것 같은 두려움**

            # 공황장애
            예기치 않은 공황발작이 반복되는 장애이다. 발작 뒤 1개월 이상 다음 두 가지 중 하나가 이어진다.
            - 또 발작이 올까 걱정한다(예기불안).
            - 발작을 피하려고 행동을 바꾼다(회피).
            터널, 엘리베이터, 대중교통처럼 빠져나가기 어려운 곳을 피하면 광장공포증이 함께 있을 수 있다.
            국시: 2022-93 (터널에서 갑자기 숨이 막히고 죽을 것 같았으나 검사상 이상이 없다 → 공황장애)

            # 과호흡의 기전
            불안으로 숨을 빠르고 깊게 쉬면 이산화탄소가 지나치게 빠져나가 **호흡성 알칼리증**이 생긴다. 그러면 손발과 입 주위가 저리고, 어지럽고, 손발이 뒤틀리고, 가슴이 답답해진다. 이 증상이 공포를 더 키우고, 공포가 다시 과호흡을 부르는 악순환이 생긴다.

            # 2. 사정
            - **신체 질환을 먼저 배제한다.** 특히 처음 겪는 발작이거나 위험 요인이 있으면 반드시 확인한다.
              - 심근경색, 폐색전증, 천식, 저혈당, 갑상샘 기능 항진
              - 카페인이나 자극제 사용, 알코올이나 약물 금단
            - 활력징후와 산소포화도를 확인한다. 산소포화도는 대개 정상이다.
            - 발작의 시작 시점, 계기, 이전 발작, 회피 행동을 확인한다. 이 사정은 발작이 가라앉은 뒤에 한다.

            # 3. 발작 중의 간호중재

            # 곁에 머물며 안전을 확보한다
            대상자를 혼자 두지 않는다. 간호사가 곁에 있다는 것 자체가 안정감을 준다.

            # 자극이 적은 조용한 곳으로 옮긴다
            사람이 많고 시끄러운 곳에서 벗어나게 한다. 조명과 소음을 줄인다.
            국시: 2020-92 (활동치료 중 공황발작 → 조용한 장소로 옮기고 곁에 있어 준다)

            # 짧고 차분하며 단순한 말로 안내한다
            예: "제가 곁에 있어요." "지금 안전해요." "천천히 숨 쉬세요." "곧 가라앉을 거예요."
            공황발작은 시간이 지나면 가라앉는다는 사실을 알려 주는 것은 근거 없는 안심이 아니다.

            # 천천히 호흡하도록 이끈다
            - 간호사가 함께 호흡하며 속도를 맞춘다.
            - 코로 천천히 들이마시고, 입술을 오므려 더 길게 내쉬게 한다.
            - 복식호흡을 하게 한다.
            - 내쉬는 숨을 길게 하면 이산화탄소가 덜 빠져나가 과호흡 증상이 줄어든다.

            # 봉투 재호흡
            - 국시 2026-92와 2021-93은 "봉투로 입과 코를 덮어 호흡하게 한다"를 정답으로 인정했다. 내쉰 이산화탄소를 다시 들이마셔 호흡성 알칼리증을 되돌리는 원리이다.
            - 그러나 봉투 재호흡은 **흡입 산소를 떨어뜨린다.** 과호흡으로 오인한 심근허혈이나 폐색전증 환자가 사망한 사례가 보고되었다(Callaham, 1989).
            - 최근 응급처치 지침(ANZCOR 2023)은 권하지 않는다.
            - 쓴다면 **원인이 불안으로 확인된 경우에만 짧게** 적용하고, 곁에서 관찰한다.

            # 신체 접촉은 조심한다
            공황 상태에서는 갑작스러운 접촉을 위협으로 느낄 수 있다. 접촉이 필요하면 미리 말하고, 대상자가 편해하는지 살핀다.

            # 약물
            증상이 심하면 처방에 따라 단기 작용 벤조디아제핀 같은 항불안제를 쓴다. 산소는 부족하지 않으므로 **고농도 산소요법은 필요 없다.**

            # 4. 발작이 가라앉은 뒤의 간호중재

            # 감정 표현과 원인 탐색
            발작 때 어떤 느낌과 생각이 들었는지 이야기하게 한다. 발작이 시작되기 직전의 상황과 생각을 함께 찾아본다.

            # 교육
            - 공황발작은 위험하지 않으며 저절로 가라앉는다는 것을 설명한다.
            - 과호흡이 저림과 어지러움을 일으키는 원리를 설명해, 증상을 심장병이나 죽음으로 잘못 해석하지 않게 한다.

            # 대처 기술 연습
            - 호흡 조절, 복식호흡, 점진적 근육이완법을 평소에 연습하게 한다.
            - 카페인, 알코올, 니코틴을 줄이게 한다.

            # 치료 연계
            - 인지행동치료: 신체 감각을 파국적으로 해석하는 생각을 바꾸고, 두려운 감각과 상황에 단계적으로 노출한다(체계적 탈감작).
            - 장기적으로는 항우울제(SSRI)를 쓴다. 벤조디아제핀은 의존 위험이 있어 단기간만 쓴다.

            # 함께 보면 좋은 문항
            - 불안 수준: 2026-91, 2024-91, 2021-91
            - 광장공포증의 체계적 탈감작: 2023-93, 2020-91
            """#
        ),
        // 2026-93 아래에 붙은 설명
        TopicGuide(
            topics: ["행동치료와 인지치료"],
            title: "행동치료와 인지치료의 종류",
            body: #"""
            **행동치료**는 문제 행동이 학습된 것이므로 다시 학습해 바꿀 수 있다고 본다. **인지치료**는 문제의 원인을 왜곡된 생각에서 찾고, 그 생각을 바꾸면 감정과 행동도 바뀐다고 본다. 두 가지를 함께 쓰는 것이 인지행동치료이다.

            # 국시 출제 경향
            - 2020~2026년에 **8문항**이 **매년** 나왔고 2023년에는 2문항이 나왔다. 2교시 77번(2021·2023·2024년)과 91~93번(2020·2022·2023·2026년) 자리에 주로 나오고, 2025년은 88번이다.
            - **노출 기법: 체계적 탈감작과 홍수법**(4문항)
              - 2026-93 고소공포증 대상자가 매일 한 계단씩 순차적으로 올라가는 연습을 한다 → **체계적탈민감(체계적 탈감작)**
              - 2023-93 광장공포증 대상자에게 적용하는 체계적 탈감작 → **두려운 상황에 점차적으로 노출시킨다**
              - 2022-92 고소공포증 대상자를 고층빌딩 최고층으로 바로 올라가게 한다 → **홍수법**
              - 2020-91 광장공포증 대상자에게 적용하는 체계적 탈감작 → **두려워하는 상황에 점진적으로 노출시킨다**
            - **인지치료와 인지적 오류**(3문항)
              - 2025-88 "한 번도 제대로 해낸 적이 없다, 이번에도 망칠 것"이라는 우울장애 환자 → **인지재구성**
              - 2023-77 한 번 실연한 청년이 앞으로 모든 관계에서 실연할 것이라 생각한다 → **과잉일반화**
              - 2021-77 인지행동 요법의 특징 → **역기능적 사고와 부적응 행동의 변화에 중점을 둔다**
            - **강화 기법**(1문항)
              - 2024-77 바람직한 행동에 정적 강화를 주어 행동을 늘리는 기법 → **토큰경제**
            - 오답 보기의 구성
              - 2023-93, 2020-91: 거의 같은 보기가 반복됐다. 집에 머물기(회피 강화), 먼 공공장소에 혼자 가기(홍수법), 속으로 '중지' 외치기(사고중지법), 다른 사람을 보고 모방하기(모델링)를 섞는다.
              - 2026-93, 2022-92, 2025-88: 홍수법과 체계적 탈감작을 **서로의 오답**으로 넣고 인지재구축, 혐오요법, 바이오피드백, 점진적 이완요법을 섞는다.
              - 2024-77: 모델링, 형성법, 홍수법, 바이오피드백처럼 **다른 행동치료 기법**을 나열한다.
              - 2023-77: 독심술, 개인화, 극소화/최소화, 선택적 추상화처럼 **다른 인지적 오류**를 나열한다.
              - 2021-77: 과거, 무의식적 갈등, 방어기전과 성격 수정(정신분석), 교정적 대인관계 경험(대인관계 치료)처럼 **다른 치료 이론의 특징**을 섞는다.
            - 체계적 탈감작은 8문항 중 3문항에서 정답, 2문항에서 오답 보기로 나와 가장 자주 쓰인 개념이다.

            # 풀이 요령
            - 노출 기법은 **노출 속도**로 가른다.
              - 약한 자극부터 한 단계씩, 점진적으로, 이완과 함께 → 체계적 탈감작(탈민감, 둔감법)
              - 가장 두려운 자극에 바로, 한꺼번에 → 홍수법
            - 다른 행동치료 기법은 핵심어로 가른다.
              - 바람직한 행동에 토큰·점수 보상 → 토큰경제
              - 목표 행동에 가까워지는 단계마다 강화 → 형성법
              - 다른 사람을 보고 따라 함 → 모델링
              - 속으로 '중지'라고 외침 → 사고중지법
              - 생리 반응을 스스로 조절 → 바이오피드백
            - 인지적 오류는 한두 번의 일로 "항상, 모든, 한 번도"라고 결론 내리면 **과잉일반화**이다. 이런 부정적 사고를 현실적으로 바꾸는 기법이 **인지재구성**이다.
            - 인지행동치료는 **현재의 사고와 행동**에 초점을 둔다. 과거·무의식·방어기전이 나오면 정신분석적 치료이므로 오답이다.

            # 1. 행동치료

            # 체계적 탈감작 (체계적 둔감법, systematic desensitization)
            불안을 일으키는 자극을 약한 것부터 강한 것까지 위계로 정리한다. 이완훈련을 익힌 뒤, 이완한 상태에서 **가장 약한 자극부터 단계적으로** 노출한다. 공포증과 불안장애에 쓴다.
            예: 고소공포증 환자가 매일 한 계단씩 올라간다. 개를 무서워하는 사람이 개 사진, 멀리 있는 개, 가까이 있는 개 순서로 다가간다.
            국시: 2026-93, 2023-93, 2020-91 (광장공포증: 두려운 상황에 점진적으로 노출)

            # 홍수법 (flooding)
            처음부터 **가장 강한 공포 자극에 한꺼번에 오래** 노출한다. 예상했던 끔찍한 일이 일어나지 않는다는 것을 경험하게 해서 불안을 없앤다.
            예: 고소공포증 환자를 고층빌딩 최고층으로 바로 올라가게 한다.
            국시: 2022-92

            # 노출 및 반응방지 (exposure and response prevention)
            강박장애에 쓴다. 불안을 일으키는 상황에 노출하되, 강박행동은 하지 못하게 막는다.
            예: 오염된 물건을 만진 뒤 손을 씻지 않게 한다.

            # 혐오요법 (aversion therapy)
            문제 행동을 불쾌한 자극과 짝지어 그 행동을 줄인다. 알코올 의존에 쓰는 다이설피람(술을 마시면 심한 불쾌감을 일으킴)이 예이다.

            # 토큰경제 (token economy)
            바람직한 행동을 하면 토큰(스티커, 점수)을 주고, 모은 토큰을 원하는 보상과 바꾸게 한다. **정적 강화**를 체계적으로 쓰는 방법으로, 병동이나 아동에게 많이 쓴다.
            예: 주 5일 이상 걷기를 실천한 노인에게 칭찬 스티커를 주고, 많이 모은 사람에게 선물을 준다.
            국시: 2024-77

            # 강화, 처벌, 소거
            - **정적 강화**: 바람직한 행동 뒤에 좋은 것을 주어 그 행동을 늘린다.
            - **부적 강화**: 바람직한 행동 뒤에 싫은 것을 없애 주어 그 행동을 늘린다.
            - **처벌**: 문제 행동 뒤에 불쾌한 결과를 주어 그 행동을 줄인다.
            - **소거**: 문제 행동에 주던 강화(관심)를 끊어 그 행동을 줄인다. 예: 관심을 끌려는 행동에 반응하지 않는다.

            # 타임아웃 (time-out)
            문제 행동을 할 때 잠시 강화가 없는 곳에 있게 한다. 아동에게 많이 쓴다.

            # 형성법 (조형, shaping)
            목표 행동에 조금씩 가까워지는 행동마다 강화해서 복잡한 행동을 단계적으로 익히게 한다.

            # 모델링 (modeling)
            다른 사람의 행동을 관찰하고 따라 하며 배우게 한다.
            예: 낯선 곳을 방문하는 다른 사람의 모습을 보고 따라 하게 한다.

            # 행동계약 (contracting)
            목표 행동과 그에 따른 보상과 결과를 대상자와 미리 약속한다.

            # 이완훈련
            - 점진적 근육이완법: 근육을 차례로 긴장시켰다가 풀어 몸의 이완을 익힌다.
            - 호흡법: 복식호흡, 천천히 길게 내쉬기
            - 심상법

            # 바이오피드백 (biofeedback)
            심박, 근육 긴장, 피부 온도 같은 생리 반응을 기계로 보여 주어 스스로 조절하도록 훈련한다. 긴장성 두통, 불안에 쓴다.

            # 주장훈련 (assertiveness training)
            다른 사람의 권리를 침해하지 않으면서 자기 생각과 감정을 솔직하게 표현하는 법을 익히게 한다.

            # 사고중지법 (thought stopping)
            원치 않는 생각이 떠오를 때 마음속으로 "중지!"라고 외치며 생각을 끊는다. 인지적 요소가 섞인 행동 기법이다.
            국시 오답 보기: 2023-93, 2020-91 ("낯선 장소에서 불안할 때 마음속으로 '중지'라고 외친다")

            # 2. 인지치료

            # 벡(Beck)의 인지치료
            - 상황 자체보다 상황을 해석하는 **자동적 사고**가 감정을 만든다고 본다.
            - 우울한 사람은 자신, 세상, 미래를 모두 부정적으로 본다(**인지 삼제**).
            - 자동적 사고를 찾아 근거를 검토하고, 더 현실적인 생각으로 바꾸게 한다.

            # 인지재구성 (인지재구조화, cognitive restructuring)
            비합리적이고 왜곡된 생각을 찾아, 근거를 따져 보고, 합리적이고 현실적인 생각으로 바꾸는 기법이다.
            예: "나는 한 번도 제대로 해낸 적이 없어요. 이번에도 분명히 망칠 거예요"라며 활동을 거부하는 우울 환자
            국시: 2025-88

            # 주요 인지왜곡
            - **과잉일반화**: 한두 번의 일로 모든 상황에 대한 결론을 내린다.
              예: 한 번 실연했으니 앞으로도 모든 관계에서 실연할 것이다.
              국시: 2023-77
            - **흑백논리(이분법적 사고)**: 모든 것을 완전한 성공 아니면 완전한 실패로 본다.
            - **개인화**: 자신과 관련 없는 일을 자기 탓으로 여긴다.
            - **독심술**: 근거 없이 남이 자신을 나쁘게 생각한다고 단정한다.
            - **예언자적 오류(점쟁이 오류)**: 근거 없이 나쁜 결과를 확신한다.
            - **선택적 추상화**: 일부 부정적인 부분만 보고 전체를 판단한다.
            - **임의적 추론**: 근거 없이 결론을 내린다.
            - **극대화와 극소화**: 부정적인 일은 크게, 긍정적인 일은 작게 본다.
            - **파국화**: 일어날 수 있는 가장 나쁜 결과를 예상한다.
            - **당위적 사고**: "반드시 ~해야 한다"는 생각에 매인다.

            # 엘리스(Ellis)의 합리적 정서행동치료 (REBT, ABCDE 모형)
            - A: 선행사건
            - B: 비합리적 신념
            - C: 정서적·행동적 결과
            - D: 비합리적 신념을 논박한다.
            - E: 효과로서 합리적 신념과 새로운 감정이 생긴다.
            "반드시", "절대로" 같은 비합리적 신념을 논박해 바꾼다.

            # 3. 인지행동치료의 특징
            **현재의 역기능적 사고와 부적응 행동**을 바꾸는 데 초점을 둔다. 구조화되어 있고 단기간이며, 목표가 분명하고 과제를 준다.
            과거, 무의식적 갈등, 성격과 방어기제의 수정에 초점을 두는 것은 정신분석적 치료이다. 교정적 대인관계 경험은 대인관계치료의 특징이다.
            국시: 2021-77

            # 4. 헷갈리기 쉬운 짝
            - **체계적 탈감작 vs 홍수법**: 약한 자극부터 단계적으로 노출하면 체계적 탈감작, 가장 강한 자극에 바로 노출하면 홍수법이다.
            - **토큰경제 vs 형성법**: 토큰을 모아 보상과 바꾸면 토큰경제, 목표에 가까워지는 단계마다 강화하면 형성법이다.
            - **인지재구성 vs 사고중지법**: 생각을 따져서 바꾸면 인지재구성, 생각을 "중지"로 끊으면 사고중지법이다.
            - **혐오요법 vs 처벌**: 혐오요법은 문제 행동을 불쾌한 자극과 짝짓는 것이다(예: 다이설피람).
            """#
        ),
        // 2026-94 아래에 붙은 설명
        TopicGuide(
            topics: ["외상후스트레스장애"],
            title: "외상후스트레스장애(PTSD) 환자의 간호중재",
            body: #"""
            PTSD 간호의 핵심은 안전감을 되찾게 하는 것이다. 대상자가 준비된 만큼 외상 경험과 감정을 표현하도록 돕는다.

            # 국시 출제 경향
            - 2020~2026년에 **3문항**이 나왔다(2021, 2024, 2026년). 2교시 93~95번 자리이다.
            - **PTSD 증상군 가리기**(2문항)
              - 2026-94 교통사고 후 자동차가 보일까 봐 창문을 신문지로 가리고 집에서만 지낸다 → **회피 증상**
              - 2024-93 교통사고 대상자가 TV 속 자동차를 보고 "피하세요!"라고 소리치며 벌벌 떤다 → **플래시백**
            - **PTSD 간호중재**(1문항)
              - 2021-95 강도 위협 후 악몽을 꾸고 사건이 생생하게 떠오른다 → **플래시백이나 과잉각성이 나타나는 동안 함께 있어준다**
            - 오답 보기의 구성
              - 2026-94: 과각성, 침습(재경험), 감정의 부정적 변화, 인지의 부정적 변화처럼 **PTSD의 다른 증상군**을 나열한다.
              - 2024-93: 회피, 불안, 집중력 장애, 부정적 인지를 섞는다. 특히 회피는 2026-94의 정답이라 두 문항이 서로를 가르는 짝이 된다.
              - 2021-95: 매일 새로운 간호사 배정(신뢰 관계 방해), 감정 표현 자제, 사건에 대해 이야기하지 않기, 악몽은 그냥 꿈이라고 안심시키기처럼 **경험을 억누르거나 가볍게 여기는 보기**를 섞는다.
            - 3문항 중 2문항이 **교통사고 후 자동차 자극**을 단서로 쓴다. 같은 단서로 회피와 플래시백을 가르는 것이 핵심이다.

            # 풀이 요령
            - 증상군은 사례의 행동으로 가른다.
              - 외상을 떠올리게 하는 자극을 피해 숨거나 외출하지 않는다 → 회피
              - 자극을 보고 사건이 지금 일어나는 것처럼 소리치고 몸을 피한다, 악몽 → 침습(재경험), 플래시백
              - 과민, 놀람 반응 증가, 수면장애 → 과각성
            - 중재는 **곁에 함께 있어 주어 안전감을 주는 것**을 고른다. 담당 간호사는 일관되게 유지한다.
            - 감정 표현을 막거나 사건 이야기를 금지하는 보기, 악몽을 가볍게 여기는 보기는 오답이다. 대상자가 준비된 만큼 경험과 감정을 표현하도록 격려한다.

            # 1. 이해를 위한 기본 내용

            # 진단 기준
            - 실제 죽음이나 심각한 부상, 성폭력 같은 외상 사건을 직접 겪거나 목격한 뒤에 생긴다.
            - 증상이 **1개월 이상** 계속될 때 PTSD로 진단한다.
            - 사건 뒤 3일에서 1개월 사이에만 증상이 있으면 **급성 스트레스장애**이다.

            # 네 가지 증상군
            - **침습(재경험)**
              - 원하지 않는데 사건이 계속 떠오른다.
              - 악몽을 꾼다.
              - **플래시백**이 나타난다. 사건이 지금 다시 일어나는 것처럼 느끼고 그렇게 행동한다.
              - 사건을 떠올리게 하는 단서에 몸과 마음이 강하게 반응한다.
            - **회피**
              - 사건과 관련된 생각이나 감정을 피한다.
              - 사건을 떠올리게 하는 장소, 사람, 물건, 상황을 피한다.
            - **인지와 감정의 부정적 변화**
              - 사건의 중요한 부분을 기억하지 못한다.
              - 자신이나 세상을 부정적으로 믿는다. 예: "세상은 위험하다."
              - 자신이나 남을 탓하고 죄책감(생존자 죄책감)을 느낀다.
              - 흥미를 잃고, 남과 멀어진 느낌이 들며, 긍정적인 감정을 느끼지 못한다.
            - **과각성**
              - 과민하고 분노가 폭발한다.
              - 무모하거나 자기파괴적인 행동을 한다.
              - 늘 경계하고(과잉경계), 잘 놀란다.
              - 집중하지 못하고 잠을 잘 못 잔다.
            **흔히 동반하는 문제**: 우울, 물질사용(자가치료 목적의 음주), 자살 위험, 대인관계와 직업 기능의 손상.

            # 2. 간호사정과 간호진단

            # 사정할 내용
            - 외상 사건의 종류와 시점
            - 현재 증상: 침습, 회피, 과각성
            - 수면과 악몽
            - 자살 생각과 자해 위험
            - 알코올과 약물 사용
            - 지지체계와 대처 방식
            - 일상생활 기능

            # 간호진단
            - **외상 후 증후군**: 2021-95의 진단명이다.
            - 불안, 수면양상 장애, 비효과적 대처, 사회적 고립
            - 자살 위험, 무력감

            # 3. 간호중재

            # ① 안전과 신뢰 관계
            - 조용하고 안전한 환경을 제공하고 자극을 줄인다.
            - **같은 간호사가 일관되게 돌본다.** 신뢰를 쌓아야 외상을 이야기할 수 있다.
            - 비판하지 않고 수용하는 태도를 보이며, 약속을 지킨다.
            - 자살 위험과 물질사용을 사정하고, 위험하면 안전 조치를 한다.

            # ② 플래시백이나 과각성이 나타날 때
            - **곁에 함께 있어 준다** (2021-95의 정답). 혼자 두면 공포가 커진다.
            - 차분하고 짧은 말로 **현재로 돌아오게(그라운딩) 돕는다.**
              - 예: "여기는 병원이고, 지금은 안전합니다. 저를 보세요."
              - 이름, 장소, 시간을 알려 준다.
              - 발바닥 감각이나 주변 사물처럼 오감에 집중하게 한다.
            - 천천히 깊게 숨쉬도록 안내한다.
            - 갑작스럽게 만지지 않는다. 신체 접촉은 먼저 허락을 구한다.

            # ③ 감정과 외상 경험의 표현
            - 대상자가 **준비된 속도에 맞춰** 사건과 감정을 이야기하도록 격려한다.
              - 억지로 끌어내지 않는다.
              - 반대로 이야기하지 말라고 막지도 않는다.
            - 감정반영과 개방적 질문을 사용한다.
              - 예: "지금 어떤 감정이나 생각이 드는지 좀 더 말해 보세요." (2020-94, 생존자 죄책감)
            - 그런 반응은 **비정상적인 사건에 대한 정상적인 반응**이라고 알려 준다(정상화).
            - 죄책감을 다룬다. 사건이 대상자 탓이 아니라는 것을 현실적으로 살펴보게 한다.
              - "잊어버리세요", "살아 있는 걸 기뻐하세요"처럼 감정을 무시하는 말은 하지 않는다.

            # ④ 불안과 수면 관리
            - 이완요법을 가르친다: 복식호흡, 점진적 근육이완, 심상요법.
            - 수면위생을 교육한다.
              - 일정한 취침 시간을 지킨다.
              - 카페인과 알코올을 피한다.
              - 잠들기 전에는 자극을 줄인다.
            - 악몽을 꾼 뒤에는 곁에 있어 주고 이야기를 들어 준다.
              - "그냥 꿈일 뿐"이라고 넘기지 않는다.
            - 운동과 규칙적인 일과를 유지하게 한다.

            # ⑤ 대처 기술과 사회적 지지
            - 외상을 떠올리게 하는 단서(촉발 요인)를 스스로 알아차리게 한다.
            - 촉발 요인에 대처하는 계획을 함께 세운다.
            - 건강한 대처 방법을 강화한다. 알코올로 자가치료하지 않도록 교육한다.
            - 가족을 교육하고 자조모임이나 지지모임을 연결한다.
            - 회피가 심하면 안전한 상황에서 조금씩 일상 활동으로 돌아가도록 돕는다.

            # ⑥ 치료와 약물
            - **외상 초점 인지행동치료**
              - 지속노출치료: 안전한 상황에서 외상 기억과 단서에 점진적으로 노출해 회피를 줄인다.
              - 인지처리치료: 자기비난과 부정적 믿음을 수정한다.
            - **EMDR**(안구운동 민감소실 및 재처리)
            - **약물**
              - 1차 약물은 **SSRI**(sertraline, paroxetine)이다.
              - 악몽에는 prazosin을 쓰기도 한다.
              - 벤조다이아제핀은 의존 위험이 있고 효과가 제한적이어서 장기 사용을 권하지 않는다.
            """#
        ),
        // 2026-96 아래에 붙은 설명
        TopicGuide(
            topics: ["성격장애의 유형", "성격장애 환자의 중재"],
            title: "성격장애의 유형, 특징, 대처법",
            body: #"""
            성격장애는 A·B·C 세 군, 열 가지 유형으로 나뉜다. 유형은 **유형마다 핵심어를 짝지어 외우고**, 간호의 핵심은 **일관된 제한설정과 중립적 태도**이다.

            # 국시 출제 경향
            - 2020~2026년에 **14문항**이 나왔다. **매년 2문항**씩 나왔고, 모두 2교시 96·97번 자리이다. 성격장애의 유형이 10문항, 성격장애 환자의 중재가 4문항이다.
            - **사례·특성을 보고 유형 이름 고르기**(7문항)
              - 2026-96 동료의 출신 대학을 비하하고 특별대우를 바라며, 갈등은 남들이 자신을 시기해서라고 여긴다 → **자기애성**
              - 2025-96 중요한 결정을 남자친구가 대신해 주기를 바라고 복종적 행동이 과도하다 → **의존성 성격장애**
              - 2024-96 초능력이 있는 비밀요원이라 믿고 특이한 복장으로 혼자 지낸다 → **조현형**
              - 2023-96 주목받으려 하고 부적절한 성적 유혹·도발적 행동을 보인다 → **연극성**
              - 2022-97 마술적 사고와 기이한 행동 → **조현형 성격장애**
              - 2021-96 정리정돈·완벽·질서에 몰두하고 융통성이 없으며 감정표현이 빈약하다 → **강박성 성격장애**
              - 2020-96 남편의 관심을 끌려고 수면제를 먹고 알리며, 유혹적으로 굴다가 쉽게 냉담해진다 → **히스테리성(연극성) 성격장애**
            - **유형을 주고 특성 고르기**(3문항)
              - 2025-97 반사회성 성격장애의 행동특성 → **타인의 권리를 침해하고 충동적이다**
              - 2024-97 강박성 성격장애의 특성 → **인색한 감정 표현과 융통성 없음**
              - 2022-96 반사회적 성격장애의 특성 → **양심과 죄책감이 결여되어 있다**
            - **성격장애 환자의 중재**(4문항)
              - 2026-97 경계성 환자가 남자친구 면회를 자유롭게 해 달라며 떼를 쓰고 화를 낸다 → **중립적인 태도로 병동의 규칙을 설명한다**
              - 2023-97 경계성 환자가 볼펜으로 손등을 자해해 피를 흘린다 → **중립적인 태도로 상처를 치료한다**
              - 2021-97 의심과 불신으로 적대적인 편집성 환자 → **중립적이고 사무적인 태도로 대한다**
              - 2020-97 반사회적 환자가 부딪쳤다며 욕설하고 난동을 부린다 → **수용될 수 없는 행동임을 설명하며 제한 설정을 한다**
            - 오답 보기의 구성
              - 유형 문항(2026-96, 2025-96, 2024-96, 2023-96, 2022-97, 2021-96, 2020-96): 편집성, 회피성, 의존성, 조현성 같은 **다른 유형 이름**을 돌려 쓴다. 편집성은 7문항 모두에 오답으로 나왔다.
              - 2024-96: 조현형의 짝으로 **조현성**을 넣는다. 조현성은 관계에 무관심하지만 기이한 믿음이나 행동은 없다.
              - 특성 문항(2025-97, 2024-97, 2022-96): 융통성 없음(강박성), 근거 없는 의심(편집성), 혼자 결정 못함·강한 애착(의존성), 비난에 대한 두려움·대인관계 회피(회피성), 화려한 외모(연극성), 기괴한 행동(조현형)처럼 **다른 유형의 특성**을 섞는다.
              - 2025-97: 책임감이 강하다, 양심의 가책을 느낀다처럼 **반사회성과 반대되는 모습**을 섞는다.
              - 중재 문항: 무시하기(2026-97, 2023-97), 요구를 들어주거나 규칙을 상황에 따라 바꾸기(2026-97, 2023-97), 동정·위로·친밀한 접근(2023-97, 2021-97, 2020-97), 비난·훈계·처벌·강박 위협(2026-97, 2023-97, 2020-97)을 섞는다.
              - 2021-97: 치료계획을 설명하지 않거나 모호하게 설명하기, 방어적인 접근처럼 **의심을 키우는 보기**를 섞는다.
            - 중재 4문항 중 3문항의 정답에 **중립적**이라는 말이 들어간다. 조현형은 2022년과 2024년, 연극성은 2020년과 2023년, 반사회성은 2022년과 2025년에 반복됐다.

            # 풀이 요령
            - 유형 문항은 사례의 핵심어로 가른다.
              - 과대감, 특별대우 기대, 공감 결여, 남들이 나를 시기한다 → 자기애성
              - 결정을 남에게 맡김, 복종, 돌봄 욕구 → 의존성
              - 마술적 사고, 초능력·텔레파시, 기이한 복장·행동 → 조현형
              - 관계에 무관심, 감정 표현 제한(기이함 없음) → 조현성
              - 관심 끌기, 성적 유혹·도발, 과장되고 빨리 바뀌는 감정 → 연극성(히스테리성)
              - 질서·완벽·통제, 융통성 없음, 인색한 감정 표현 → 강박성
              - 타인의 권리 침해, 충동성, 양심·죄책감 결여 → 반사회성
              - 근거 없는 의심과 불신 → 편집성
              - 거절·비난이 두려워 관계를 피함 → 회피성
            - 조현형과 조현성은 **기이함이 있는가**로 가른다. 기이한 믿음이나 행동이 있으면 조현형이다.
            - 중재 문항은 **중립적·사무적 태도, 일관된 규칙, 명확한 제한 설정**을 고른다. 동정·친밀한 접근·요구 들어주기는 조종을 강화하고, 비난·훈계·처벌·위협은 적대감을 키우므로 오답이다.
            - 경계성 환자의 자해에는 무시하지도 동정하지도 않고 **중립적으로 상처를 치료**한다. 편집성 환자에게는 치료계획을 **명확하고 솔직하게** 설명한다.

            # 1. 이해를 위한 기본 내용

            # 성격장애란
            - 생각하고 느끼고 관계 맺는 방식이 문화적 기대에서 크게 벗어나 있다.
            - 그 방식이 경직되어 있고, 청소년기나 초기 성인기부터 오래 지속된다.
            - 그 때문에 고통을 겪거나 사회·직업 기능이 손상된다.

            # 특징
            - 대상자는 문제를 자기 탓이 아니라 남이나 환경의 탓으로 보는 경우가 많다(자아동조적).
            - 그래서 스스로 치료를 원하는 일이 적고, 치료가 오래 걸린다.
            **분류**: DSM-5는 성격장애를 세 군으로 나눈다.
            - **A군**: 이상하고 괴짜 같다(편집성, 조현성, 조현형).
            - **B군**: 극적이고 감정적이며 변덕스럽다(반사회성, 경계성, 연극성, 자기애성).
            - **C군**: 불안하고 두려워한다(회피성, 의존성, 강박성).

            # 치료와 간호의 공통 원칙
            - 일관성을 유지한다. 모든 직원이 같은 규칙을 같은 방식으로 적용한다.
            - 명확한 제한설정을 한다.
            - 중립적이고 비판하지 않는 태도를 유지한다.
            - 행동에 책임을 지게 한다.
            - 감정을 행동이 아닌 말로 표현하게 돕는다.
            - 치료는 정신치료(변증법적 행동치료, 인지행동치료)가 중심이다. 약물은 증상을 조절하는 보조 수단이다.

            # 2. 유형별 특징과 대처법

            # A군: 이상하고 괴짜 같은 성격

            # 편집성 성격장애
            - **특징**
              - 근거 없이 남을 **의심하고 불신**한다.
              - 남이 자기를 이용하거나 해친다고 생각한다.
              - 원한을 오래 품는다.
              - 사소한 말에서 숨은 뜻과 모욕을 찾는다.
              - 방어적이고 적대적이며, 쉽게 반격한다.
              - 망상은 없다. 이 점에서 망상장애와 다르다.
            - **대처법** (2021-97)
              - **중립적이고 사무적이며 일관된 태도**로 대한다. 지나치게 친절하거나 친밀하게 다가가면 오히려 의심한다.
              - 치료계획, 검사, 약물은 **명확하고 솔직하게** 설명한다. 모호하면 의심이 커진다.
              - 약속을 지킨다.
              - 논쟁하거나 방어적으로 반응하지 않는다.
              - 대상자 앞에서 귓속말하거나 웃지 않는다.
              - 가능한 범위에서 스스로 결정하게 하여 통제감을 준다.

            # 조현성(schizoid) 성격장애
            - **특징**
              - 대인관계에 **무관심**하고 혼자 하는 활동을 좋아한다.
              - 감정 표현이 제한되어 냉담해 보인다.
              - 칭찬이나 비난에도 무관심하다.
              - 기이한 믿음이나 행동은 없다.
            - **대처법**
              - 대상자의 사생활과 거리를 존중한다.
              - 억지로 관계를 맺게 하지 않고, 짧고 부담이 적은 접촉부터 시작한다.
              - 관계를 점진적으로 넓히도록 사회기술훈련을 한다.

            # 조현형(schizotypal) 성격장애
            - **특징**
              - **마술적 사고**와 기이한 믿음이 있다(초능력, 텔레파시, 육감).
              - 관계사고와 특이한 지각 경험이 있다.
              - **괴상한 외모, 말, 행동**을 보인다.
              - 친밀한 관계가 없고 사회적 불안이 크다.
              - 조현병과 유전적으로 가깝지만, 뚜렷한 정신병 증상이 지속되지는 않는다.
            - **대처법**
              - 기이한 믿음과 논쟁하지 않고 현실을 부드럽게 알려 준다.
              - 사회기술훈련을 한다.
              - 스트레스를 받으면 정신병 증상이 생길 수 있으므로 관찰한다.
            - **조현성과 조현형의 구별**
              - 조현성은 무관심하지만 기이하지 않다.
              - 조현형은 **기이하다.**

            # B군: 극적이고 감정적이며 변덕스러운 성격

            # 반사회성 성격장애
            - **특징**
              - 15세 이전부터 품행장애가 있었다.
              - **타인의 권리를 무시하고 침해**한다(법 위반, 거짓말, 사기, 폭력).
              - 충동적이고 공격적이다.
              - 무책임하다.
              - **양심의 가책과 죄책감이 없다.**
              - 겉으로는 매력적이어서 남을 **조종**한다.
              - 18세 이상이어야 진단한다.
            - **대처법** (2020-97)
              - **수용할 수 없는 행동이 무엇인지 분명히 알리고**, 규칙과 결과를 일관되게 적용한다(제한설정).
              - 모든 직원이 같은 규칙을 지킨다. 조종에 넘어가지 않는다.
              - 행동의 결과에 스스로 책임지게 한다.
              - 훈계, 처벌, 논쟁은 반항과 적대감을 키운다.
              - 변명할 기회를 주면 합리화가 강해진다.
              - 정서적으로 친밀하게 접근하면 조종에 이용된다.
              - 폭력 위험을 사정하고 안전을 확보한다.

            # 경계성 성격장애
            - **특징**
              - **대인관계, 자아상, 정서가 불안정**하다.
              - 버림받는 것을 몹시 두려워한다.
              - 이상화와 평가절하를 오간다. 이것을 **분열(splitting)**이라 하며, 대표 방어기제이다.
              - 충동적이다(낭비, 폭식, 약물, 난잡한 성관계).
              - **자해와 자살 시도를 반복**한다.
              - 만성적인 공허감을 느낀다.
              - 분노를 조절하지 못한다.
              - 스트레스를 받으면 일시적으로 해리나 편집 증상이 나타난다.
              - 조종 행동을 한다.
            - **대처법** (2026-97, 2023-97)
              - **일관되고 명확한 제한설정**을 한다. 병동 규칙을 **중립적인 태도**로 설명한다.
              - 요구를 들어주거나 상황에 따라 규칙을 바꾸면 조종 행동이 강해진다.
              - 무시하거나 강박으로 위협하지 않는다.
              - **자해를 했을 때**
                - 감정적으로 반응하지 않고 **중립적이고 사무적으로 상처를 치료**한다.
                - 지나친 동정과 관심은 자해를 강화한다.
                - 비난은 수치심과 분노를 키운다.
              - 자해하기 전에 도움을 청하도록 **무자해 약속**을 맺는다.
              - 자해 대신 감정을 말로 표현하게 돕는다.
              - 분열에 대처한다.
                - 직원끼리 정기적으로 의사소통한다.
                - 한 간호사를 '좋은 사람', 다른 간호사를 '나쁜 사람'으로 나누는 말에 끌려가지 않는다.
              - 대상자와 관계의 경계를 분명히 한다. 특별대우와 개인적인 친밀함을 피한다.
              - 치료는 **변증법적 행동치료(DBT)**가 대표적이다. 감정조절, 고통 감내, 대인관계 기술, 마음챙김을 다룬다.

            # 연극성(히스테리성) 성격장애
            - **특징**
              - **관심의 중심**이 되지 않으면 불편해한다.
              - **부적절하게 성적으로 유혹하거나 도발적인 행동**을 한다.
              - 감정이 과장되고 빨리 바뀌며 피상적이다.
              - 외모로 관심을 끈다.
              - 암시를 잘 받는다.
              - 관계를 실제보다 친밀하다고 여긴다.
            - **대처법**
              - 극적인 행동에 과도하게 반응하지 않는다.
              - 적절한 행동에는 관심과 긍정적 강화를 준다.
              - 유혹적인 행동에는 전문적 관계의 경계를 분명히 한다.
              - 과장된 감정 밑에 있는 실제 감정과 욕구를 표현하게 돕는다.
            - **경계성과의 구별** (2020-96)
              - 수면제를 먹고 남편에게 알리는 등 관심을 끄는 극적인 행동을 한다.
              - 다른 환자에게 과도하게 친절하고 유혹적이다.
              - 이런 행동이 두드러지면 연극성이다.

            # 자기애성 성격장애
            - **특징**
              - 자기를 과대하게 보고 **특별대우를 기대**한다(특권의식).
              - **공감하지 못한다.**
              - 칭찬을 지나치게 원한다.
              - 남을 착취하거나 깎아내린다.
              - 남이 자기를 시기한다고 믿는다.
              - 비판에 매우 예민하다. 속으로는 자존감이 취약하다.
            - **대처법**
              - 과대함과 맞서거나 비웃지 않고, 중립적이고 일관된 태도를 유지한다.
              - 특별대우를 하지 않고 규칙을 똑같이 적용한다.
              - 실제 강점은 현실적으로 인정해 준다.
              - 다른 사람의 감정을 생각해 보게 돕는다.

            # C군: 불안하고 두려워하는 성격

            # 회피성 성격장애
            - **특징**
              - **비난과 거절이 두려워** 대인관계와 사회활동을 피한다.
              - 자신을 부족하다고 느낀다.
              - 받아들여질 것이 확실할 때만 관계를 맺는다.
              - 관계를 **원하지만 두려워서** 피한다. 이 점이 조현성과 다르다.
            - **대처법**
              - 수용적이고 지지적인 관계를 만든다.
              - 작은 사회적 접촉부터 점진적으로 늘린다.
              - 사회기술훈련과 자기주장훈련을 한다.
              - 성공 경험을 칭찬해 자존감을 높인다.
              - 인지치료로 거절에 대한 부정적 예측을 수정한다.

            # 의존성 성격장애
            - **특징**
              - **돌봄을 받고 싶은 욕구가 지나치다.**
              - 그래서 **복종적이고 매달린다.**
              - 일상적인 결정도 남의 조언과 확인 없이는 하지 못한다.
              - 혼자 남는 것을 두려워한다.
              - 관계가 끝나면 서둘러 다른 관계를 찾는다.
              - 반대 의견을 말하지 못한다.
            - **대처법** (2025-96)
              - 대신 결정해 주지 않고, **스스로 결정하고 선택하도록** 격려한다. 작은 결정부터 시작한다.
              - 독립적인 행동을 긍정적으로 강화한다.
              - 자기주장훈련을 한다.
              - 간호사에게 지나치게 의존하지 않도록 관계의 경계를 정한다.

            # 강박성 성격장애
            - **특징**
              - **질서, 완벽주의, 통제**에 지나치게 몰두한다.
              - **융통성이 없고** 규칙과 세부사항에 매달린다.
              - 일과 생산성에 몰두해 여가와 친구를 희생한다.
              - **감정 표현이 인색하고** 경직되어 있다.
              - 돈을 쓰는 데 인색하다.
              - 일을 남에게 맡기지 못한다.
            - **대처법**
              - 완벽하지 않아도 괜찮다는 것을 경험하게 한다.
              - 결정을 미루지 않도록 시간 제한을 둔다.
              - 감정을 알아차리고 표현하도록 돕는다.
              - 이완요법과 여가 활동을 권한다.
              - 인지치료로 흑백논리와 완벽주의 사고를 다룬다.
            - **강박장애와의 구별**
              - 강박성 성격장애에는 뚜렷한 강박사고와 강박행동이 없다.
              - 대상자는 자기 성향을 문제로 느끼지 않는다(자아동조적).
              - 강박장애는 강박사고와 강박행동이 있고, 스스로 괴로워한다(자아이질적).
            """#
        ),
        // 2026-98 아래에 붙은 설명
        TopicGuide(
            topics: ["물질 관련 장애", "알코올 관련 장애"],
            title: "남용 가능 물질의 분류, 간호사정, 간호중재",
            body: #"""
            남용 물질은 억제제, 자극제, 아편류, 환각제, 대마로 나누고, 알코올은 금단의 시간 경과와 영양 결핍 합병증을 따로 정리한다. **물질이 어느 계열인지 알고, 중독 증상과 금단 증상이 서로 반대라는 것**을 기억하면 대부분의 문항이 풀린다.

            # 국시 출제 경향
            - 2020~2026년에 **14문항**이 나왔다. **매년 2문항**씩 나왔고, 모두 2교시 98·99번 자리이다. 해마다 물질 관련 장애 1문항과 알코올 관련 장애 1문항이 짝을 이룬다.
            - **물질별 특성과 분류**(5문항)
              - 2026-98 마리화나의 특성 → **심리의존이 있다**
              - 2025-98 암페타민의 특성 → **다행감과 각성효과를 보인다**
              - 2024-99 집중력이 좋아진다는 약을 먹은 고등학생이 불안, 초조, 불면을 호소한다 → **메스암페타민**
              - 2021-98 중추신경자극제에 해당하는 것 → **코카인**
              - 2020-98 시공간 지각 변화, 풍부한 색·촉감, 플래시백을 일으키는 물질 → **환각제**
            - **물질 관련 개념과 치료약물**(2문항)
              - 2023-98 감수성이 떨어져 같은 효과를 얻으려 용량을 늘리는 현상 → **내성**
              - 2022-99 아편 중독 치료와 금단증상 완화에 쓰는 약물 → **메타돈(methadone)**
            - **알코올 금단과 합병증**(4문항)
              - 2025-99 30년 음주 환자가 기억나지 않는 부분을 무의식적으로 꾸며 대답한다 → **작화증**
              - 2024-98 만성 알코올중독 환자에게 입원 후 2~3일에 나타날 수 있는 금단증상 → **손의 진전**
              - 2023-99 마지막 음주 후 2~3일경에 나타날 수 있는 증상 → **진전섬망**
              - 2021-99 입원 직전까지 술을 마신 환자에게 입원 2일 후 나타날 수 있는 금단증상 → **진전**
            - **알코올 사용장애 환자의 중재·평가**(3문항)
              - 2026-99 싸이아민 투약을 거부하는 환자에게 할 설명 → **베르니케뇌병증 같은 신경계 손상을 예방하는 데 필요하다**
              - 2022-98 집단요법에서 자신의 문제를 가장 잘 이해하는 반응 → **자조모임 참석을 중단하면 재발 위험이 높아진다**
              - 2020-99 술을 마시고 길에서 싸움을 벌인 뒤 입원한 환자 → **음주행위와 최근의 싸움이 관련 있음을 인식시킨다**
            - 오답 보기의 구성
              - 2024-99, 2021-98, 2020-98: 코데인·헤로인·모르핀(아편류), 디아제팜·알프라졸람·페노바비탈(억제제), 알코올처럼 **다른 계열의 물질**을 나열한다.
              - 2025-98: 식욕 증가, 불면증 치료, 동공축소, 의존 없음처럼 **자극제와 반대되는 효과**를 섞는다. 동공축소는 아편류의 특징이다.
              - 2026-98: 강한 내성·중독성·신체의존, 진정수면제로 분류처럼 **마리화나에 해당하지 않는 특성**을 섞는다.
              - 2023-98: 금단, 이중진단, 공동의존, 플래쉬백처럼 **다른 물질 관련 용어**를 나열한다.
              - 2022-99: 모르핀, 데메롤, 코데인, 헤로인처럼 **남용되는 아편류 자체**를 섞는다.
              - 2024-98, 2021-99: 느린 맥박, 동공 축소, 체온 저하, 혈압 저하, 기면처럼 **교감신경 항진과 반대되는 증상**을 섞는다.
              - 2023-99, 2025-99: 말초신경염, 알코올성치매, 베르니케증후군, 코르사코프증후군 같은 **만성 합병증**과 진전섬망, 기억상실을 서로 섞는다.
              - 2022-98: 합리화("잠이 안 와서", "사회생활에 필수"), 부정("언제든지 끊을 수 있다"), 투사(가족 탓)를 섞는다.
              - 2020-99, 2026-99: 사회적 음주 모색, 비판적 태도, 배우자 책임, 조건부 수용, 권위에 기댄 설명("의사의 처방이니"), 자조그룹으로 약 대신하기를 섞는다.
            - 알코올 금단 시기를 묻는 문항이 3번(2024-98, 2023-99, 2021-99) 나왔고, **입원·마지막 음주 후 2~3일**이 반복되는 단서이다. 중추신경자극제(코카인, 암페타민, 메스암페타민)도 3번 정답이 됐다.

            # 풀이 요령
            - 물질은 **계열**부터 가른다.
              - 코카인, 암페타민, 메스암페타민 → 자극제: 다행감, 각성, 불면, 식욕 저하, 동공 확대, 빈맥
              - 코데인, 헤로인, 모르핀, 데메롤 → 아편류: 진정, 동공축소, 호흡억제. 대체요법은 메타돈, 과량 해독제는 날록손
              - 디아제팜, 알프라졸람, 페노바비탈 → 억제제: 진정, 졸림
              - LSD 등 환각제 → 시공간 지각 변화, 공감각, 플래시백
              - 마리화나 → 주로 심리의존, 신체의존과 내성은 약하다
            - 알코올 금단은 **교감신경 항진**이므로 진전, 발한, 빈맥, 혈압·체온 상승, 동공 확대를 고른다. 느린 맥박, 저혈압, 체온 저하, 기면은 오답이다.
            - 시기로 가른다.
              - 마지막 음주 후 6~24시간부터 → 진전, 발한, 불안, 불면
              - 48~72시간(2~3일) → 진전섬망(의식 혼란, 환시, 심한 떨림)
              - 장기 음주와 싸이아민 결핍 → 베르니케뇌병증, 코르사코프증후군(작화증), 말초신경염, 알코올성 치매
            - 알코올 환자 중재는 **부정과 합리화를 깨고 음주와 결과의 관련성을 인식시키는 것**을 고른다. 목표는 절주가 아니라 단주이고, 비판이나 조건부 수용, 배우자 탓은 오답이다.
            - 치료 효과 평가 문항은 스스로 통제할 수 없음을 인정하고 **자조모임을 계속해야 한다**고 말하는 반응을 고른다.

            # 1. 이해를 위한 기본 용어
            - **물질사용장애**
              - 조절하지 못한 채 물질을 계속 사용해 기능이 손상된 상태이다.
              - 사회적 문제나 위험이 생겨도 계속 사용한다.
              - 내성이나 금단이 나타난다.
            - **중독(intoxication)**: 물질을 사용한 직후 나타나는 급성 변화이다. 예: 술에 취한 상태.
            - **내성(tolerance)**: 반복해서 사용하면 같은 효과를 얻는 데 **더 많은 양이 필요**해진다 (2023-98).
            - **금단(withdrawal)**: 사용을 중단하거나 줄였을 때 나타나는 증상이다. 대개 **중독 증상과 반대 방향**이다.
            - **심리적 의존**: 물질이 없으면 불안해지고 갈망이 생긴다.
            - **신체적 의존**: 물질을 끊으면 신체적 금단증상이 나타난다.
            - **교차내성**: 같은 계열의 한 물질에 내성이 생기면 다른 물질에도 내성이 생긴다.
              - 예: 알코올과 벤조다이아제핀.
              - 그래서 알코올 금단을 벤조다이아제핀으로 치료한다.
            - **이중진단**: 물질사용장애와 다른 정신질환이 함께 있는 것이다.
            - **공동의존(co-dependency)**
              - 중독자의 가족이 중독 행동에 얽매여 있는 상태이다.
              - 가족이 대신 책임을 지거나 뒤처리를 해 주어 중독을 오히려 유지시킨다(enabling).
            - **플래시백**: 환각제를 끊은 뒤에도 환각 경험이 갑자기 다시 나타나는 것이다.

            # 2. 남용 가능 물질의 분류

            # ① 중추신경억제제: 알코올, 벤조다이아제핀, 바비튜레이트
            - **해당 약물**
              - 알코올
              - 벤조다이아제핀: 디아제팜, 알프라졸람, 로라제팜
              - 바비튜레이트: 페노바비탈
              - 흡입제(본드, 가스)도 억제 작용을 한다.
            - **중독 증상**
              - 진정, 졸림, 발음이 불분명해진다.
              - 운동실조가 생기고 판단력이 떨어진다.
              - 탈억제로 공격적이 되기도 한다.
              - 과량이면 **호흡억제**, 혼수, 사망에 이른다.
              - 다른 억제제와 함께 쓰면 위험이 더 커진다.
            - **금단 증상**
              - 교감신경이 항진된다: 진전, 발한, 빈맥, 혈압과 체온 상승, 불안, 불면.
              - **경련**과 섬망이 생길 수 있어 생명을 위협한다.
              - 그래서 갑자기 끊지 않고 서서히 줄인다.
            - **해독제와 치료**
              - 벤조다이아제핀 과량에는 **flumazenil**을 쓴다.
              - 금단은 벤조다이아제핀을 점차 줄이며 치료한다.

            # ② 중추신경자극제: 암페타민, 메스암페타민, 코카인
            - **해당 약물**
              - 암페타민
              - 메스암페타민(필로폰)
              - 코카인
              - MDMA(엑스터시)
              - 카페인과 니코틴도 자극제이다.
            - **중독 증상** (2025-98, 2024-99, 2021-98)
              - 도파민과 노르에피네프린이 증가한다.
              - **다행감, 각성**, 집중력과 활력이 커진다.
              - **식욕이 줄고 불면**이 생긴다.
              - 불안과 초조가 나타난다.
              - 교감신경이 흥분한다: **동공 확대**, 빈맥, 고혈압, 고체온.
              - 과량이면 부정맥, 심근경색, 경련이 생긴다.
              - **편집증적 정신병**이 생길 수 있다.
                - 망상과 환각이 나타난다.
                - 코카인 사용 시 피부에 벌레가 기어가는 느낌(개미주행감)이 들기도 한다.
            - **금단 증상**
              - 중독과 반대로 나타난다: 피로, **과다수면**, 식욕 증가.
              - **우울**과 무쾌감이 생기고, 갈망이 강하다.
              - **자살 위험**이 있으므로 관찰한다.
            - **의존**: **심리적 의존이 강하다.** 의존이 없다는 보기는 오답이다.

            # ③ 아편류(마약성 진통제): 헤로인, 모르핀, 코데인
            - **해당 약물**
              - 헤로인, 모르핀, 코데인
              - 메페리딘(데메롤), 펜타닐, 옥시코돈
            - **중독 증상**
              - 다행감 뒤에 진정과 졸림이 온다.
              - **동공이 축소**된다(축동). 이것이 핵심 감별점이다.
              - 호흡이 억제된다.
              - 변비가 생긴다.
              - 과량이면 **축동, 호흡억제, 혼수**가 3대 징후이다.
            - **금단 증상**
              - 중독과 반대로 나타난다.
                - 동공 확대, 콧물, 눈물, 하품
                - 소름(立毛)
                - 복통, 설사, 근육통
                - 불안, 불면
              - 매우 괴롭지만 생명을 위협하는 경우는 드물다.
            - **치료 약물**
              - 과량에는 **naloxone**을 쓴다. 아편 수용체 길항제이다.
              - **methadone 유지요법** (2022-99)
                - 작용 시간이 긴 합성 아편제로 헤로인을 대체한다.
                - 금단과 갈망을 줄인다.
              - buprenorphine도 대체요법에 쓴다.
              - naltrexone은 재발을 예방한다.
            - **주의**: 모르핀, 데메롤, 코데인, 헤로인은 모두 **남용 물질**이지 치료약이 아니다.

            # ④ 환각제: LSD, 메스칼린, 실로시빈, PCP
            - **중독 증상** (2020-98)
              - **시간과 공간에 대한 지각이 바뀐다.**
              - 공감각이 생긴다. 색을 듣고 소리를 보는 것처럼 느낀다.
              - 감각이 강렬해진다.
              - 이인증과 비현실감이 생긴다.
              - 공황을 동반한 나쁜 경험(bad trip)을 하기도 한다.
              - 동공이 확대되고 빈맥이 생긴다.
            - **특징**
              - **플래시백**이 생긴다. 이를 환각제 지속성 지각장애라 한다.
              - 신체적 의존과 금단은 거의 없다.
            - **PCP(펜시클리딘)**
              - 폭력성이 나타난다.
              - 안진(눈떨림)이 생긴다.
              - 통증을 느끼지 못한다.
              - 자극을 최소화하는 것이 중요하다.
            - **나쁜 경험에 대한 간호**
              - 조용하고 자극이 적은 환경을 제공한다.
              - 곁에 있어 주며, 약물 때문이고 일시적이라고 안심시킨다(talk down).

            # ⑤ 대마: 마리화나, 해시시
            - **중독 증상** (2026-98)
              - 다행감과 이완감이 든다.
              - 시간 감각이 왜곡된다.
              - **결막이 충혈**된다.
              - **식욕이 증가**하고 입이 마른다.
              - 빈맥이 생긴다.
            - **특징**
              - **주로 심리적 의존**을 일으킨다.
              - 신체적 의존과 내성은 약하다.
              - 진정수면제가 아니라 **대마류로 따로 분류**한다.
            - **장기 사용 시**
              - **무동기증후군**이 생긴다. 의욕이 없고 무관심해진다.
              - 기억력과 집중력이 떨어진다.
              - 정신병 위험이 커진다.

            # ⑥ 기타 물질
            - **니코틴**
              - 자극제이다.
              - 금단 시 과민, 불안, 집중력 저하, 식욕 증가가 나타난다.
              - 니코틴 대체요법, bupropion, varenicline으로 치료한다.
            - **흡입제(본드, 부탄가스)**
              - 청소년에게 흔하다.
              - 급사할 수 있고 뇌, 간, 신장이 손상된다.
            - **카페인**
              - 중독 시 불안, 불면, 빈맥이 나타난다.
              - 금단 시 두통과 피로가 나타난다.

            # 구별 요점
            - **동공**
              - 자극제와 환각제, 아편 금단 → 확대
              - 아편 중독 → 축소
            - **식욕**
              - 자극제 → 감소
              - 대마 → 증가
            - **생명을 위협하는 금단**
              - 알코올, 벤조다이아제핀, 바비튜레이트: 경련과 섬망
              - 자극제 금단: 우울과 자살 위험
            - **대체약물과 해독제**
              - 아편 대체 → methadone
              - 아편 해독 → naloxone
              - 벤조다이아제핀 해독 → flumazenil

            # 3. 알코올 관련 장애

            # 알코올 금단의 시간 경과 (2024-98, 2023-99, 2021-99)
            - **6~24시간**
              - **손 떨림(진전)**, 발한, 빈맥, 혈압과 체온 상승이 나타난다.
              - 불안, 불면, 오심이 생긴다.
              - 교감신경 항진 상태이다.
            - **12~48시간**
              - 알코올성 환각증이 생긴다. 주로 환청이며, 의식은 맑다.
              - 금단 경련이 생긴다.
            - **48~72시간: 진전섬망(DT)**
              - 의식이 혼란하고 지남력을 잃는다.
              - **생생한 환시**가 나타난다. 벌레나 작은 동물이 보이기도 한다.
              - 심하게 떨고 열이 나며, 빈맥과 발한이 있다.
              - 생명을 위협한다.
            - 금단은 **항진** 상태이다. 느린 맥박, 동공 축소, 체온 저하, 혈압 저하, 기면, 식욕 상승은 오답이다.

            # 영양 결핍 합병증: 싸이아민(비타민 B1) 결핍
            - **베르니케뇌병증**
              - 급성이며, 제때 치료하면 회복될 수 있다.
              - 3대 증상은 **안구운동장애(안진), 운동실조, 혼돈**이다.
            - **코르사코프증후군**
              - 만성이다.
              - 새로운 것을 기억하지 못한다(**전진성 기억상실**).
              - **작화증**이 나타난다 (2025-99). 기억의 빈틈을 무의식적으로 꾸며 채운다. 거짓말과 달리 의도가 없다.
            - **싸이아민 투여 목적** (2026-99)
              - **베르니케뇌병증 같은 신경계 손상을 예방**하기 위해 투여한다.
              - 포도당보다 먼저 투여한다.
            - **그 밖의 합병증**
              - 말초신경염, 알코올성 치매
              - 간경변, 췌장염, 위장관 출혈

            # 알코올 치료 약물
            - **disulfiram(안타부스)**
              - 혐오요법이다.
              - 복용 중 술을 마시면 홍조, 두통, 오심, 구토, 빈맥, 저혈압이 생긴다.
              - 소량의 알코올에도 반응한다. 알코올이 든 음식, 구강청결제, 화장품, 소독제를 피하도록 교육한다.
              - 마지막 음주 후 최소 12시간이 지나서 시작한다.
              - 대상자의 동의가 반드시 필요하다.
            - **naltrexone, acamprosate**: **갈망을 줄인다.**
            - **벤조다이아제핀**: 해독과 금단 치료에 쓴다. 용량을 점차 줄인다.
            - **싸이아민, 엽산, 종합비타민**: 영양 결핍을 교정한다.

            # 4. 간호사정

            # 물질 사용력
            - 물질의 종류, 양, 빈도, 기간, 경로
            - **마지막으로 사용한 시점**: 금단이 언제 나타날지 예측하는 데 가장 중요하다.
            - 여러 물질을 함께 쓰는지

            # 선별도구
            - **CAGE**
              - C(Cut down): 줄여야겠다고 느낀 적이 있는가?
              - A(Annoyed): 남의 비난에 화가 난 적이 있는가?
              - G(Guilty): 죄책감을 느낀 적이 있는가?
              - E(Eye-opener): 아침에 해장술을 마신 적이 있는가?
            - **AUDIT**
            - **CIWA-Ar**: 알코올 금단의 중증도를 평가한다.

            # 신체 사정
            - 활력징후. 금단 초기에는 빈맥, 고혈압, 발열을 확인한다.
            - 동공, 진전, 발한
            - 의식과 지남력
            - 영양 상태, 간 기능
            - 주사 자국, 감염(HIV, 간염)

            # 심리사회 사정
            - **방어기제**
              - 부정: "나는 언제든 끊을 수 있다."
              - 합리화: "잠이 안 와서 마셨을 뿐이다."
              - 투사: "가족이 잘해 주면 안 마신다."
            - 동반 정신질환(이중진단), 자살 위험
            - 가족의 공동의존, 법적·직업적 문제
            - 동기와 변화 단계
              - 변화 단계는 인식 전 → 인식 → 준비 → 실행 → 유지 순이다.

            # 간호진단
            - 손상 위험(금단, 경련, 섬망)
            - 영양 불균형
            - 비효과적 부정, 비효과적 대처
            - 가족과정 기능장애
            - 수면양상 장애, 자살 위험

            # 5. 간호중재

            # ① 급성기: 중독과 해독, 금단 관리 (안전 최우선)
            - 활력징후와 의식을 자주 관찰한다. 금단 척도(CIWA)로 평가한다.
            - 처방된 벤조다이아제핀을 투여하고 점차 줄인다.
            - **경련에 대비**한다. 침대 난간을 올리고 흡인기를 준비한다.
            - 조용하고 밝은 방에서 **자극을 줄인다.**
              - 어두우면 착각과 환시가 심해진다.
            - 섬망 환자에게는 지남력을 자주 알려 준다.
              - 환시에 대해 논쟁하지 않고, 짧고 차분하게 현실을 알려 준다.
            - 수분, 전해질, 영양을 공급한다. **싸이아민을 투여**한다.
            - 아편 과량 → naloxone, 벤조다이아제핀 과량 → flumazenil. 이때 호흡을 유지한다.
            **② 부정 다루기와 문제 인식** (2020-99)
            - **음주와 그 결과 사이의 관련성을 인식하도록 돕는다.**
              - 예: 음주와 최근의 싸움이 관련 있다는 것
              - 사실에 근거해 비판하지 않고 직면시킨다.
            - 대상자는 수용하되, 물질 사용 행동은 수용하지 않는다. 비판적 태도, 조건부 수용, 훈계는 관계를 해친다.
            - 책임은 대상자에게 있다. 배우자나 가족에게 책임을 돌리지 않는다.
            - **치료 목표는 단주**이다. 절주나 "안전한 사회적 음주"는 목표가 아니다.
            - 동기강화면담을 한다. 변화 단계에 맞춰 양가감정을 다룬다.

            # ③ 재활과 재발 예방
            - **자조모임**에 참여하게 한다: AA(단주친목), NA(약물중독자 모임), 12단계 프로그램.
              - 참여를 계속하는 것이 회복의 핵심이다 (2022-98).
            - 재발의 고위험 상황(사람, 장소, 감정)을 찾아내고 대처 계획을 세운다.
            - 스트레스 관리, 이완, 대체 활동을 가르친다.
            - 거절 기술과 자기주장훈련을 한다.
            - 집단치료와 인지행동치료를 한다.
            - 약물요법을 교육한다: disulfiram 주의사항, naltrexone, acamprosate, methadone.
            - 재발은 실패가 아니라 회복 과정의 일부로 다루고, 다시 치료에 참여하게 한다.

            # ④ 가족 중재
            - 가족에게 질병과 공동의존을 교육한다.
            - 대신 뒤처리를 해 주지 않도록 한다(enabling을 중단한다).
            - 가족 자조모임(알아넌 Al-Anon, 알아틴 Alateen)을 연결한다.
            - 가족치료를 한다.

            # ⑤ 신체 건강과 기타
            - 균형 잡힌 식사, 비타민, 수면위생
            - 감염 예방: 주사기를 함께 쓰지 않는다. 간염과 HIV 검사를 받는다.
            - 동반 정신질환을 함께 치료한다(이중진단).
            """#
        ),
        // 2026-100 아래에 붙은 설명
        TopicGuide(
            topics: ["섬망과 치매"],
            title: "섬망과 치매의 간호중재",
            body: #"""
            섬망은 급성이고 되돌릴 수 있으며, 치매는 서서히 진행한다. 두 질환 모두 **안전하고 자극이 적고 일관된 환경, 지남력 제공, 짧고 간단한 의사소통**이 간호의 기본이다.

            # 국시 출제 경향
            - 2020~2026년에 **6문항**이 나왔다(2025년을 뺀 매해: 2020, 2021, 2022, 2023, 2024, 2026년). 모두 2교시 100번 자리이다.
            - **치매 환자의 환경 관리와 가족 교육**(2문항)
              - 2026-100 치매 노인의 가족에게 주는 교육 → **일상생활을 규칙적으로 유지한다**
              - 2020-100 배회·초조를 보이는 치매 환자의 '상해의 위험' → **자극이 적은 환경을 유지한다**
            - **치매 환자와의 의사소통**(2문항)
              - 2022-100 주요 신경인지장애(치매) 환자의 간호중재 → **한 번에 한 가지씩 천천히 지시한다**
              - 2021-100 기억력 장애, 배회, 분노를 보이는 75세 여자와의 의사소통 → **간단한 문장을 사용한다**
            - **섬망 환자의 간호중재**(2문항)
              - 2024-100 수술 후 중환자실에서 "감옥에 가두느냐"며 침대에서 나오려는 75세 → **시간, 장소, 사람을 자주 알려 준다**
              - 2023-100 섬망 환자의 간호중재 → **구체적인 용어로 대화한다**
            - 오답 보기의 구성
              - 조명을 끄거나 어둡게 하기가 2026-100, 2024-100, 2023-100, 2020-100에 모두 나온다.
              - 돌보는 사람이나 간호사를 자주 바꾸기가 2026-100, 2024-100, 2020-100에 나온다.
              - 지남력 단서를 없애는 보기: 시계와 달력을 두지 않기(2023-100), 숫자가 작은 시계(2026-100), 가구 위치를 주기적으로 바꾸기(2026-100), 안경·보청기를 간호사실에 보관(2024-100)
              - 자극과 부담을 늘리는 보기: 한 번에 여러 가지 지시(2023-100), 다양한 방문객 허용(2023-100), 새로운 지식·복잡한 활동·많은 음식(2022-100), 추상적 단어·개방형 질문·의사결정 요구(2021-100), 높은 톤이나 큰 소리(2022-100, 2021-100)
              - 2024-100은 진정제 투여, 2020-100은 활동 범위를 병실로 제한하기·집단치료 제한을 섞는다.
            - 섬망과 치매 모두 **일관성, 단순함, 적절한 조명, 지남력 단서**라는 같은 원칙이 반복해서 정답과 오답을 가른다.

            # 풀이 요령
            - 먼저 사례가 섬망인지 치매인지 가린다. 수술 후 갑자기 생긴 혼란·착각은 섬망, 서서히 진행된 기억장애·배회는 치매이다. 다만 중재 원칙은 거의 같다.
            - 환경 보기는 다음처럼 고른다.
              - 조명 → 끄지 않고 은은한 야간 조명을 유지한다
              - 돌보는 사람 → 바꾸지 않고 일관되게 유지한다
              - 시계·달력·가구 → 크고 잘 보이게 두고, 위치는 바꾸지 않는다
              - 안경·보청기 → 환자 곁에 둔다
            - 의사소통 보기는 **짧고 간단한 문장, 구체적인 말, 한 번에 한 가지, 천천히, 낮고 차분한 톤**이 들어간 것을 고른다. 추상적 단어, 개방형 질문, 의사결정 요구, 여러 지시, 높은 톤은 오답이다.
            - "새로운", "다양한", "복잡한", "자주 변경" 같은 말이 들어간 보기는 혼란을 키우므로 지운다. **규칙적, 일관된, 자극이 적은**이 정답 쪽 표현이다.
            - 진정제나 활동 제한처럼 억제하는 보기는 일차 중재가 아니다. 안전은 환경을 조정해서 지킨다.

            # 1. 이해를 위한 기본 내용: 섬망과 치매의 구별

            # 섬망(delirium)
            - **발병**: **급격하다.** 수 시간에서 며칠 사이에 생긴다.
            - **경과**
              - **하루 중에도 변동**이 심하다. 밤에 더 나빠진다.
              - 원인을 치료하면 대개 **회복된다(가역적).**
            - **핵심 증상**
              - **의식 수준과 주의력의 장애**
              - 지남력 장애, 특히 시간에 대한 지남력
              - 지각장애: **착각과 환시**가 흔하다.
              - 수면-각성 주기가 뒤바뀐다.
              - 초조하거나(과활동형), 반대로 조용하고 무기력하다(저활동형). 저활동형은 놓치기 쉽다.
            - **원인**
              - 수술 후, 감염(요로감염, 폐렴), 탈수, 전해질 이상, 저산소증
              - 약물: 항콜린제, 벤조다이아제핀, 마약성 진통제
              - 알코올 금단(진전섬망)
              - 통증, 수면 부족
              - 중환자실 환경, 감각 결손
            - **위험군**: 고령자, 치매가 있는 사람, 수술 환자
            - **응급 여부**: **의학적 응급**이다. 원인을 찾아 교정하는 것이 가장 중요하다.

            # 치매(주요 신경인지장애)
            - **발병**: **서서히** 시작해 수개월에서 수년에 걸쳐 진행한다.
            - **경과**: 대부분 **진행성이고 비가역적**이다(알츠하이머병, 혈관성 치매 등).
            - **핵심 증상**
              - **의식은 맑다.**
              - 기억장애가 나타나며, 최근 기억부터 잃는다.
              - 인지기능 장애
                - 실어증: 말을 이해하거나 표현하지 못한다.
                - 실행증: 동작을 수행하지 못한다.
                - 실인증: 사물이나 사람을 알아보지 못한다.
                - 실행기능 장애: 계획하고 판단하지 못한다.
              - 지남력 장애가 시간, 장소, 사람 순으로 진행한다.
            - **행동심리증상(BPSD)**
              - 배회, 초조, 공격성
              - 의심, 망상(물건을 도둑맞았다는 망상)
              - 우울, 수면장애
              - **해질녘증후군(sundowning)**: 해질녘과 밤에 혼란과 초조가 심해진다.
            - **대처 방식**
              - 기억의 빈틈을 채우려고 **작화증**을 보인다.
              - 기억하지 못하는 것을 숨기려고 **파국반응**을 보인다. 해내지 못할 일을 요구받으면 갑자기 울거나 화를 낸다.
            - **치료 약물**
              - 콜린에스테라제 억제제: 도네페질, 리바스티그민, 갈란타민
              - NMDA 길항제: 메만틴
              - 진행을 늦추는 약이며, 완치하는 약은 아니다.

            # 구별 요점
            - **급격하고 의식이 흐리며 변동**하면 섬망이다.
            - **서서히 오고 의식이 맑으며 진행**하면 치매이다.
            - 치매가 있는 노인에게 섬망이 겹칠 수 있다. 치매 환자가 갑자기 나빠지면 섬망을 의심한다.

            # 2. 간호사정

            # 섬망
            - 의식 수준, 주의력, 지남력을 **하루에도 여러 번 반복**해서 사정한다.
            - 선별도구: CAM, 중환자실에서는 CAM-ICU를 쓴다.
            - 원인을 사정한다.
              - 활력징후, 산소포화도
              - 섭취량과 배설량, 탈수
              - 검사 결과: 전해질, 혈당, 감염 지표
              - 투약 목록, 특히 항콜린제와 진정제
              - 통증, 배뇨와 배변(요정체, 변비)
              - 음주력
            - 착각, 환시, 초조를 관찰한다. 낙상하거나 관을 빼는 등 안전 위험을 확인한다.

            # 치매
            - 인지 기능: MMSE(K-MMSE), MoCA, CDR
            - 일상생활 수행능력: ADL, IADL
            - 행동심리증상: 배회, 공격성, 수면, 망상, 우울
            - 안전 위험: 낙상, 길 잃음, 화재, 약물 오용
            - 영양과 연하 상태, 배설
            - 남아 있는 능력과 강점, 생활력(습관과 선호)
            - **가족 돌봄자의 부담**과 소진

            # 간호진단
            - 급성 혼란(섬망), 만성 혼란(치매)
            - **상해(손상) 위험** (2020-100), 낙상 위험
            - 사고과정 장애, 언어적 의사소통 장애
            - 자가간호 결핍, 수면양상 장애, 영양 불균형
            - 배회
            - 돌봄자 역할 긴장

            # 3. 공통 간호중재: 섬망과 치매 모두에 해당

            # ① 환경: 안전하고, 자극이 적고, 일관되게
            - **적절한 조명**을 유지한다.
              - 밤에는 은은한 **야간등**을 켠다.
              - 어두우면 착각, 환시, 해질녘 혼란, 낙상이 심해진다.
              - **"밤에 조명을 끈다", "어둡게 한다"는 항상 오답**이다 (2026-100, 2024-100, 2023-100, 2020-100).
            - **자극이 적고 조용한 환경**을 유지한다 (2020-100).
              - 소음, TV, 사람의 출입을 줄인다.
              - 방문객은 **익숙한 소수**로 제한한다 (2023-100). "다양한 방문객 허용"은 오답이다.
            - **같은 간호사가 일관되게** 돌본다 (2026-100, 2024-100, 2020-100).
              - "돌보는 사람을 자주 바꾼다", "매일 새로운 간호사"는 오답이다.
            - 가구와 물건의 **위치를 바꾸지 않는다** (2026-100).
            - 낙상을 예방한다.
              - 침대를 낮추고 바퀴를 잠근다.
              - 바닥의 장애물을 치운다.
              - 미끄럼 방지 신발을 신긴다.
              - 호출벨은 손이 닿는 곳에 둔다.
            - 억제대는 되도록 쓰지 않는다. 초조와 손상이 커진다.
              - 가까이서 관찰하고, 가족이 함께 있게 하는 방법을 먼저 쓴다.

            # ② 지남력 제공과 감각 보조
            - **시간, 장소, 사람을 자주 알려 준다** (2024-100).
              - 예: "지금은 오후 3시이고, 여기는 ○○병원입니다. 저는 간호사 ○○입니다."
            - **숫자가 크고 잘 보이는** 시계와 달력을 둔다 (2026-100, 2023-100).
              - "시계와 달력을 두지 않는다", "숫자가 작은 시계"는 오답이다.
            - **안경, 보청기, 틀니, 지팡이를 환자 곁에** 둔다 (2024-100).
              - 감각 입력이 줄면 혼란이 커진다.
              - "간호사실에 보관한다"는 오답이다.
            - 가족사진이나 익숙한 물건을 두어 안정감을 준다.

            # ③ 의사소통
            - **짧고 간단하며 구체적인 말**로 한다 (2023-100, 2021-100).
            - **한 번에 한 가지씩, 천천히** 지시한다 (2022-100).
            - **낮고 차분한 목소리**로 말한다.
              - 높은 톤이나 고함은 화난 것으로 받아들인다 (2022-100, 2021-100).
              - 청력이 떨어졌다면 크게 말하기보다 정면에서 또박또박 말한다.
            - 이름을 부르고 정면에서 눈을 맞춘 뒤 말을 건다.
            - **"예/아니요"로 답할 수 있는 질문**이나 두 가지 중 하나를 고르는 질문을 한다.
              - 개방형 질문, 추상적인 단어, 복잡한 의사결정 요구는 좌절을 일으킨다 (2021-100).
            - 말로 하면서 몸짓, 시범, 그림을 함께 쓴다.

            # ④ 기본 욕구와 수면
            - 수분과 영양을 공급한다. 섭취량과 배설량을 확인한다.
            - 규칙적으로 배변하고 배뇨하도록 돕는다.
            - 통증을 조절한다.
            - 낮에는 깨어서 활동하고 밤에는 자도록 **수면-각성 주기를 유지**한다.
              - 낮잠을 줄인다.
              - 낮에는 커튼을 열어 햇빛을 받게 한다.

            # 4. 섬망의 간호중재 (특히 중요한 것)
            - **원인을 찾아 교정**하는 것이 가장 중요하다.
              - 감염을 치료한다.
              - 수분과 전해질을 교정한다.
              - 산소를 공급한다.
              - 원인 약물을 중단하거나 조정한다.
            - **진정제는 일차 중재가 아니다** (2024-100).
              - 벤조다이아제핀은 섬망을 악화시킬 수 있다.
              - 예외는 알코올 금단 섬망이다. 이때는 벤조다이아제핀을 쓴다.
              - 자신이나 남을 해칠 위험이 크면 처방에 따라 **저용량 항정신병약물**(할로페리돌 등)을 쓴다.
            - 착각과 환시에 대처한다.
              - 논쟁하지 않는다.
              - "무섭게 느껴지시는군요. 저것은 창밖의 나뭇잎입니다"처럼 감정을 인정하고 짧게 현실을 알려 준다 (2025-100).
            - 초조하면 곁에 있어 주고 안심시킨다. 가능하면 가족이 함께 있게 한다.
            - 조기에 움직이게 한다. 불필요한 도관과 관을 빨리 제거한다.
            - 회복된 뒤에는 대상자와 가족에게 **섬망은 일시적이었다**고 설명해 불안을 줄인다.

            # 5. 치매의 간호중재 (특히 중요한 것)

            # 일상의 구조화
            - **일과를 규칙적이고 일관되게** 유지한다 (2026-100). 치매 환자는 새로운 상황에 적응하는 능력이 떨어진다.
            - 익숙한 것을 유지한다. **새로운 지식이나 복잡한 활동은 피한다** (2022-100).
            - **단순하고 성공할 수 있는 활동**을 제공한다. 성취감을 주고 좌절을 막는다.

            # 자가간호
            - 남아 있는 능력은 **스스로 하게 한다.**
            - 단계를 나누어 한 가지씩 안내한다.
            - 옷은 입는 순서대로 놓아 둔다.
            - 식사는 **한 번에 조금씩**, 한 가지씩 제공한다 (2022-100). 삼킴을 관찰한다.

            # 배회
            - **안전한 범위 안에서 배회를 허용**한다 (2020-100).
              - 병실에만 가두거나 억제하면 초조가 커진다.
            - 배회에는 이유가 있으므로 확인한다: 배고픔, 배설, 통증, 지루함.
            - 출입구에 경보장치를 달고, 이름표나 위치 추적 장치를 쓴다.
            - 산책처럼 규칙적인 활동을 한다.

            # 초조와 공격성, 파국반응
            - 원인(자극, 피로, 통증, 좌절)을 찾아 제거한다.
            - 맞서거나 논쟁하지 않는다.
            - 차분하게 **관심을 다른 곳으로 돌린다(전환).**
            - 해질녘증후군이 있으면 오후에 활동과 자극을 줄이고 조명을 밝게 한다.

            # 기억 문제와 망상
            - 기억하지 못하는 것을 따지거나 시험하지 않는다.
              - "기억 안 나세요?"라고 묻지 않는다.
            - 물건을 도둑맞았다는 망상에는 함께 찾아 준다. 물건은 늘 같은 자리에 둔다.

            # 치료적 활동
            - **회상요법**: 과거의 즐거운 기억을 이야기하게 해 자존감을 높인다.
            - **현실지남력훈련**: 경증일 때 쓴다.
            - **인정요법(validation)**: 중증일 때 감정을 인정하는 방법이다.
            - 음악요법, 미술요법, 단순한 집단활동도 도움이 된다 (2020-100). 집단치료를 제한하는 것은 오답이다.

            # 가족 지지
            - 질병의 경과와 돌봄 방법을 교육한다.
            - 돌봄자가 소진되었는지 사정한다.
            - 주간보호, 단기보호, 장기요양서비스, 가족 지지모임을 연결한다.
            - 가정 안전 교육
              - 가스밸브와 약을 관리한다.
              - 낙상 위험 요소를 없앤다.
              - 야간등을 켠다.
              - 가구를 옮기지 않는다.

            # 함께 보면 좋은 문항
            - 2025-100 섬망 환자가 흔들리는 나뭇잎을 보고 귀신이 있다고 함 → 착각 (주제: 지각장애: 환각과 착각)
            - 2023-99 마지막 음주 후 2~3일째 증상 → 진전섬망 (주제: 알코올 관련 장애)
            - 2025-99 기억을 꾸며 대답하는 음주 환자 → 작화증 (주제: 알코올 관련 장애)
            """#
        ),
        // 2026-101 아래에 붙은 설명
        TopicGuide(
            topics: ["섭식장애"],
            title: "섭식장애의 간호중재",
            body: #"""
            섭식장애 간호의 요점은 두 가지이다.
            - 식욕부진증은 **생명을 위협하는 저영양 상태**이므로 **영양 회복이 최우선**이다.
            - **보상행동(구토, 운동, 설사제, 이뇨제)은 막고 관찰**한다.

            # 국시 출제 경향
            - 2020~2026년에 **7문항**이 나왔다. 매년 1문항씩이고, 모두 2교시 101번 자리이다.
            - **섭식장애의 특성 구별**(3문항)
              - 2026-101 신경성 식욕부진증 환자의 특징 → **신체상이 왜곡되어 있다**
              - 2024-101 폭식 후 구토·설사를 반복하며 정상 체중을 유지하는 환자의 증상 → **식사 조절감 상실**
              - 2021-101 신경성 폭식증의 특성 → **먹는 것에 대한 조절능력을 상실한다**
            - **극도의 저체중 환자의 우선순위**(2문항)
              - 2025-101 165cm, 35kg으로 입원한 20세 여자의 우선적 간호중재 → **영양상태를 회복한다**
              - 2020-101 157cm, 40kg인데 더 감량하려고 식사를 줄이고 종일 운동하는 대상자의 우선 간호진단 → **영양 불균형: 신체요구량보다 적음**
            - **신경성 식욕부진증의 입원 중 간호중재**(2문항)
              - 2023-101 입원 초기 간호중재 → **매일 섭취량과 배설량을 확인한다**
              - 2022-101 간호중재 → **식사 후 1~2시간 이내 화장실 가는 것을 제한한다**
            - 오답 보기의 구성
              - 보상행동을 허용하는 보기: 이뇨제 허용·활발한 운동 격려·요구할 때 관장(2023-101), 운동량 늘리기(2022-101)
              - 체중 측정을 잘못 하는 보기: 요구할 때마다 측정(2023-101), 하루에 여러 번 측정(2022-101)
              - 식욕부진증과 폭식증을 섞는 보기: 정상체중 유지(2026-101), 최소 체중유지 거부(2021-101), 전신 솜털 증가·심한 저체온(2024-101)
              - 실제와 반대인 보기: 음식에 무관심·체중에 만족·공공장소 식사(2026-101), 외모·신체상에 무관심(2024-101, 2021-101), 높은 자존감(2021-101)
              - 우선순위 문항(2025-101, 2020-101)은 신체상 왜곡, 완벽주의, 스트레스 관리, 대인관계, 자존감, 지식 부족 같은 **심리사회적 문제**를 오답으로 둔다.
            - 신체 상태가 먼저라는 원칙이 2025-101과 2020-101에서 거듭 나왔고, 두 문항 모두 키와 체중으로 저체중임을 알게 한다.

            # 풀이 요령
            - 키와 체중이 나오면 BMI를 어림한다(2025-101은 약 12.9, 2020-101은 약 16.2). 극도의 저체중이면 **영양 회복, 영양 불균형**이 심리 문제보다 먼저이다.
            - 두 장애는 핵심어로 가른다.
              - 저체중, 신체상 왜곡, 체중 증가 두려움, 최소 체중 거부, 솜털·저체온 → 신경성 식욕부진증
              - 정상 체중, 짧은 시간의 폭식, 조절감 상실, 구토·설사제 같은 보상행동 → 신경성 폭식증
            - 두 장애 모두 체형과 체중에 지나치게 신경 쓴다. "무관심", "만족", "자존감이 높음"이 들어간 보기는 지운다.
            - 입원 중 중재는 **보상행동을 막고 관찰하는 것**을 고른다. 섭취량·배설량 확인, 식후 1~2시간 화장실 제한이 정답이고, 운동·이뇨제·관장은 허용하지 않는다.
            - 체중은 정해진 시간에 같은 조건으로 한 번 잰다. 식사는 소량부터 늘리고, 몸매나 체중에 대한 언급(칭찬 포함)은 피한다.

            # 1. 이해를 위한 기본 내용

            # 신경성 식욕부진증

            # 핵심 특징
            - 음식 섭취를 제한해 나이와 키에 비해 **현저한 저체중**이 된다. 최소 체중을 유지하기를 거부한다.
            - **체중 증가를 몹시 두려워한다.**
            - **신체상이 왜곡**되어 있다. 말랐는데도 자신이 뚱뚱하다고 여긴다 (2026-101).
            - 자신이 병들었다는 것을 부정한다.

            # 유형
            - 제한형: 굶거나 과도하게 운동한다.
            - 폭식/제거형: 폭식하거나 구토, 설사제를 사용한다.

            # 심리적 특성
            - 음식에 **관심이 많다.** 요리하고, 칼로리를 계산하고, 남에게 먹인다. "음식에 관심이 없다"는 오답이다.
            - 남 앞에서 먹는 것을 피한다.
            - 음식을 숨기거나 잘게 자르고, 오래 끌며 먹는다.
            - **완벽주의**가 있고 통제욕구가 강하며 자존감이 낮다.
            - 체중에 **만족하지 못한다.**
            **신체 증상** (굶주림 때문에 생긴다)
            - 서맥, 저혈압, 저체온
            - 부정맥
            - **솜털(lanugo)**이 생긴다.
            - 피부가 건조해지고 손발이 차다.
            - 무월경
            - 변비
            - 골다공증
            - 전해질 불균형, 특히 저칼륨혈증
            **경과**: 정신질환 가운데 **사망률이 가장 높은 편**이다. 원인은 부정맥과 자살이다.

            # 신경성 폭식증

            # 핵심 특징
            - **폭식 삽화**가 반복된다. 짧은 시간에 많은 양을 먹으며, 먹는 동안 **조절감을 잃는다** (2024-101, 2021-101).
            - 체중 증가를 막으려고 **보상행동**을 반복한다.
              - 스스로 구토한다.
              - 설사제, 이뇨제, 관장을 사용한다.
              - 굶거나 과도하게 운동한다.
            - 대개 **정상 체중**이거나 약간 과체중이다. 이 점이 식욕부진증과 다르다.

            # 심리적 특성
            - **자존감이 체형과 체중에 지나치게 좌우**되며, 낮은 경우가 많다.
            - **외모에 매우 신경 쓴다.** "자존감이 높다", "외모에 무관심하다"는 오답이다.
            - 폭식한 뒤 수치심, 죄책감, 우울을 느낀다.
            - 폭식과 구토를 몰래 한다.
            - 충동성이 있다. 물질 남용이나 자해를 동반하기도 한다.
            **신체 증상** (반복적인 구토 때문에 생긴다)
            - 치아 법랑질이 부식되고 충치가 생긴다.
            - 침샘(이하선)이 붓는다.
            - **러셀 징후**: 구토를 유발하느라 손등에 굳은살과 상처가 생긴다.
            - 식도염이 생긴다.
            - **저칼륨혈증**과 대사성 알칼리증이 생기고, 부정맥으로 이어진다.

            # 구별 요점
            - **체중**: 식욕부진증은 저체중, 폭식증은 정상 체중이다.
            - **핵심어**
              - 식욕부진증: 거부, 제한, 신체상 왜곡, 솜털, 저체온
              - 폭식증: **조절감 상실**, 보상행동
            - **폭식장애(binge-eating disorder)**: 폭식은 있지만 보상행동이 없다. 그래서 대개 비만이다.

            # 2. 간호사정

            # 신체 사정
            - 체중과 **BMI**를 확인한다. BMI는 체중(kg) ÷ 키(m)²이다.
              - 18.5 미만은 저체중이다.
              - 15 미만은 극도의 저체중이다.
              - 2025-101: 165cm, 35kg이면 BMI는 약 12.9이다.
              - 2020-101: 157cm, 40kg이면 BMI는 약 16.2이다.
            - 활력징후: 서맥, 저혈압, 기립성 저혈압, 저체온
            - 심전도, 전해질(칼륨, 인, 마그네슘), 혈당, 탈수
            - 피부, 솜털, 부종, 치아, 침샘, 손등의 상처
            - 월경, 배변

            # 행동 사정
            - 식사 양상: 무엇을, 얼마나, 어떻게 먹는가
            - 음식을 숨기거나 버리는가
            - 보상행동: 구토, 운동, 설사제, 이뇨제, 관장
            - 체중을 얼마나 자주 확인하는가

            # 심리 사정
            - 신체상 왜곡, 체중에 대한 두려움
            - 자존감, 완벽주의, 통제 욕구
            - 우울, 불안, 강박
            - **자살과 자해 위험**
            - 가족 관계와 가족 역동

            # 간호진단
            - **영양 불균형: 신체요구량보다 적음** (2020-101의 우선 간호진단)
            - 체액 부족 위험, 전해질 불균형 위험, 심박출량 감소 위험
            - 신체상 장애
            - 만성 자존감 저하
            - 비효과적 대처, 비효과적 부정
            - 가족과정 장애

            # 우선순위
            - 생명과 직결되는 신체 문제가 먼저이다: 영양, 수분, 전해질, 심장.
            - 자존감이나 지식 부족 같은 심리사회 문제는 그다음이다.

            # 3. 신경성 식욕부진증의 간호중재
            **① 최우선: 영양 회복과 신체 안정** (2025-101)
            - 극도의 저체중이면 **영양 상태를 먼저 회복**한다.
              - 전해질 불균형, 부정맥, 저혈압으로 생명이 위험하기 때문이다.
              - 신체상 교정, 성격 수정, 스트레스 관리, 대인관계는 신체가 안정된 뒤에 다룬다.
            - **매일 섭취량과 배설량을 확인**한다 (2023-101).
            - 활력징후, 전해질, 심전도를 관찰한다.
            - 식사는 **소량부터 시작해 점차 늘린다.**
              - "한 번에 많은 양의 식사"는 오답이다 (2022-101).
              - 목표 체중 증가량은 주당 약 0.5~1kg이다.
            - **재급식증후군(refeeding syndrome)**에 주의한다.
              - 갑자기 많이 먹이면 저인산혈증, 저칼륨혈증, 저마그네슘혈증이 생긴다.
              - 그 결과 심부전, 부정맥, 부종이 생길 수 있다.
              - 초기에는 전해질을 자주 확인한다.
            - 입으로 먹지 못하거나 생명이 위험하면 처방에 따라 비위관 영양이나 정맥 영양을 한다.

            # ② 식사 관리와 보상행동 차단
            - 식사 시간과 양을 정하고, 간호사가 **식사 중에 함께 있으며 관찰**한다.
              - 정해진 시간(예: 30분) 안에 먹게 한다.
            - 음식을 숨기거나 버리지 않는지 관찰한다.
            - **식사 후 1~2시간은 화장실 사용을 제한하고 관찰**한다 (2022-101). 몰래 구토하는 것을 막기 위해서이다.
            - **운동을 제한**한다. 체중 감소를 위한 보상행동이기 때문이다.
              - "운동량을 늘린다", "활발한 운동을 격려한다"는 오답이다 (2022-101, 2023-101).
            - **이뇨제, 설사제, 관장을 허용하지 않는다** (2023-101).
              - "이뇨제 사용 허용", "요구할 때 관장"은 오답이다.
            - 행동수정요법(계약)을 한다.
              - 체중 증가나 식사 목표를 달성하면 활동, 면회, 외출 같은 특권을 준다.
              - 먹는 것을 두고 벌을 주거나 강요하거나 협상하지 않는다.

            # ③ 체중 측정
            - **정해진 시간**에 측정한다. 보통 아침 식사 전, 배뇨 후, 같은 옷을 입고 같은 저울로 잰다.
            - "요구할 때마다 측정", "하루에 여러 번 측정"은 오답이다 (2023-101, 2022-101).
            - 옷에 무게를 숨기거나 물을 많이 마셔 체중을 속이지 않는지 확인한다.

            # ④ 치료적 관계와 의사소통
            - 음식과 체중에 대해 논쟁하거나 권력 다툼을 하지 않는다.
              - 대화의 초점을 음식이 아니라 **감정과 스트레스**에 둔다.
            - 외모와 체중에 대해 언급하지 않는다.
              - "날씬한 몸매를 칭찬한다"는 오답이다 (2022-101).
              - "살이 좀 붙었네요"도 피한다.
            - 일관되고 확고하되, 비판하지 않고 수용하는 태도를 보인다.
            - 대상자가 통제하고 싶어 하는 마음을 이해하고, **음식이 아닌 영역에서 선택권**을 준다.
            **⑤ 심리 치료** (신체가 안정된 뒤)
            - 인지행동치료로 신체상 왜곡과 비합리적 사고를 수정한다.
              - 예: "조금만 먹어도 살이 찐다."
            - 음식이나 체중과 상관없는 강점을 찾아 자존감을 높인다.
            - 완벽주의를 다루고, 감정을 표현하고 스트레스에 대처하는 방법을 가르친다.
            - **가족치료**를 한다. 청소년에게 특히 효과적이다.
            - 자살 위험을 계속 사정한다.

            # 4. 신경성 폭식증의 간호중재

            # ① 신체 안정
            - 전해질, 특히 **칼륨**을 확인한다. 부정맥을 관찰하고 탈수를 교정한다.
            - 치아와 구강을 관리한다.
              - 구토한 직후에는 양치하지 말고 물로 헹군다. 위산으로 약해진 법랑질이 손상되기 때문이다.

            # ② 폭식과 보상행동의 중단
            - 규칙적인 식사 계획을 세운다. 하루 세 끼와 간식을 정해진 시간에 먹는다.
              - 굶으면 폭식이 생긴다. 굶기와 폭식의 악순환을 끊는다.
            - 식사 후 화장실 사용을 제한하고 관찰해 구토를 막는다.
            - 설사제, 이뇨제, 과도한 운동을 제한한다.
            - **식사 일지**를 쓰게 한다.
              - 언제, 무엇을 먹었는지 기록한다.
              - 폭식 전후의 상황, 감정, 생각을 기록한다.
              - 폭식을 촉발하는 요인(스트레스, 외로움, 분노)을 찾는다.

            # ③ 대처 방법의 교육
            - 폭식 충동이 들 때 할 수 있는 대체 행동을 찾는다: 산책, 전화, 음악, 이완.
            - 감정을 말로 표현하도록 격려한다.
            - 스트레스 관리, 자기주장훈련, 문제해결 기술을 가르친다.

            # ④ 심리 치료와 약물
            - **인지행동치료**가 1차 치료이다.
              - 체형과 체중에 좌우되는 자존감, 흑백논리를 수정한다.
            - 비판하지 않고 수용한다. 수치심과 죄책감을 다룬다.
            - **SSRI**(fluoxetine)가 폭식과 구토를 줄인다.
            - 우울과 충동성, 물질 사용, 자해 위험을 사정한다.
            - 집단치료와 자조모임에 참여하게 한다.
            """#
        ),
        // 2026-102 아래에 붙은 설명
        TopicGuide(
            topics: ["수면장애"],
            title: "수면장애의 간호중재",
            body: #"""
            수면장애 간호는 **불면장애의 수면위생·자극조절 교육**과 **기면증의 약물·안전 관리**가 중심이다.

            # 국시 출제 경향
            - 2020~2026년에 **7문항**이 나왔다. 매년 1문항씩이고, 모두 2교시 102번 자리이다.
            - **수면위생 교육**(3문항)
              - 2025-102 부서 이동 후 늦게 잠들고 새벽에 깨는 40대 회사원 → **20분이 지나도 잠들지 못하면 잠자리에서 나와 다른 일을 한다**
              - 2023-102 수면장애 대상자의 간호 교육 → **취침 직전 많은 양의 식사는 피한다**
              - 2022-102 6개월 전부터 잠들기 어렵고 자주 깨는 40세 남자 → **기상시간을 일정하게 유지한다**
            - **기면증의 증상과 사정**(2문항)
              - 2024-102 입면 시 환각과 깰 때 움직일 수 없는 상태를 보이는 수면장애 → **기면증**
              - 2021-102 밤에 충분히 자고도 운전·업무 중 여러 차례 잠에 빠지는 환자의 사정 → **잠들거나 깨어날 때의 환각 여부**
            - **수면장애 약물**(2문항)
              - 2026-102 밤에 푹 자는데도 운전 중 깜박 잠이 드는 택배 기사 → **메틸페니데이트**
              - 2020-102 새벽 1시에 깨서 다시 잠들 수 없다며 약을 요구하는 불면장애 환자 → **졸피뎀**
            - 오답 보기의 구성
              - 수면위생 문항은 매번 **취침 전 술, 격렬한 운동, 과식**을 섞는다(2025-102, 2023-102, 2022-102). 여기에 긴 낮잠(2023-102, 2022-102), 주말 늦잠(2023-102), 침대에서 업무 자료 읽기(2025-102)가 더해진다.
              - 기면증 문항은 다른 수면장애를 섞는다. 2024-102는 불면장애·과다수면장애·호흡관련 수면장애·일주기리듬 수면-각성장애, 2021-102는 코골이·수면 중 무호흡(수면무호흡), 악몽(악몽장애), 자다가 돌아다니기(몽유병)이다.
              - 약물 문항은 다른 계열 약을 섞는다. 2026-102는 리튬·클로르프로마진·도네페질·알프라졸람, 2020-102는 설트랄린·플루옥세틴(SSRI), 벤즈트로핀, 메틸페니데이트이다.
            - **메틸페니데이트**는 2020-102에서는 불면에 줄 수 없는 오답, 2026-102에서는 기면증의 정답으로 나왔다. 약은 증상의 방향(잠이 안 옴 대 잠이 쏟아짐)으로 가른다.

            # 풀이 요령
            - "밤에 충분히 잤는데도 낮에 의지와 상관없이 잠든다"는 문장이 나오면 **기면증**이다. 함께 나오는 증상은 탈력발작, 입면·출면 시 환각, 수면마비이다.
            - 약물은 증상으로 고른다.
              - 잠들기 어렵거나 깬 뒤 다시 못 잠(불면) → 졸피뎀
              - 낮에 참을 수 없는 졸림(기면증) → 메틸페니데이트, 모다피닐 같은 중추신경자극제
            - 수면위생 교육은 **기상시간 일정, 20분 규칙(잠이 안 오면 침대에서 나오기), 침대는 잠에만 사용, 취침 전 과식 피하기**를 고른다.
            - 술, 취침 직전 운동, 과식, 긴 낮잠, 주말 늦잠이 들어간 보기는 모두 오답이다. 술은 잠드는 데 도움이 되는 것 같아도 수면을 얕게 하고 새벽에 깨게 한다.

            # 1. 이해를 위한 기본 내용

            # 정상 수면의 구조
            - **NREM 수면**
              - 1~3단계로 나뉜다. 3단계는 깊은 서파수면이다.
              - 몸이 회복되는 시간이며, 밤의 앞부분에 많다.
            - **REM 수면**
              - 빠른 안구운동이 나타나고 꿈을 꾼다.
              - 근육 긴장이 사라진다(근무력).
              - 새벽으로 갈수록 길어진다.
            - 90분 정도 주기로 NREM과 REM이 4~5회 반복된다.
            - 노인은 깊은 수면이 줄고 자주 깬다. 잠드는 시간과 깨는 시간도 앞당겨진다.

            # 주요 수면장애

            # 불면장애
            - 잠들기 어렵거나(입면 곤란), 자주 깨거나(수면 유지 곤란), 새벽에 일찍 깨서 다시 잠들지 못한다.
            - 주 3회 이상, **3개월 이상** 계속되고 낮 기능에 장애가 생긴다.
            - 스트레스, 걱정, 우울, 불안, 잘못된 수면 습관, 카페인과 알코올이 원인이 된다.

            # 기면증
            - 밤에 충분히 자도 **낮에 참을 수 없이 잠에 빠진다(수면발작).**
            - 다음 증상이 함께 나타난다.
              - **탈력발작(cataplexy)**: 웃거나 놀라는 등 감정이 강해지면 갑자기 근력이 빠진다.
              - **입면 시 환각**: 잠들 때 생생한 환각을 경험한다. 깰 때 나타나면 출면 시 환각이라 한다.
              - **수면마비(가위눌림)**: 잠에서 깰 때 의식은 있지만 움직일 수 없다.
            - REM 수면이 비정상적으로 끼어드는 것이 원인이다. 하이포크레틴(오렉신)이 부족하다.

            # 과다수면장애
            - 충분히 자도 계속 졸리다.
            - 기면증의 탈력발작이나 환각은 없다.

            # 호흡관련 수면장애(폐쇄성 수면무호흡증)
            - **코골이, 수면 중 무호흡과 저호흡**이 나타나고 낮에 졸리다.
            - 비만, 고혈압과 관련이 있다.
            - 양압기(CPAP)로 치료하고 체중을 줄인다.

            # 일주기리듬 수면-각성장애
            - 생체리듬이 사회적 일정과 맞지 않는다.
            - 교대근무, 시차, 수면위상 지연(늦게 자고 늦게 일어남)이 해당한다.

            # 사건수면
            - **몽유병(수면보행)**
              - NREM 깊은 수면 중에 일어나 돌아다닌다.
              - 대상자는 기억하지 못한다.
            - **야경증**
              - NREM 수면 중에 비명을 지르며 공포 반응을 보인다.
              - 깨우기 어렵고 대상자는 기억하지 못한다.
              - 아동에게 흔하다.
            - **악몽장애**
              - REM 수면 중에 무서운 꿈을 꾸고 깬다.
              - 대상자는 꿈을 생생하게 기억한다.
            - **REM 수면 행동장애**
              - 꿈의 내용을 행동으로 옮긴다. 발로 차거나 주먹을 휘두른다.
              - 노인 남성에게 많고 파킨슨병과 관련된다.

            # 하지불안증후군
            - 저녁과 밤에 다리가 불편해서 움직이고 싶은 충동이 생긴다.
            - 철분 결핍과 관련이 있다.

            # 2. 간호사정

            # 수면 양상
            - 잠드는 시간과 깨는 시간
            - 잠들 때까지 걸리는 시간, 밤에 깨는 횟수
            - 총 수면시간, 낮잠
            - 낮의 졸림과 기능

            # 도구
            - **수면일지**: 1~2주 동안 기록한다.
            - 수면다원검사
            - 수면잠복기반복검사: 기면증을 진단한다.
            - 엡워스 졸음척도

            # 생활 습관
            - 카페인, 알코올, 니코틴
            - 운동, 식사 시간
            - 취침 전 스마트폰이나 TV
            - 교대근무

            # 원인 사정
            - 스트레스, 걱정
            - 우울, 불안, 조증
            - 통증, 야간뇨, 약물
            **증상별 사정 항목** (2021-102)
            - 기면증이 의심되면: **잠들거나 깰 때의 환각**, 수면마비, 탈력발작
            - 수면무호흡이 의심되면: 코골이, 무호흡, 저호흡
            - 악몽장애: 악몽의 횟수와 내용
            - 몽유병: 자다가 일어나 돌아다니는 행동

            # 간호진단
            - 불면, 수면양상 장애
            - 수면 부족
            - 손상 위험(기면증 환자의 운전, 몽유병)
            - 불안

            # 3. 불면장애의 간호중재

            # ① 수면위생 교육 (2025-102, 2023-102, 2022-102)

            # 규칙적인 수면 리듬
            - **매일 같은 시간에 일어난다.** 기상시간을 일정하게 유지하는 것이 가장 기본이다 (2022-102).
            - 주말과 휴가에도 늦잠을 자지 않는다.
              - "주말이나 휴가에 늦잠 허용"은 오답이다 (2023-102).
            - **낮잠은 피하거나 짧게 한다.** 30분 이내로 하고, 오후 3시 이전에 잔다.
              - "낮잠을 충분히", "2시간 이상 낮잠"은 오답이다 (2023-102, 2022-102).

            # 음식과 물질
            - **취침 직전에 많이 먹지 않는다** (2023-102). 소화 활동이 수면을 방해한다.
              - "저녁 식사량을 늘린다", "취침 전에 많이 먹는다"는 오답이다 (2025-102, 2022-102).
              - 배가 고프면 따뜻한 우유처럼 가벼운 간식을 먹는다.
            - **알코올을 피한다.**
              - 알코올은 잠드는 데 도움이 되는 것 같지만 수면을 얕게 하고 새벽에 깨게 한다.
              - "잠들기 전 술(맥주)"은 오답이다 (2025-102, 2023-102, 2022-102).
            - 오후와 저녁에는 **카페인**(커피, 녹차, 콜라, 초콜릿)을 피한다.
            - 저녁에는 **니코틴**을 피한다. 니코틴은 자극제이다.
            - 저녁에는 수분 섭취를 줄여 야간뇨를 줄인다.

            # 운동
            - 규칙적인 운동은 낮에 한다.
            - **취침 직전에는 격렬한 운동을 피한다.** 취침 3~4시간 전까지만 한다.
              - "취침 1시간 전 격렬한 운동", "수면 전 과격한 운동"은 오답이다 (2025-102, 2023-102, 2022-102).

            # 침실 환경
            - 조용하고 어둡고 알맞게 서늘한 환경을 만든다.
            - 편안한 침구를 쓴다.
            - 침실에서 시계를 보지 않는다.
            - 취침 1시간 전부터는 스마트폰, TV, 컴퓨터 화면을 멀리한다.

            # 잠들기 전
            - 이완 활동을 한다: 따뜻한 목욕, 조용한 음악, 가벼운 독서.
            - 걱정거리는 잠자리에 들기 전에 따로 적어 둔다.

            # ② 자극조절요법 (2025-102)
            **원리**: 침대와 잠의 연결을 강화하는 방법이다.
            - **졸릴 때만 잠자리에 든다.**
            - **침대에서는 잠만 잔다.** 성생활은 예외이다.
              - 업무, 공부, 스마트폰, TV, 식사는 침대에서 하지 않는다.
              - "침대에서 업무 자료를 읽으며 수면 유도"는 오답이다 (2025-102).
            - **누운 지 20분쯤 지나도 잠들지 못하면 침실에서 나온다** (2025-102 정답).
              - 조용한 다른 일을 하다가 졸리면 다시 눕는다.
              - 밤중에 깨서 다시 잠들지 못할 때도 같은 방법을 쓴다.
            - 밤에 얼마나 잤든 **아침에는 같은 시간에 일어난다.**
            - 낮잠을 자지 않는다.

            # ③ 그 밖의 비약물 치료
            - **수면제한요법**
              - 침대에 누워 있는 시간을 실제로 잔 시간만큼으로 줄인다.
              - 수면 효율이 좋아지면 조금씩 늘린다.
            - **이완요법**
              - 점진적 근육이완, 복식호흡, 심상요법, 명상
            - **인지치료**
              - 잠에 대한 잘못된 생각과 걱정을 수정한다.
              - 예: "8시간 못 자면 내일 큰일 난다."
            - **불면증 인지행동치료(CBT-I)**
              - 수면위생, 자극조절, 수면제한, 이완, 인지치료를 묶은 것이다.
              - 만성 불면의 **1차 치료**이다.
            - 원인 질환(우울, 불안, 통증)을 함께 치료한다.

            # ④ 약물 (2020-102)

            # 비벤조다이아제핀 수면제
            - 약물: **졸피뎀**(zolpidem), 에스조피클론
            - 효과: 빨리 작용하고 작용 시간이 짧아 불면에 쓴다.
            - 교육 내용
              - 복용한 뒤에는 **바로 잠자리에 든다.**
              - 복용 후 기억하지 못하는 행동(자면서 운전하기, 음식 먹기)이 생길 수 있다.
              - 알코올과 함께 먹지 않는다.
              - 다음 날까지 남는 졸림에 주의한다.

            # 벤조다이아제핀
            - 의존, 내성, 금단 위험이 있다.
            - 단기간만 쓰고 끊을 때는 서서히 줄인다.

            # 기타 약물
            - 멜라토닌 작용제: 일주기리듬 조절에 쓴다.
            - 진정 작용이 있는 항우울제: 트라조돈, 미르타자핀

            # 공통 원칙
            - 수면제는 **단기간 보조적으로** 쓴다.
            - 노인은 낙상과 혼돈에 주의한다.
            - 약물은 수면위생과 함께 사용한다.

            # 2020-102 오답 약물
            - 설트랄린, 플루옥세틴: SSRI 항우울제이다. 플루옥세틴은 오히려 불면을 일으킬 수 있다.
            - 벤즈트로핀: 추체외로증상 치료제이다.
            - 메틸페니데이트: 각성을 일으킨다.

            # 4. 기면증의 간호중재

            # ① 약물
            - 낮 졸림에는 **중추신경자극제**를 쓴다: **메틸페니데이트**, 모다피닐, 암페타민 (2026-102).
            - 탈력발작에는 항우울제(SSRI, SNRI, 삼환계)나 sodium oxybate를 쓴다.
            - 오답 약물 (2026-102)
              - 리튬: 기분안정제이다.
              - 클로르프로마진: 항정신병약물이다.
              - 도네페질: 치매 치료제이다.
              - 알프라졸람: 벤조다이아제핀이어서 졸림을 오히려 악화시킨다.

            # ② 계획된 낮잠
            - 하루 2~3회, 15~20분 정도 **짧은 낮잠을 계획해서** 잔다.
            - 기면증 환자에게는 낮잠이 치료가 된다. 불면장애와는 반대이다.

            # ③ 규칙적인 수면
            - 밤에 충분히 잔다.
            - 잠드는 시간과 깨는 시간을 일정하게 지킨다.

            # ④ 안전
            - 졸릴 때는 **운전하거나 위험한 기계를 다루지 않는다.**
            - 수면발작이 생길 수 있으므로 안전한 직업과 활동을 선택하도록 돕는다.
            - 탈력발작을 일으키는 강한 감정 상황을 알고 대비한다.

            # ⑤ 교육과 지지
            - 게으른 것이 아니라 **질병**이라는 것을 대상자, 가족, 직장, 학교에 알린다.
            - 무거운 식사와 알코올은 졸림을 심하게 하므로 피한다.

            # 5. 그 밖의 수면장애 중재

            # 폐쇄성 수면무호흡증
            - 양압기(CPAP)를 사용한다.
            - 체중을 줄인다.
            - 옆으로 누워 잔다.
            - 알코올과 진정제를 피한다. 기도 근육을 이완시켜 무호흡을 악화시킨다.

            # 몽유병과 야경증
            - **안전한 환경**을 만든다.
              - 문과 창문을 잠근다.
              - 날카로운 물건과 장애물을 치운다.
              - 계단에 안전문을 단다.
            - 억지로 깨우지 말고 조용히 침대로 이끈다.
            - 수면 부족과 스트레스를 줄인다.

            # 악몽장애
            - 깨어나면 곁에 있으며 안심시킨다.
            - 이완요법을 한다.
            - **심상 시연 치료**: 악몽의 결말을 바꾸어 연습한다.
            - 외상후스트레스장애가 있는지 사정한다.

            # 일주기리듬 장애
            - 아침에 밝은 빛에 노출한다(광선치료).
            - 멜라토닌을 쓴다.
            - 교대근무자는 수면 시간표를 짜고 방을 어둡게 한다.

            # 입원 환자의 수면 증진
            - 밤에는 처치와 활력징후 측정을 몰아서 한다.
            - 소음과 조명을 줄인다.
            - 통증을 조절한다.
            - 평소의 취침 습관을 유지하게 한다.
            """#
        ),
        // 2026-103 아래에 붙은 설명
        TopicGuide(
            topics: ["성 관련 장애"],
            title: "성 관련 장애의 간호중재",
            body: #"""
            성 관련 장애는 성기능부전, 변태성욕장애, 성별 불쾌감으로 나뉜다. 사정에서는 **비판단적인 면담**이, 유형 구별에서는 **변태성욕장애 각각의 정의**가 중요하다.

            # 국시 출제 경향
            - 2020~2026년에 **7문항**이 나왔다. 매년 1문항씩이고, 모두 2교시 103번 자리이다.
            - **변태성욕장애 가리기**(4문항)
              - 2025-103 다른 사람의 성기나 성행위를 몰래 훔쳐보며 성적 흥분을 얻음 → **관음장애**
              - 2024-103 신체 일부나 신체와 밀접한 물체에서 성적 흥분을 느낌 → **물품음란장애**
              - 2022-103 성적 흥분을 위해 여성의 속옷에 집착함 → **물품음란장애**
              - 2020-103 혼잡한 지하철에서 성기를 여자의 몸에 문지름 → **마찰도착장애**
            - **성 관련 장애 대상자 면담**(2문항)
              - 2026-103 성교 시 통증으로 부부 갈등이 있는 대상자와의 면담 → **비판단적인 태도로 경청한다**
              - 2021-103 성 관련 장애 환자 면담 → **비판단적인 태도로 경청한다**
            - **성별 불쾌감**(1문항)
              - 2023-103 여성인 것이 불편하고 남성의 이차성징을 갈망하는 15세 여학생 → **성별 불쾌감**
            - 오답 보기의 구성
              - 진단 문항은 다른 변태성욕장애를 돌려 쓴다. 노출장애, 관음장애, 마찰도착장애, 물품음란장애, 성적피학장애, 성적가학장애, 복장도착장애, 소아성애장애가 서로의 오답이 된다(2025-103, 2024-103, 2022-103, 2020-103).
              - 2023-103은 관음장애·마찰도착장애·성적가학장애(변태성욕장애)와 성기능부전을 섞는다.
              - 면담 문항은 두 해 모두 전문용어 사용, 민감한 주제부터 시작, 대상자의 가치관이 잘못됐다고 인식시키기를 섞는다. 2026-103은 속어 사용, 2021-103은 폐쇄적 질문을 더한다.
            - 면담 문항은 2021-103과 2026-103의 정답과 오답이 거의 같다. 물품음란장애도 2022-103과 2024-103에서 두 번 정답이었다.

            # 풀이 요령
            - 변태성욕장애는 성적 흥분의 대상과 방법으로 가른다.
              - 몰래 훔쳐봄 → 관음장애
              - 낯선 사람에게 성기를 보임 → 노출장애
              - 동의하지 않은 사람에게 문지름(붐비는 대중교통) → 마찰도착장애
              - 속옷·신발 같은 물건이나 성기가 아닌 신체 부위 → 물품음란장애
              - 이성의 옷을 입음 → 복장도착장애
              - 고통·굴욕을 당함 → 성적피학장애, 고통을 줌 → 성적가학장애
            - 지정된 성별이 불편하고 다른 성별의 성징을 원하면 변태성욕장애가 아니라 **성별 불쾌감**이다.
            - 면담 문항은 **비판단적·수용적 경청**을 고른다. 이해하기 쉬운 정확한 용어, 개방적 질문, 덜 민감한 주제에서 민감한 주제로 옮겨 가는 순서가 맞는 방법이다.
            - 간호사의 가치관을 강요하거나 "잘못됐다"고 인식시키는 보기, 전문용어나 속어를 쓰는 보기는 지운다.

            # 1. 이해를 위한 기본 내용: 성 관련 장애의 분류

            # ① 성기능부전 (sexual dysfunction)
            성 반응 주기(욕구 → 흥분 → 극치감 → 해소)의 어느 단계에 장애가 생겨 고통을 겪는 것이다.

            # 욕구와 흥분의 장애
            - 남성 성욕감퇴장애: 성적 생각과 욕구가 지속적으로 떨어진다.
            - 여성 성적 관심/흥분장애: 성적 관심과 흥분이 떨어진다.
            - **발기장애**: 발기가 되지 않거나 유지되지 않는다.

            # 극치감의 장애
            - 여성 극치감장애
            - **조기사정**: 삽입 후 약 1분 이내에, 원하기 전에 사정한다.
            - 사정지연

            # 통증의 장애
            - **생식기-골반통/삽입장애**: 성교 시 통증을 느끼고, 삽입을 두려워하며, 질 근육이 긴장한다(과거의 질경련).

            # 원인
            - 신체적 원인
              - 당뇨, 고혈압, 혈관질환, 호르몬 이상
              - 약물: **SSRI**, 항정신병약물, 항고혈압제
              - 알코올
            - 심리적 원인
              - 수행불안, 우울, 부부 갈등
              - 성에 대한 죄책감, 성적 외상

            # ② 변태성욕장애 (paraphilic disorder)
            비정상적인 대상이나 상황에서 반복적으로 강한 성적 흥분을 느낀다. 이로 인해 **고통을 겪거나 기능이 손상되거나, 동의하지 않은 사람에게 행동한** 경우에 진단한다. 지속 기간은 **6개월 이상**이다.

            # 동의하지 않은 사람을 대상으로 하는 유형
            - **관음장애**: 알아차리지 못하는 사람의 나체, 옷 벗는 모습, 성행위를 **몰래 훔쳐본다** (2025-103).
            - **노출장애**: 낯선 사람에게 자신의 **성기를 노출**한다.
            - **마찰도착장애**: 동의하지 않은 사람에게 **몸이나 성기를 대거나 문지른다.** 붐비는 지하철이나 버스에서 흔하다 (2020-103).
            - **소아성애장애**: **사춘기 이전의 아동**이 대상이다.
              - 16세 이상이고 아동보다 5세 이상 많아야 진단한다.

            # 고통이나 굴욕과 관련된 유형
            - **성적피학장애**: 자신이 **모욕당하거나, 맞거나, 묶이거나, 고통받을 때** 흥분한다.
            - **성적가학장애**: **다른 사람에게 고통이나 굴욕을 줄 때** 흥분한다.

            # 물건이나 옷과 관련된 유형
            - **물품음란장애**: **무생물**(속옷, 신발, 스타킹)이나 **성기가 아닌 신체 부위**(발 등)에서 흥분을 느낀다 (2024-103, 2022-103).
            - **복장도착장애**: **이성의 옷을 입을 때** 흥분한다.
              - 성별 정체성은 바뀌지 않는다. 이 점이 성별 불쾌감과 다르다.

            # 특성
            - 대부분 남성이다.
            - 여러 유형이 함께 나타나는 경우가 많다.
            - 스스로 치료를 원하는 경우는 드물다. 법적 문제로 치료에 오는 경우가 많다.

            # ③ 성별 불쾌감 (gender dysphoria)
            - 자신이 경험하는 성별과 **태어날 때 지정된 성별이 일치하지 않아** 심한 고통을 겪는다 (2023-103).
            - 다른 성별의 성징을 갖거나 다른 성별로 대우받기를 강하게 원한다.
            - 6개월 이상 계속된다.
            - 성적 흥분의 문제가 아니라 **성별 정체성의 문제**이다. 변태성욕장애가 아니다.
            - 우울, 불안, 따돌림, **자살 위험**이 높다.

            # 2. 간호사정: 성 문제 면담의 원칙 (국시 핵심)

            # 태도
            - **비판단적이고 수용적인 태도로 경청**한다 (2026-103, 2021-103 정답).
              - 대상자가 안심하고 이야기할 수 있게 하는 것이 가장 중요하다.
            - 간호사가 **먼저 자신의 성에 대한 가치관과 태도를 인식**한다(자기인식).
              - 놀라거나 당황하거나 불편해하는 반응을 드러내지 않는다.
            - **간호사의 가치관을 강요하지 않는다.**
              - "성과 관련된 가치관이 잘못된 것임을 인식시킨다"는 오답이다 (2026-103, 2021-103).

            # 환경
            - **사생활이 보장되는 조용한 장소**에서 면담한다.
            - 비밀이 유지된다는 것을 알려 준다.

            # 용어
            - **대상자가 이해할 수 있는 정확한 용어**를 쓴다.
              - 지나친 **전문용어**는 이해를 어렵게 한다.
                - "전문용어를 사용하면서 면담"은 오답이다 (2026-103, 2021-103).
              - **속어**는 전문성을 떨어뜨린다.
                - "성과 관련된 속어를 사용"은 오답이다 (2026-103).
            - 대상자가 쓰는 말의 뜻이 분명하지 않으면 확인한다.

            # 질문
            - **개방적 질문**으로 자유롭게 표현하게 한다.
              - "폐쇄적인 질문으로 자료 수집"은 오답이다 (2021-103).
            - **덜 민감한 주제부터 시작**해 점차 민감한 주제로 옮겨 간다.
              - "민감한 주제부터 시작하여 덜 민감한 것으로"는 오답이다 (2026-103, 2021-103).
              - 예: 일반 건강력 → 월경력과 생식력 → 성 관련 관계 → 성적 행동과 문제
            - 질문을 일반화하면 대답하기 쉬워진다.
              - 예: "많은 사람이 ~한 경험을 합니다. 당신은 어떤가요?"

            # 사정할 내용
            - 성 문제의 시작 시기와 양상, 성 반응 주기 중 어느 단계의 문제인지
            - 신체 질환, 복용 약물, 음주
            - 부부와 파트너 관계, 스트레스, 우울과 불안
            - 성에 대한 가치관, 지식, 문화와 종교적 배경
            - 성적 외상의 경험
            - 변태성욕장애라면 **타인에게 피해를 줄 위험**
            - 성별 불쾌감이라면 **자살 위험**과 따돌림

            # 간호진단
            - 성기능 장애, 비효과적 성양상
            - 신체상 장애, 자존감 저하
            - 불안, 가족과정 장애
            - 폭력 위험(타인 대상), 자살 위험

            # 3. 간호중재

            # 공통 원칙: PLISSIT 모델
            단계가 올라갈수록 더 전문적인 개입이 필요하다.
            - **P (Permission, 허용)**
              - 성에 대해 이야기해도 괜찮다고 허락한다.
              - 대상자의 성적 생각과 감정이 정상 범위라는 것을 알려 준다.
            - **LI (Limited Information, 제한된 정보)**
              - 대상자의 문제에 필요한 정확한 정보를 준다.
              - 예: 성 반응, 약물의 부작용
            - **SS (Specific Suggestions, 구체적 제안)**
              - 문제에 맞는 구체적인 방법을 제안한다.
              - 예: 감각집중훈련, 윤활제 사용
            - **IT (Intensive Therapy, 집중치료)**
              - 성치료 전문가나 정신치료 전문가에게 의뢰한다.

            # ① 성기능부전의 간호중재
            - **원인을 확인**한다.
              - 신체 질환을 치료한다.
              - **약물 부작용**을 확인하고 처방 조정을 상의한다(SSRI, 항정신병약물, 항고혈압제).
              - 알코올을 줄인다.
            - **성교육**을 한다.
              - 정상적인 성 반응과 나이에 따른 변화를 설명한다.
              - 잘못된 믿음을 교정한다.
            - **부부(커플)를 함께** 상담한다. 의사소통을 개선한다.
            - **감각집중훈련(sensate focus)**
              - 성교를 목표로 하지 않는다.
              - 서로 만지며 감각에 집중해 **수행불안을 줄인다.**
            - 문제별 행동요법
              - 조기사정: 멈추고-시작하기 기법, 압박법
              - 삽입 시 통증: 이완훈련, 점진적 질 확장, 윤활제 사용, 골반저근 훈련
            - 약물
              - 발기장애에는 PDE-5 억제제(실데나필)를 쓴다.
              - 질산염 제제와 함께 쓰면 심한 저혈압이 올 수 있어 금기이다.
            - 불안, 우울, 부부 갈등을 함께 다룬다.

            # ② 변태성욕장애의 간호중재
            - **비판단적 태도**를 유지한다.
              - 사람은 수용하되, 타인에게 피해를 주는 행동은 수용하지 않는다.
            - **타인의 안전**을 먼저 생각한다.
              - 피해 위험을 사정한다.
              - 아동 학대 같은 법적 신고 의무를 확인한다.
            - **인지행동치료**
              - 성적 충동을 일으키는 상황과 생각(촉발 요인)을 알아차리게 한다.
              - 충동을 조절하는 방법을 배운다.
              - 인지 왜곡을 수정한다. 예: "상대도 좋아했을 것이다."
              - 피해자에 대한 공감을 훈련한다.
            - **혐오요법**, 자위 재조건화 같은 행동요법을 쓴다.
            - **재발 방지 계획**을 세운다.
              - 고위험 상황을 피한다. 예: 마찰도착장애 대상자는 붐비는 대중교통을 피한다.
            - 사회기술훈련과 스트레스 관리로 건강한 관계를 맺는 방법을 배운다.
            - 약물
              - SSRI는 성적 충동을 줄인다.
              - 항안드로겐제는 심한 경우에 쓴다.

            # ③ 성별 불쾌감의 간호중재
            - 대상자가 경험하는 **성별 정체성을 존중**한다.
              - 대상자가 원하는 이름과 호칭을 쓴다.
              - 비판단적이고 수용적인 태도를 보인다.
            - 고통, 우울, 불안을 다룬다. **자살 위험**을 사정한다.
            - 가족을 교육하고 지지한다. 학교에서 따돌림을 당하는지 확인한다.
            - 선택할 수 있는 치료를 정확히 안내하고, 대상자가 결정하도록 돕는다.
              - 선택지: 정신치료, 호르몬 치료, 수술
            - 지지모임과 전문기관을 연결한다.
            """#
        ),
        // 2026-104 아래에 붙은 설명
        TopicGuide(
            topics: ["자폐스펙트럼장애"],
            title: "자폐스펙트럼장애의 간호중재",
            body: #"""
            자폐스펙트럼장애(ASD)의 핵심은 두 축이다.
            - **사회적 의사소통과 상호작용의 결함**
            - **제한적이고 반복적인 행동**
            중재의 핵심어는 네 가지이다.
            - **안전**(자해 시 헬멧)
            - **일관성**(같은 간호사, 변화 최소화)
            - **구조화된 일과**
            - **사회적 상호교류 향상**

            # 국시 출제 경향
            - 2020~2026년에 **6문항**이 나왔다(2023년을 뺀 매해: 2020, 2021, 2022, 2024, 2025, 2026년). 대개 2교시 104번 자리이고, 2021년만 105번이었다.
            - **사례를 보고 진단 추정**(2문항)
              - 2025-104 선풍기를 종일 바라보고, 불러도 쳐다보지 않으며 청력은 정상인 3세 → **자폐스펙트럼장애**
              - 2021-105 눈을 맞추지 않고, 같은 장소에서만 놀며 스위치를 반복해 켜고 끄는 5세 → **자폐스펙트럼장애**
            - **행동 특성**(2문항)
              - 2024-104 자폐스펙트럼장애 아동의 행동 특성 → **사회적 의사소통 능력 저하**
              - 2020-104 바퀴를 돌리며 놀고 말이 없으며 눈맞춤이 안 되는 5세 → **상동적 행동**
            - **간호목표와 간호중재**(2문항)
              - 2026-104 머리를 바닥에 찧는 자해행동을 보이는 아동 → **헬멧 등으로 머리를 보호한다**
              - 2022-104 혼자 놀고 불러도 대답하지 않는 3세 남아의 간호목표 → **사회적 상호교류가 향상된다**
            - 오답 보기의 구성
              - 다른 아동기 장애를 섞는다. 2025-104는 투렛장애·품행장애·분리불안장애·적대적 반항장애, 2021-105는 뚜렛장애·특정학습장애·의사소통장애·반응성 애착장애이다.
              - 다른 장애의 특징이나 목표를 섞는다. 2020-104의 잦은 논쟁(적대적 반항장애)과 차례를 기다리지 못함(ADHD), 2022-104의 과제 완수·집중력 향상(ADHD)과 사회적 규범 준수·친구의 권한 침해 않기(품행장애)이다.
              - 자폐와 정반대인 모습을 섞는다. 풍부한 감정 표현, 상상놀이 공유, 다양한 관심, 과도한 친밀감(2024-104), 또래와 친밀감 형성, 다양한 집단놀이에 흥미(2020-104)이다.
              - 2026-104는 새로운 장난감 제공, 자해에 무관심, 담당 간호사 변경, 다른 활동 제한을 섞는다.
            - 사례 문항은 모두 **눈맞춤 부족·불러도 반응 없음**과 **돌아가는 물체나 반복 행동**을 함께 제시한다. 2025-104와 2020-104는 청력이 정상이라는 단서도 준다.

            # 풀이 요령
            - 자폐스펙트럼장애는 두 축으로 알아본다.
              - 사회적 의사소통·상호작용 결함 → 눈맞춤 부족, 이름을 불러도 반응 없음, 혼자 놀기
              - 제한적·반복적 행동 → 바퀴·선풍기 같은 돌아가는 물체에 몰두, 스위치 켜고 끄기, 같은 장소 고집
            - 간호목표는 핵심 문제인 **사회적 상호교류 향상**을 고른다. 집중력·과제는 ADHD, 규범·타인의 권리는 품행장애 쪽이다.
            - 자해행동이 있으면 **신체 손상 예방(보호장구)**이 먼저이다. 변화에 저항하므로 새 물건이나 담당자 변경은 오답이다.
            - 오답 진단은 핵심 증상으로 지운다. 틱은 투렛장애, 규칙 위반은 품행장애, 분리 시 불안은 분리불안장애, 반항·논쟁은 적대적 반항장애, 학대·방임 후 애착 문제는 반응성 애착장애이다.

            # 1. 이해를 위한 기본 내용

            # 정의
            - **발달 초기**부터 증상이 나타나는 **신경발달장애**이다.
            - 대개 생후 12~24개월에 부모가 알아차린다.
            - 남아가 여아보다 약 4배 많다.
            - 증상의 정도가 넓게 퍼져 있어서 '스펙트럼'이라 부른다.
              - 지적장애와 언어장애를 동반하는 경우가 있다.
              - 지능이 정상인 경우도 있다(과거의 아스퍼거장애).

            # 핵심 증상 ①: 사회적 의사소통과 상호작용의 결함
            - **눈을 맞추지 않는다.** 표정과 몸짓을 적게 쓴다.
            - **이름을 불러도 반응하지 않는다.**
              - 청력은 정상이다 (2025-104, 2020-104). 청력 검사를 하면 청각장애가 배제된다.
            - **혼자 논다.** 또래에게 관심이 없고 친밀감을 형성하지 못한다.
            - 관심이나 기쁨을 나누지 못한다. 예를 들어 손가락으로 가리켜 보여 주지 않는다.
            - 감정을 적게 표현한다. 다른 사람의 감정을 이해하기 어렵다.
            - **상상놀이나 역할놀이를 하지 못한다.**
            - 언어 발달이 늦다.
              - **반향언어**: 남의 말을 앵무새처럼 그대로 따라 한다.
              - 대명사를 뒤바꿔 쓴다. 예: '나' 대신 '너'
              - 억양이 단조롭다.

            # 핵심 증상 ②: 제한적이고 반복적인 행동, 관심, 활동
            - **상동행동**
              - 손 흔들기, 몸 흔들기, 제자리 돌기
              - **물건 돌리기**: 장난감 바퀴, 선풍기 (2020-104, 2025-104)
              - **스위치를 반복해서 켜고 끄기** (2021-105)
            - **같은 것을 고집하고 변화에 저항**한다.
              - 같은 장소, 같은 길, 같은 음식, 같은 순서를 고집한다.
              - 작은 변화에도 심하게 짜증을 낸다(분노발작).
            - **관심이 좁고 특정 물건에 강하게 집착**한다.
            - **감각 자극에 과민하거나 둔감**하다.
              - 소리, 빛, 촉감에 과민하다.
              - 통증에는 둔감하다.

            # 동반 문제
            - **자해**: 머리 찧기, 손 물기
            - 공격성, 분노발작
            - 수면 문제, 편식
            - 지적장애, 뇌전증, ADHD

            # 치료
            - **조기 집중 행동치료**가 핵심이다: 응용행동분석(ABA), 언어치료, 사회기술훈련, 특수교육.
            - 약물은 핵심 증상을 치료하지 못한다.
              - **리스페리돈과 아리피프라졸**은 **과민성, 공격성, 자해**를 줄이는 데 쓴다.

            # 다른 아동기 장애와의 구별
            - **ADHD**: 부주의, 과잉행동, 충동성이 있다. 차례를 기다리지 못한다.
            - **적대적 반항장애**: 어른과 자주 논쟁하고 반항한다.
            - **품행장애**: 타인의 권리와 사회 규범을 침해한다.
            - **투렛장애**: 운동 틱과 음성 틱이 함께 있다.
            - **반응성 애착장애**: 학대나 방임 때문에 애착이 형성되지 않았다.
            - **분리불안장애**: 애착 대상과 떨어질 때 지나치게 불안해한다.
            - **특정학습장애**: 읽기, 쓰기, 셈하기에 어려움이 있다.

            # 2. 간호사정

            # 사회적 상호작용
            - 눈맞춤이 있는가
            - 이름을 부르면 반응하는가
            - 또래나 가족과 어떻게 관계를 맺는가
            - 관심을 공유하는가

            # 의사소통
            - 말을 할 수 있는가, 할 수 있다면 어느 수준인가
            - 반향언어가 있는가
            - 비언어적 의사소통(몸짓, 가리키기)을 하는가
            - 요구를 어떻게 표현하는가

            # 행동
            - 상동행동의 종류와 빈도
            - 무엇을 고집하는가, 변화에 어떻게 반응하는가
            - 분노발작을 일으키는 요인은 무엇인가

            # 안전
            - **자해행동**(머리 찧기, 물기)과 공격성
            - 위험을 인식하는가

            # 감각
            - 과민하거나 둔감한 자극은 무엇인가
            - 청력과 시력을 검사해 다른 원인을 배제한다.

            # 기본 생활
            - 수면, 식사(편식), 배변 훈련, 자가간호 능력

            # 가족
            - 부모의 스트레스와 소진
            - 질병에 대해 얼마나 알고 있는가
            - 이용할 수 있는 지지 자원

            # 간호진단
            - **사회적 상호작용 장애**(가장 핵심)
            - 언어적 의사소통 장애
            - **자해 위험**, 폭력 위험
            - 개인 정체성 장애
            - 자가간호 결핍
            - 부모 역할 장애, 돌봄자 역할 긴장
            **간호목표** (2022-104)
            - **사회적 상호교류가 향상된다.**
            - 다른 장애의 목표와 헷갈리지 않도록 구별한다.
              - "과제를 완수한다", "집중력이 향상된다"는 **ADHD**의 목표이다.
              - "사회적 규범을 준수한다", "친구의 권한을 침해하지 않는다"는 **품행장애**의 목표이다.

            # 3. 간호중재

            # ① 안전: 자해와 공격성 (2026-104)
            - **자해할 때는 신체 손상을 막는 것이 우선**이다.
              - 머리를 찧으면 **헬멧 같은 보호장구로 머리를 보호**한다.
              - 손을 물면 장갑을 끼운다.
              - 주변의 위험한 물건을 치운다.
            - 자해를 "무시한다"는 오답이다. 손상 위험이 계속되기 때문이다.
              - 다만 보호한 뒤에는 자해 행동에 지나친 관심을 보이지 않는다. 관심이 행동을 강화하지 않게 한다.
            - 자해를 일으키는 요인을 찾아 줄인다.
              - 좌절, 감각 과부하, 변화, 요구를 전달하지 못하는 상황
            - 자해 대신 쓸 수 있는 행동이나 활동으로 **관심을 돌린다(전환).**
            - **"자해 위험이 없어질 때까지 다른 활동 제한"은 오답**이다. 좌절과 자해가 오히려 늘어난다 (2026-104).

            # ② 일관성과 구조화
            - **같은 간호사가 일관되게** 돌본다.
              - "담당 간호사를 변경한다"는 오답이다 (2026-104).
            - **일과를 규칙적으로 구조화**한다.
              - 매일 같은 순서와 시간을 지키면 불안이 줄어든다.
            - **변화를 최소화**한다.
              - 환경, 가구 배치, 물건 위치를 바꾸지 않는다.
              - 변화가 필요하면 **미리 알리고 조금씩** 도입한다.
              - **"새로운 장난감 제공"은 오답**이다 (2026-104). 새 물건은 불안을 높인다.
            - **그림 일과표** 같은 시각 자료로 다음 활동을 미리 보여 준다.
            - 자극이 적고 예측할 수 있는 환경을 만든다. 소음과 강한 빛을 줄인다.

            # ③ 사회적 상호작용 증진 (간호목표의 핵심)
            - 신뢰 관계를 천천히 형성한다.
              - 아동의 속도에 맞추고 강요하지 않는다.
              - 처음에는 **일대일 관계**에서 시작한다.
            - 눈맞춤과 모방을 격려하고, 적절한 반응에는 즉시 **칭찬하고 강화**한다.
            - 간단한 차례 지키기 놀이로 시작해 점차 소집단 활동으로 넓힌다.
            - **사회기술훈련**을 한다. 인사하기, 요청하기, 기다리기를 가르친다.
            - 아동이 좋아하는 관심사를 이용해 상호작용을 끌어낸다.

            # ④ 의사소통 증진
            - **짧고 간단하며 구체적인 말**로 한다. 한 번에 한 가지씩 말한다.
            - 이름을 부르고 주의를 끈 다음에 말한다.
            - 일관된 용어를 쓴다.
            - **시각 보조도구**를 쓴다.
              - 그림카드
              - 그림교환 의사소통체계(PECS)
              - 몸짓, 수화
            - 아동의 비언어적 신호(행동, 소리)가 무엇을 뜻하는지 파악한다.
            - 적절한 언어 표현을 강화하고 언어치료와 연계한다.

            # ⑤ 행동 관리
            - **행동수정요법(응용행동분석)**
              - 바람직한 행동은 즉시 칭찬과 보상으로 강화한다.
              - 부적절한 행동은 강화하지 않는다.
            - 상동행동을 무조건 막지 않는다.
              - 상동행동이 불안을 줄이는 역할을 할 수 있다.
              - 위험하지 않다면 시간과 장소를 정해 허용한다.
              - 점차 다른 활동으로 대체한다.
            - 분노발작이 생기면 차분하게 대응한다. 자극을 줄이고, 안전을 확보한 뒤 진정할 시간을 준다.

            # ⑥ 자가간호
            - 옷 입기, 씻기, 식사, 배변을 **단계별로 나누어** 반복해서 가르친다.
            - 그림 순서표를 활용한다.
            - 할 수 있는 것은 스스로 하게 하고, 해내면 칭찬한다.

            # ⑦ 가족 지지와 교육
            - 질병을 정확히 설명한다.
              - 부모의 양육 잘못 때문이 아니라 **신경발달장애**라는 것을 알려 부모의 죄책감을 줄인다.
            - **조기 개입이 중요**하다는 것을 알리고 치료를 꾸준히 받도록 격려한다.
            - 가정에서도 병원과 같은 일과와 행동 관리 방법을 **일관되게** 적용하도록 교육한다.
            - 부모의 스트레스와 소진을 사정한다.
            - 부모 지지모임, 특수교육, 발달재활서비스, 단기보호를 연결한다.
            - 형제자매에게도 관심을 갖는다.

            # 함께 보면 좋은 문항
            - 2021-76: 질문을 그대로 따라 하는 조현병 환자 → 반향언어. 반향언어는 자폐스펙트럼장애에서도 나타난다.
            """#
        ),
        // 2026-105 아래에 붙은 설명
        TopicGuide(
            topics: ["품행장애와 틱장애"],
            title: "품행장애의 간호중재",
            body: #"""
            품행장애 간호의 핵심은 문제행동에 대한 제한설정이다.
            - 문제행동에는 **즉시, 차분하고 단호하게, 일관되게** 제한을 설정한다.
            - 비난, 낙인, 위협, 체벌, 공격 행동의 수용은 모두 오답이다.

            # 국시 출제 경향
            - 2020~2026년에 **4문항**이 나왔다(2020, 2022, 2023, 2026년). 모두 2교시 105번 자리이다.
            - **품행장애 아동에 대한 대처**(2문항)
              - 2026-105 품행장애 아들에게 구타당한 어머니에게 주는 교육 → **문제행동은 즉각적으로 차분하고 단호하게 대처한다**
              - 2020-105 보드게임 중 의자를 던져 모니터를 부순 중학생 → **"기물을 파손하는 것은 허용되지 않는 행동이에요."**
            - **품행장애의 행동 특성**(1문항)
              - 2023-105 품행장애 대상자의 행동특성 → **규칙을 위반하고 거짓말을 한다**
            - **투렛장애의 특징**(1문항)
              - 2022-105 투렛장애에 관한 설명 → **다양한 운동 틱과 음성 틱이 나타난다**
            - 오답 보기의 구성
              - 2020-105: "도대체 무엇이 문제인가요?"(비난조 질문), "나쁜 학생이군요"(낙인), 격리실로 보내겠다는 위협, 배상 추궁을 섞는다.
              - 2026-105: 규칙을 융통성 있게 적용, 무력으로 통제, 목표를 높게 설정, 관심을 끌려는 공격 행동 수용을 섞는다.
              - 2023-105: 강한 인내심, 공감, 죄책감 표현처럼 **품행장애와 반대되는 모습**에 투렛장애의 특징(운동 틱과 음성 틱)을 섞는다.
              - 2022-105: 분리불안장애(분리 시 공황), 특정학습장애(지적 능력에 비해 낮은 학습기술), 유뇨증(반복적 소변 실수), ADHD(주의집중 곤란)의 설명을 섞는다.
            - 품행장애와 투렛장애가 서로의 오답으로 쓰였다. 2023-105의 오답 "운동 틱과 음성 틱이 동시에 나타난다"는 2022-105의 정답 내용이다.

            # 풀이 요령
            - 품행장애 중재는 **제한설정**이다. 문제행동이 일어나면 즉시, 감정 없이 차분하고 단호하게, 허용되지 않는 행동임을 알리는 보기를 고른다.
            - 규칙은 명확하고 일관되게, 목표는 현실적으로 달성 가능하게 세운다. "융통성 있게", "높게", "수용하세요"가 들어간 보기는 오답이다.
            - 비난, 낙인("나쁜 학생"), 위협(격리실), 무력 통제, 배상 추궁은 적대감과 반항을 키우므로 지운다.
            - 품행장애의 특성은 **타인의 권리와 규칙 위반, 거짓말, 공격성, 공감·죄책감 부족, 낮은 인내심**이다.
            - 아동기 장애의 핵심어를 짝지어 둔다.
              - 운동 틱과 음성 틱 → 투렛장애
              - 부모와 분리될 때 공황 → 분리불안장애
              - 지적 능력에 비해 낮은 학습기술 → 특정학습장애
              - 반복적인 소변 실수 → 유뇨증
              - 주의집중 곤란 → ADHD

            # 1. 이해를 위한 기본 내용 (중재의 근거)

            # 정의
            - 타인의 권리와 사회 규범을 반복해서 침해하는 장애이다.
            - 공격성, 재산 파괴, 사기와 절도, 심각한 규칙 위반을 보인다.

            # 중재가 이렇게 정해지는 이유
            - **공감과 죄책감이 부족**하다.
              - 그래서 도덕적 설교나 훈계는 효과가 없다.
              - **행동과 결과를 분명하게 연결**해 주어야 한다.
            - **좌절을 견디지 못하고 충동적**이다.
              - 그래서 분노 조절과 대처 기술을 가르쳐야 한다.
            - **조종하고 남을 탓하는 경향**이 있다.
              - 그래서 모든 직원과 부모가 **같은 규칙을 일관되게** 적용해야 한다.
            - 많은 경우 **가혹하거나 일관되지 않은 양육**, 학대, 방임의 경험이 있다.
              - 그래서 **부모 훈련과 가족 중재**가 필수이다.
              - 폭력적인 대응은 공격성을 본받게 한다.
            - 겉으로는 거칠지만 속으로는 **자존감이 낮다.**
              - 그래서 강점을 찾아 강화한다.

            # 치료 목표
            - 사회적 규범과 규칙을 지킨다.
            - 타인의 권리를 존중한다.
            - 공격 없이 분노를 표현한다.
            - 자신의 행동에 책임을 진다.

            # 2. 간호중재

            # ① 안전 확보 (최우선)
            - 타인과 자신에 대한 **폭력 위험**을 계속 사정한다.
            - 분노가 커지는 초기 신호를 알아차린다.
              - 목소리가 커진다.
              - 주먹을 쥐고 서성인다.
              - 욕설을 한다.
            - 초기 신호가 보이면 **조기에 개입**한다.
              - 자극이 적은 곳으로 옮기게 하고 진정할 시간을 준다(타임아웃).
              - 신체 활동으로 에너지를 풀게 한다.
            - 무기가 될 수 있는 물건을 치운다.
            - 폭력이 임박하거나 실제로 일어나면 충분한 인력으로 안전하게 대처한다.
              - 격리나 억제는 **최후의 수단**이다. 처벌이 아니라 안전을 위해 쓴다.

            # ② 제한설정: 문제행동이 일어났을 때 (2020-105)
            - 문제행동이 일어나면 **즉시** 개입한다.
              - 시간이 지나면 행동과 결과가 연결되지 않는다.
            - **감정적으로 반응하지 않고 차분하게** 대한다.
              - 화를 내거나 흥분하면 힘겨루기가 되고 공격성이 커진다.
            - **어떤 행동이 허용되지 않는지 분명하고 단호하게** 말한다.
              - 예: "기물을 파손하는 것은 허용되지 않는 행동이에요." (2020-105 정답)
            - **사람이 아니라 행동에 초점**을 맞춘다.
              - "나쁜 학생이군요"처럼 낙인을 찍지 않는다.
            - 규칙을 어겼을 때의 결과를 **미리 정해 두고 일관되게** 적용한다.
              - 위협하는 말투로 하지 않는다. 예: "이러면 격리실로 보낼 거예요."
              - 정해진 결과를 담담하게 실행한다.
            - 비난하는 질문은 하지 않는다.
              - 예: "도대체 무엇이 문제인가요?"
            - 추궁하거나 따지지 않는다.
              - 예: "배상은 어떻게 할 건가요?"
            - 논쟁하거나 협상하지 않는다.
            - **모든 직원이 같은 규칙**을 적용한다.
              - 규칙을 사람마다 다르게 적용하면 조종 행동이 생긴다.

            # ③ 행동수정요법
            - **바람직한 행동에는 즉시 칭찬과 보상**을 준다(정적 강화).
              - 문제행동보다 **좋은 행동에 더 관심**을 둔다.
            - **토큰 제도**를 쓴다.
              - 규칙을 지키면 점수를 준다.
              - 모은 점수로 특권(게임, 외출)과 바꾼다.
            - **행동 계약**을 맺는다.
              - 기대되는 행동, 보상, 결과를 아동과 함께 정하고 서면으로 남긴다.
            - **목표는 현실적이고 달성할 수 있게** 작게 나눈다.
              - 성공을 경험하게 한다.
              - "목표는 높게 설정"은 오답이다 (2026-105).
            - 규칙을 어겼을 때는 **논리적 결과**를 적용한다.
              - 예: 특권을 박탈한다.
              - 파손한 물건은 나이에 맞는 방식으로 책임지게 한다.
              - 체벌은 쓰지 않는다.

            # ④ 분노 조절과 대처 기술
            - 분노를 일으키는 상황과 **초기 신체 신호**를 스스로 알아차리게 한다.
            - 분노를 **행동이 아닌 말로 표현**하게 한다.
              - 예: "나는 ~할 때 화가 나."
            - 대체 행동을 연습한다.
              - 심호흡하기, 숫자 세기, 그 자리를 떠나기
              - 운동, 샌드백 치기
            - **문제해결 기술**을 가르친다.
              - 문제를 정의한다.
              - 해결 방법을 여러 개 떠올린다.
              - 각 방법의 결과를 예측한다.
              - 하나를 골라 실행한다.
            - 역할극으로 연습한다.

            # ⑤ 책임감과 인지의 수정
            - 자기 행동과 그 결과(타인의 피해, 자신이 받는 결과)의 **관계를 인식**하게 한다.
            - 남 탓과 합리화를 받아들이지 않는다. **자기 행동에 책임을 지게** 한다.
            - **인지 왜곡**을 수정한다.
              - 예: 남의 의도를 적대적으로 해석하는 것("쟤가 날 무시했다")
            - 피해자의 입장을 생각해 보게 해 **공감 능력**을 키운다.

            # ⑥ 사회기술훈련과 자존감 향상
            - 또래와 어울리는 적절한 방법을 가르친다.
              - 차례 지키기, 협상하기, 갈등 해결
            - 집단활동과 **소집단 치료**에서 연습하게 한다.
            - 스포츠, 예술, 관심 분야 같은 **강점**을 찾아 성공 경험을 준다.
            - 낙인을 찍지 않고 **존중하는 태도**를 유지한다.
            - 따뜻하되 단호한 어른과 긍정적인 관계를 맺게 한다. 그 어른이 역할모델이 된다.

            # ⑦ 부모 교육과 가족 중재 (2026-105)

            # 부모 훈련의 핵심
            - **문제행동에는 즉각적으로, 차분하고 단호하게** 대처한다 (2026-105 정답).
            - **규칙은 명확하고 일관되게** 적용한다.
              - "규칙은 융통성 있게 적용"은 오답이다.
              - 부모끼리도 같은 규칙을 쓴다.
            - **체벌이나 무력을 쓰지 않는다.**
              - "공격성을 보일 때는 무력으로 통제"는 오답이다.
              - 폭력은 공격성을 본받게 하고, 폭력과 반항의 악순환을 만든다.
            - **공격 행동을 받아 주지 않는다.**
              - "관심을 받기 위한 공격 행동은 수용"은 오답이다. 받아 주면 행동이 강화된다.
            - **현실적인 목표**를 정하고, 작은 성공도 칭찬한다.
              - 올바른 행동에 관심과 칭찬을 준다.

            # 가족 지지
            - 가족치료로 의사소통과 가족 역동을 개선한다.
            - **부모의 안전**을 확인한다. 부모가 폭행을 당하고 있다면 안전 계획을 세운다.
            - 부모의 스트레스와 죄책감을 다루고 지지한다.
            - 부모에게 정신질환이나 물질 남용이 있으면 함께 치료하도록 연계한다.
            - 학대나 방임이 의심되면 **신고**한다. 아동을 보호하는 것이 우선이다.

            # ⑧ 학교와 지역사회의 연계
            - 학교와 협력해 **같은 행동 관리 계획**을 적용한다.
            - 학습 문제가 있으면 학습을 지원한다.
            - 비행 또래와 어울리지 않게 하고, 건전한 여가 활동으로 대체한다.
            - 필요하면 청소년상담복지센터나 정신건강복지센터 같은 지역사회 자원을 연결한다.

            # ⑨ 동반 질환 치료
            - **ADHD**가 있으면 메틸페니데이트 같은 약물을 함께 쓴다. 충동성과 공격성도 줄어든다.
            - 우울, 불안, 물질 사용을 치료한다.
            - 공격성이 심하면 처방에 따라 약물을 보조적으로 쓴다: 리스페리돈, 기분안정제.
              - 약물이 중심은 아니다. **행동치료와 가족치료가 중심**이다.

            # 3. 비치료적 반응: 하지 말아야 할 것
            **간호사의 반응** (2020-105 오답)
            - 비난조 질문: "도대체 무엇이 문제인가요?"
            - 낙인: "나쁜 학생이군요."
            - 위협: "격리실로 보낼 거예요."
            - 추궁: "배상을 어떻게 할 건가요?"
            **부모의 양육** (2026-105 오답)
            - 규칙을 융통성 있게 적용한다.
            - 무력으로 통제한다.
            - 목표를 높게 설정한다.
            - 관심을 끌려는 공격 행동을 수용한다.

            # 그 밖에 피할 것
            - 훈계와 설교
            - 감정적으로 화내기
            - 논쟁이나 협상
            - 규칙을 사람마다 다르게 적용하기
            - 문제행동을 무시하기(안전 문제가 있을 때)
            - 체벌

            # 함께 보면 좋은 문항: 같은 원리의 성격장애 중재
            - 2020-97: 반사회적 성격장애 → 제한설정
            - 2026-97: 경계성 성격장애 → 중립적인 태도로 규칙 설명
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["정신건강간호의 이론적 모형"],
            title: "정신건강간호 이론적 모형 정리",
            body: #"""
            정신건강간호의 이론적 모형은 이상행동이 왜 생기는지, 어떻게 치료하는지, 치료자와 대상자가 각각 어떤 역할을 하는지를 설명하는 틀이다. 모형마다 이상행동의 원인을 보는 **핵심어**가 다르므로, 모형 이름과 핵심어를 짝지어 구별하는 것이 요점이다.

            # 국시 출제 경향
            - 2020~2026년에 **3문항**이 나왔다(2020, 2022, 2025년). 모두 2교시 71번 자리이다.
            - **사회모형**(2문항)
              - 2025-71 한 문화권의 문제행동이 다른 문화권에서는 정상일 수 있다고 보는 모형 → **사회모형**
              - 2022-71 사회적 모형에서 이상행동을 판단하는 기준 → **문화**
            - **실존모형**(1문항)
              - 2020-71 자신이나 환경으로부터 멀어질 때 일탈행동이 나타나고 '현재와 지금'을 강조하는 모형 → **실존모형**
            - 오답 보기의 구성
              - 2025-71·2020-71: 간호모형, 의학모형, 실존모형, 행동모형, 사회모형, 대인관계모형처럼 **다른 이론적 모형 이름**을 섞는다.
              - 2022-71: 행동, 의사소통, 대인관계, 개인 내적 갈등처럼 **다른 모형의 핵심 초점**을 보기로 낸다. 각각 행동모형, 의사소통모형, 대인관계모형, 정신분석모형에 해당한다.

            # 풀이 요령
            - "문화", "사회적 맥락", "다른 문화권에서는 정상"이 나오면 **사회모형**이다.
            - "자기·환경으로부터의 소외", "지금-여기", "선택과 책임", "삶의 의미"가 나오면 **실존모형**이다.
            - "잘못된 학습", "재학습", "강화"는 행동모형, "무의식적 갈등", "초기 아동기 경험"은 정신분석모형이다.
            - "대인관계에서 생긴 불안"은 대인관계모형, "메시지 전달의 왜곡"은 의사소통모형, "생물학적 원인·진단·약물"은 의학모형이다.

            # 1. 정신분석모형
            - **대표 이론가**: Freud, Erikson
            - **이상행동의 관점**: 초기 아동기의 해결되지 않은 발달 갈등이 무의식에 남아 불안을 일으키고, 이를 막기 위한 방어기제가 증상으로 나타난다.
            - **치료 과정**: 자유연상, 꿈 분석, 전이의 해석으로 무의식의 갈등을 의식화한다.
            - **역할**: 대상자는 떠오르는 생각을 모두 말하고, 치료자는 이를 해석한다.

            # 2. 대인관계모형
            - **대표 이론가**: Sullivan, Peplau
            - **이상행동의 관점**: 불안은 대인관계에서 생기고 경험된다. 거부에 대한 두려움, 안정감과 만족의 욕구가 채워지지 않으면 문제가 생긴다.
            - **치료 과정**: 치료자-대상자 관계 안에서 신뢰를 쌓고, 교정적인 대인관계 경험을 제공한다.
            - **역할**: 대상자는 치료자와 경험을 나누고, 치료자는 참여적 관찰자로서 관계를 활용한다.

            # 3. 사회모형
            - **대표 이론가**: Szasz, Caplan
            - **이상행동의 관점**: 개인의 행동을 사회·문화적 맥락에서 이해한다. 정상과 이상의 기준은 **문화**가 정하므로 한 문화의 문제행동이 다른 문화에서는 정상일 수 있다. 빈곤, 불안정한 가족, 부적절한 교육 같은 사회적 조건이 이상행동을 일으킨다고 본다.
            - Szasz는 정신질환을 사회가 붙인 낙인(정신질환의 신화)으로 보았고, Caplan은 1차·2차·3차 예방과 위기개입 개념을 제시하였다.
            - **치료 과정**: 사회적 지지체계와 지역사회 자원을 활용하고, 대상자가 스스로 치료를 선택하게 한다.
            - **역할**: 대상자는 문제를 제시하고 지역사회 자원을 활용하며, 치료자는 대상자와 협력하여 자원을 연결한다.

            # 4. 실존모형
            - **대표 이론가**: Perls(게슈탈트 치료), Glasser(현실요법), Ellis(합리적 정서치료), Rogers(내담자 중심 치료), Frankl(로고테라피)
            - **이상행동의 관점**: 개인이 자기 자신, 타인, 환경으로부터 **소외**되어 진정한 자기를 경험하지 못할 때 일탈행동이 나타난다.
            - **치료 과정**: '지금-여기(here and now)'의 경험에 초점을 두고, 자기인식을 높이며 자신의 선택과 행동에 책임지게 한다.
            - **역할**: 대상자는 자신의 행동에 책임을 지고, 치료자는 대상자와 동등한 관계에서 진정한 자기를 찾도록 돕는다.

            # 5. 의사소통·행동·의학·간호모형
            # 의사소통모형
            - **대표 이론가**: Berne(교류분석), Watzlawick
            - 메시지를 보내고 받는 과정이 **왜곡**되면 이상행동이 생긴다고 본다. 언어적·비언어적 의사소통 양식을 분석하고 명확한 의사소통을 가르친다.

            # 행동모형
            - **대표 이론가**: Pavlov, Skinner, Wolpe, Eysenck
            - 행동은 **학습된 것**이므로 부적응 행동도 잘못 학습된 결과이며 **재학습**으로 바꿀 수 있다고 본다.
            - 체계적 탈감작, 이완훈련, 토큰경제, 강화 같은 기법을 쓰고, 치료자는 교육자 역할을 한다.

            # 의학모형
            - 이상행동을 뇌의 **생물학적 질병**으로 본다. 진단을 내리고 약물치료, 전기경련요법 같은 신체적 치료를 한다. 치료자는 의사, 대상자는 처방을 따르는 역할이다.

            # 간호모형
            - 대상자를 생물·심리·사회·영적 측면을 가진 **전인적 존재**로 보고, 스트레스에 대한 반응을 사정하여 간호과정을 적용한다(Stuart의 스트레스 적응 모형 등).
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
