            title: "발달이론 정리",
            body: #"""
            발달이론은 사람이 태어나서 성장하는 동안 성격과 사고, 대인관계가 어떤 단계를 거쳐 형성되는지를 설명한다. 각 단계의 과업을 이루지 못하면 이후의 부적응이나 정신병리로 이어질 수 있다고 보므로, **이론가별 단계와 과업을 정확히 짝짓는 것**이 핵심이다.

            # 국시 출제 경향
            - 2020~2026년에 **4문항**이 나왔다(2021, 2023, 2024년). 2교시 71~72번 자리이다.
            - **프로이트 정신성적 발달단계**(2문항)
              - 2024-71 이성과의 관계에 집중하고 부모 의존과 독립 사이에서 갈등하는 시기 → **성기기**
              - 2021-72 동성 부모와 동일시하고 초자아가 발달하는 시기 → **남근기**
            - **이론가 구별**(1문항)
              - 2024-72 타인과의 대인관계를 통해 성격이 형성된다고 한 이론가 → **설리반**
            - **에릭슨 심리사회적 발달단계**(1문항)
              - 2023-72 과업을 이루지 못하면 열등감을 경험하는 단계 → **학령기**
            - 오답 보기의 구성
              - 2024-71·2021-72: 구강기, 항문기, 남근기, 잠복기, 성기기의 **프로이트 다섯 단계**를 모두 보기로 낸다.
              - 2024-72: 말러, 피아제, 에릭슨, 프로이트처럼 **다른 발달이론가**를 섞는다.
              - 2023-72: 청소년기, 성인기, 중년기, 노년기처럼 **에릭슨의 다른 단계**를 섞는다.

            # 풀이 요령
            - "오이디푸스 콤플렉스", "동일시", "초자아"는 **남근기**, "이성관계", "부모로부터 독립"은 **성기기**이다.
            - "대인관계를 통한 성격 형성", "불안은 대인관계에서 생긴다"는 **설리반**이다.
            - 에릭슨 문항은 위기 쌍(예: 근면성 대 열등감)과 연령을 함께 외워 두면 바로 풀린다.
            - "분리-개별화"는 말러, "인지발달", "보존개념"은 피아제이다.

            # 1. 프로이트의 정신성적 발달단계
            # 구강기 (0~1세)
            입을 통한 만족이 중심이다. 어머니와의 관계에서 신뢰와 의존을 경험한다. 고착되면 흡연, 과식, 지나친 의존 같은 구강기적 특성이 나타난다.

            # 항문기 (1~3세)
            배변훈련을 통해 자기 통제와 자율성을 익힌다. 고착되면 지나친 정리정돈, 인색함, 완고함(강박적 성격) 또는 반대로 무질서함이 나타날 수 있다.

            # 남근기 (3~6세)
            오이디푸스(엘렉트라) 콤플렉스를 겪고, 이를 해결하려고 **동성 부모와 동일시**한다. 성역할을 익히고 부모의 가치와 규범을 내면화해 **초자아**가 발달한다.

            # 잠복기 (6~12세)
            성적 욕구가 잠잠해지고, 에너지가 학습과 또래관계, 동성 친구와의 활동으로 향한다.

            # 성기기 (사춘기 이후)
            성적 에너지가 **이성과의 관계**로 향한다. 부모에 대한 의존과 독립 사이에서 갈등하며 성숙한 성 정체성을 형성한다.

            # 2. 에릭슨의 심리사회적 발달단계
            전 생애를 8단계로 나누고, 각 단계의 위기를 해결하면 긍정적 특성이 생긴다고 보았다.
            - **영아기(0~1세)**: 신뢰감 대 불신감
            - **유아기(1~3세)**: 자율성 대 수치심·회의
            - **학령전기(3~6세)**: 주도성 대 죄책감
            - **학령기(6~12세)**: 근면성 대 열등감
            - **청소년기(12~18세)**: 정체감 대 역할혼돈
            - **성인 초기**: 친밀감 대 고립감
            - **중년기**: 생산성 대 침체
            - **노년기**: 자아통합 대 절망

            # 3. 설리반의 대인관계 발달이론
            - 성격은 **의미 있는 타인과의 대인관계**를 통해 형성되고, 불안도 대인관계에서 생긴다고 보았다.
            - 불안을 피하려고 형성되는 **자기체계**에는 좋은 나(good me), 나쁜 나(bad me), 내가 아닌 나(not me)가 있다.
            - 단계는 유아기, 아동기, 소년기, 전청소년기, 초기 청소년기, 후기 청소년기로 나뉜다. 전청소년기에는 동성 친구와의 친밀한 관계(단짝)가 중요하다.
            - 페플라우의 대인관계 간호이론에 큰 영향을 주었다.

            # 4. 피아제의 인지발달이론
            - **감각운동기(0~2세)**: 감각과 운동으로 세상을 탐색하고 대상영속성을 획득한다.
            - **전조작기(2~7세)**: 상징과 언어를 사용하지만 자기중심적 사고와 물활론적 사고를 한다.
            - **구체적 조작기(7~11세)**: 보존개념과 분류를 익히고 구체적 사물에 대해 논리적으로 사고한다.
            - **형식적 조작기(11세 이후)**: 추상적·가설적 사고가 가능하다.

