            - **정상 자폐기**: 생후 첫 1개월 무렵, 자신과 외부를 구별하지 못한다.
            - **공생기**: 어머니와 자신을 하나로 느낀다.
            - **분리-개별화기**: 분화, 연습, 재접근, 대상항상성의 하위단계를 거쳐 어머니와 분리된 독립된 자기를 형성한다.
            - 재접근기의 갈등을 해결하지 못하는 것은 경계성 인격장애의 발생과 관련된다고 설명된다.
            """#
