            title: "사고 형태의 장애 정리",
            body: #"""
            사고 형태의 장애는 생각의 내용이 아니라 **생각이 이어지는 방식과 연결**에 문제가 생긴 상태이다. 대상자의 말을 들어 보고 목표에 도달하는지, 같은 말을 반복하는지, 생각 사이의 논리적 연결이 있는지를 따져 증상 이름을 붙이는 것이 핵심이다.

            # 국시 출제 경향
            - 2020~2026년에 **5문항**이 나왔다(2020, 2021, 2024, 2025년). 2교시 75, 76, 83, 84번 자리이다.
            - **목표 도달 여부로 구별**(1문항)
              - 2025-75 입원 이유를 묻자 여행, 세계 정세, 가족 이야기를 장황하게 하다가 결국 잠과 식사를 못 해 입원했다고 답함 → **우원증**
            - **같은 말의 반복**(2문항)
              - 2024-83 아침 반찬과 좋아하는 계절을 물어도 모두 "두부"라고 답함 → **보속증**
              - 2021-76 간호사의 "잘 주무셨어요?"를 "잘 주무셨어요, 잘 주무셨어요."로 따라 함 → **반향언어**
            - **논리적 연결의 소실**(2문항)
              - 2024-84 "점심을 먹고 바다가 파래, 자주색 김밥, 물고기 엄마…"라고 말하는 환자의 간호진단 → **언어적 의사소통장애**
              - 2020-83 "그네를 타고 소풍을 갔어. 죽어. 어서 해. 당연하지. 초콜릿." → **연상이완**
            - 오답 보기의 구성
              - 2025-75: 기시감, 보속증, 신어조작증, 사고이탈. 특히 **사고이탈**은 목표에 도달하지 못한다는 점에서 우원증과 구별된다.
              - 2024-83: 음송증, 음연상, 말비빔, 신어조작증처럼 **다른 언어 이상**을 섞는다.
              - 2021-76·2020-83: 우원증, 말비빔, 사고이탈, 연상이완, 양가감정, 사고지연, 사고두절처럼 **다른 사고장애 증상**을 섞는다.
              - 2024-84: 급성 혼동, 사회적 고립, 만성적 자존감 저하, 타인에 대한 폭력의 위험처럼 **사례의 자료로 뒷받침되지 않는 간호진단**을 섞는다.

            # 풀이 요령
            - 장황하게 돌아가도 **결국 질문에 답하면 우원증**, 끝내 답하지 못하고 빗나가면 **사고이탈**이다.
            - 질문이 바뀌어도 **같은 대답을 되풀이하면 보속증**, **상대의 말을 그대로 따라 하면 반향언어**이다.
            - 단어나 문장이 논리적 연결 없이 이어지면 **연상이완**(심하면 지리멸렬, 말비빔)이다. 주제가 빠르게 바뀌되 어느 정도 연결 고리가 있으면 조증의 **사고비약**이다.
            - 앞뒤가 맞지 않는 말 때문에 의미 있는 대화가 안 되는 사례에서 간호진단을 물으면 **언어적 의사소통장애**를 고른다.

            # 1. 사고장애의 분류
            - **사고 형태의 장애**: 생각과 생각이 연결되는 방식의 이상이다. 연상이완, 지리멸렬, 말비빔, 신어조작증 등이 있다.
            - **사고 흐름(진행)의 장애**: 생각이 흐르는 속도와 방향의 이상이다. 사고비약, 우원증, 사고이탈, 사고지연, 사고두절, 보속증 등이 있다.
            - **사고 내용의 장애**: 생각의 내용 자체의 이상이다. 망상, 강박사고, 공포 등이 있다.
            - 교재에 따라 형태와 흐름의 장애를 묶어 설명하기도 하므로, 분류보다 **각 증상의 정의**를 정확히 아는 것이 중요하다.

            # 2. 연결이 끊어지는 증상
            - **연상이완**: 생각 사이의 논리적 연결이 느슨하거나 없어져 관련 없는 내용이 이어진다. 조현병의 대표적 증상이다.
            - **지리멸렬**: 연상이완이 심해져 문장 전체가 앞뒤가 맞지 않아 이해할 수 없다.
            - **말비빔(word salad)**: 단어들이 의미 없이 뒤섞여 나열된다. 지리멸렬의 가장 심한 형태이다.
            - **음연상(clang association)**: 의미가 아니라 **소리(운율)가 비슷한 단어**로 생각이 이어진다. 조증과 조현병에서 나타난다.
            - **신어조작증**: 자기만 아는 새로운 단어를 만들어 쓴다.

            # 3. 흐름과 속도의 이상
            - **사고비약**: 생각이 매우 빠르게 이 주제에서 저 주제로 옮겨 간다. 연결 고리는 어느 정도 남아 있으며 **조증**에서 흔하다.
            - **우원증(우회적 사고)**: 불필요한 세부 사항을 장황하게 늘어놓지만 **결국 목표에 도달**한다.
            - **사고이탈(빗나간 사고)**: 질문과 관련 없는 쪽으로 빗나가 **목표에 도달하지 못한다**.
            - **사고지연**: 생각의 속도가 느려져 대답이 늦다. 우울증에서 흔하다.
            - **사고두절(사고차단)**: 말하는 도중 갑자기 생각이 끊겨 말이 멈춘다. 조현병에서 나타난다.
            - **사고빈곤**: 말의 양이나 내용이 빈약하다. 조현병 음성증상과 관련된다.

            # 4. 반복되는 말과 행동
            - **보속증**: 질문이나 자극이 바뀌어도 **같은 말이나 행동을 계속 반복**한다. 기질적 뇌장애와 조현병에서 나타난다.
            - **반향언어**: 다른 사람의 말을 앵무새처럼 **그대로 따라 한다**. 긴장형 조현병, 자폐스펙트럼장애에서 나타난다. 동작을 따라 하는 것은 반향동작이다.
            - **음송증**: 의미 없는 단어나 구절을 되풀이한다.

            # 5. 간호중재
            - 대상자의 말을 이해하지 못했으면 **이해한 척하지 않고** 솔직하게 말하며 명료화를 요청한다.
            - 짧고 단순하며 구체적인 문장으로 말하고, 한 번에 하나의 주제를 다룬다.
            - 대화가 빗나가면 원래 주제로 부드럽게 되돌린다. 우원증 대상자에게는 인내심을 가지고 들으면서 필요할 때 초점을 맞추게 한다.
            - 대상자의 말 속에 담긴 감정이나 주제를 찾아 반응한다.
            - 불안이 심하면 사고장애가 악화되므로 자극이 적고 조용한 환경을 제공한다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["지각장애: 환각과 착각"],
            title: "환각과 착각 정리",
            body: #"""
            지각장애는 감각기관으로 들어온 정보를 잘못 받아들이는 상태이다. **외부 자극 없이** 무언가를 지각하면 환각, **실제 있는 자극을 잘못** 지각하면 착각이며, 이 한 가지 차이로 대부분의 문항이 풀린다.

            # 국시 출제 경향
            - 2020~2026년에 **3문항**이 나왔다(2020, 2024, 2025년). 2교시 75번, 100번 자리이다.
            - **착각**(2문항)
              - 2025-100 섬망 환자가 창밖에서 흔들리는 나뭇잎을 가리키며 "저기 귀신이 있어요!" → **착각**
              - 2020-75 무늬가 있는 벽지를 가리키며 "저기 뱀이 기어가고 있어요." → **착각**
            - **환각**(1문항)
              - 2024-75 벽을 보며 "나를 욕하지 마!"라고 혼잣말함 → **환각**
            - 오답 보기의 구성
              - 2025-100: 망상, 해리, 전환, 이인증처럼 **지각 이외의 다른 증상**을 섞는다.
              - 2024-75: 망상, 상동증, 언어압박, 반향언어처럼 **사고·행동·언어의 이상**을 섞는다.
              - 2020-75: 작화증, 거부증, 지리멸렬, 신어조작증을 섞는다.

            # 풀이 요령
            - 사례에 **실제 사물(나뭇잎, 벽지 무늬, 그림자, 옷걸이)**이 있고 그것을 다른 것으로 보면 **착각**이다.
            - 아무도 없는데 소리를 듣고 반응하거나(혼잣말, 허공에 대답), 없는 것을 보면 **환각**이다.
            - 잘못된 **신념**은 망상, 잘못된 **지각**은 환각·착각이다. 둘을 혼동하지 않는다.
            - 섬망 환자의 착각을 줄이는 중재를 물으면 **적절한 조명**과 자극 조절을 고른다.

            # 1. 환각과 착각의 구별
            - **환각(hallucination)**: 외부 자극이 없는데도 실제처럼 지각한다. 대상자는 실제라고 확신한다.
            - **착각(illusion)**: 실제로 존재하는 외부 자극을 잘못 해석해 지각한다. 섬망, 알코올 금단, 어둡거나 피곤한 상황에서 흔하고 정상인에게도 나타날 수 있다.
            - **망상**: 지각이 아니라 잘못된 신념이다. 사고 내용의 장애에 속한다.

            # 2. 환각의 종류
            - **환청**: 가장 흔하며 조현병의 대표 증상이다. 대상자를 욕하거나 비난하는 목소리, 자신의 행동을 논평하는 목소리가 흔하다. 무언가를 하라고 지시하는 **명령 환청**은 자해·타해 위험이 있어 반드시 내용을 사정한다.
            - **환시**: 섬망, 알코올 금단, 물질 중독 같은 기질적 원인에서 흔하다.
            - **환촉**: 피부 위나 아래로 벌레가 기어가는 느낌으로, 알코올 금단이나 코카인 등 물질 사용에서 나타난다.
            - **환후, 환미**: 이상한 냄새나 맛을 느낀다. 음식에 독이 들었다는 피해망상과 함께 나타나기도 한다.
            - **입면환각, 출면환각**: 잠들 때나 깰 때 나타나며 정상인에게도 생길 수 있다.

            # 3. 관련된 지각·자기 인식의 이상
            - **이인증**: 자기 자신이 낯설거나 자신에게서 분리된 것처럼 느낀다.
            - **비현실감**: 주변 환경이 비현실적이거나 꿈속처럼 느껴진다.
            - **기시감(deja vu)**: 처음 보는 것을 전에 본 것처럼 느낀다. 반대로 익숙한 것을 처음 보는 것처럼 느끼는 것은 미시감이다.

            # 4. 환각이 있는 대상자의 간호
            - 환각의 내용, 빈도, 유발 상황을 사정한다. 특히 명령 환청이 있는지, 그 내용이 자해나 타해와 관련되는지 확인한다.
            - 혼잣말, 허공을 응시하거나 무언가를 듣는 듯한 몸짓 같은 **환각의 행동 단서**를 관찰한다.
            - 환각을 인정하거나 동조하지 않고, 논쟁하지도 않는다. "저에게는 그 소리가 들리지 않지만 당신에게는 들린다는 것을 압니다"처럼 현실을 알려 주면서 대상자의 경험과 감정을 인정한다.
            - 환각의 내용보다 **대상자가 느끼는 감정**(두려움, 불안)에 초점을 맞춘다.
            - 현실에 기반한 대화와 활동에 참여시키고, 환청 대처 방법(다른 사람과 대화하기, 노래 부르기, 음악 듣기)을 함께 찾는다.

            # 5. 섬망 환자의 착각 줄이기
            - 밤에 조명이 어두우면 착각이 심해지므로 **적절한 조명**(야간 조명)을 유지한다.
            - 그림자를 만드는 물건이나 무늬가 복잡한 환경 등 오해를 부르는 자극을 줄이고, 소음을 줄인다.
            - 시계, 달력, 익숙한 물건으로 지남력을 제공하고, 가능하면 같은 간호사가 돌본다.
            - 안경과 보청기를 착용하게 해 감각 정보를 정확히 받아들이게 한다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
