            body: #"""
            망상은 사실이 아닌데도 굳게 믿고, 반대 증거나 논리적 설득으로도 바뀌지 않는 잘못된 신념으로, **사고 내용의 장애**이다. 망상의 내용으로 종류를 구별하고, 망상장애는 조현병과 달리 행동이 기이하지 않고 기능이 비교적 유지된다는 점을 기억하는 것이 핵심이다.

            # 국시 출제 경향
            - 2020~2026년에 **5문항**이 나왔다(2020, 2021, 2022, 2023, 2025년). 2교시 75, 83, 85, 89번 자리이다.
            - **망상의 종류 구별**(3문항)
              - 2022-75 지나가는 사람들이 모두 자신에 대해 수군거린다고 함 → **관계망상**
              - 2021-83 뉴스 아나운서가 자신에 대해 이야기한다고 함 → **관계망상**
              - 2020-89 양극성장애 환자가 학교에서 세상을 놀라게 할 정보를 가져왔다고 함 → **과대망상**
            - **망상이 속하는 장애 영역**(1문항)
              - 2023-75 누군가 음식에 독을 탔다며 식사를 거부함 → **사고장애**
            - **망상장애의 특성**(1문항)
              - 2025-85 망상장애의 특성 → **행동이 명백하게 기이하지 않다**
            - 오답 보기의 구성
              - 2021-83·2020-89: 신체망상, 조종망상, 종교망상, 허무망상, 빈곤망상처럼 **다른 망상의 종류**를 섞는다.
              - 2022-75: 보속증, 지리멸렬, 양가감정, 사고비약처럼 **사고 형태·정서의 다른 증상**을 섞는다.
              - 2023-75: 언어장애, 의식장애, 정서장애, 지남력장애처럼 **다른 정신기능 영역**을 섞는다.
              - 2025-85: 환각이 심함, 성격 황폐화, 1개월 미만 지속, 일상생활이 어려울 정도의 기능 손상처럼 **조현병에 가까운 특성**이나 틀린 기간을 보기로 낸다.

            # 풀이 요령
            - TV, 라디오, 다른 사람의 대화나 행동이 **나와 관련 있다**고 해석하면 **관계망상**이다.
            - 특별한 능력, 지식, 지위, 부를 가졌다고 믿으면 **과대망상**이며 조증에서 흔하다. 가난해졌다, 죄를 지었다, 몸이 썩었다는 내용은 우울증의 빈곤·죄책·허무망상이다.
            - 누가 해치려 한다(독을 탔다, 감시한다)는 **피해망상**이며, 망상은 모두 **사고(내용)장애**에 속한다.
            - 망상장애는 **1개월 이상** 망상이 지속되지만 **행동이 기이하지 않고 기능이 유지**되며, 환각이 두드러지지 않고 성격 황폐화가 없다.

            # 1. 망상의 정의와 특징
            - 사실이 아닌 것을 굳게 믿는 **고정된 잘못된 신념**이다.
            - 반대 증거나 논리적 설득으로 교정되지 않는다.
            - 대상자의 교육 수준이나 문화적 배경으로 설명되지 않는다. 같은 문화권에서 공유되는 종교적 믿음은 망상이 아니다.
            - 대상자의 불안, 낮은 자존감, 두려움을 방어하는 기능을 하는 경우가 많다.

            # 2. 망상의 종류
            - **피해망상**: 누군가 자신을 해치거나 감시하거나 음해한다고 믿는다. 가장 흔하다.
            - **관계망상**: 자신과 무관한 사건, 다른 사람의 말과 행동, 방송 내용을 자신과 관련된 것으로 해석한다.
            - **과대망상**: 자신이 특별한 능력, 지식, 지위, 재산을 가졌다고 믿는다. 조증에서 흔하다.
            - **조종망상(피조종망상)**: 외부의 힘이 자신의 생각이나 행동을 조종한다고 믿는다.
            - **신체망상**: 몸에 심각한 이상이나 병이 있다고 믿는다.
            - **허무망상**: 자신이나 세상, 신체 일부가 존재하지 않는다고 믿는다. 심한 우울증에서 나타난다.
            - **빈곤망상, 죄책망상**: 가난해졌다거나 큰 죄를 지었다고 믿는다. 우울증에서 흔하다.
            - **질투망상**: 배우자나 연인이 부정을 저지른다고 믿는다.
            - **색정망상**: 대개 지위가 높은 사람이 자신을 사랑한다고 믿는다.
            - **종교망상**: 종교적 내용의 망상으로, 자신이 신이나 신의 사자라고 믿기도 한다.
            - **사고전파, 사고주입, 사고탈취**: 자기 생각이 남에게 알려진다, 남이 생각을 넣는다, 생각을 빼앗아 간다고 믿는다. 조현병에서 나타난다.

            # 3. 망상장애
            - 1개월 이상 지속되는 하나 이상의 망상이 있다.
            - 조현병의 진단기준을 만족하지 않는다. 환각은 없거나 두드러지지 않으며, 있더라도 망상의 주제와 관련된다.
            - 망상과 직접 관련된 영역을 제외하면 **기능이 뚜렷하게 손상되지 않고 행동이 명백하게 기이하지 않다**.
            - 조현병과 달리 **성격의 황폐화가 없다**.
            - 아형은 색정형, 과대형, 질투형, 피해형, 신체형, 혼합형 등으로 나뉜다.
            - 대상자는 병식이 없고 의심이 많아 치료를 거부하는 경우가 많으므로, 치료적 관계를 맺는 것이 가장 중요하다.

            # 4. 망상이 있는 대상자의 간호
            - 신뢰 관계를 형성한다. 약속을 지키고 일관되고 솔직한 태도를 유지한다.
            - 망상 내용에 대해 **논쟁하거나 설득하지 않고, 동의하지도 않는다**. 논쟁하면 망상이 오히려 굳어진다.
            - 망상의 내용보다 그 밑에 있는 **감정(두려움, 불안, 외로움)**에 반응한다.
            - 현실에 기반한 주제와 활동으로 관심을 돌리고, 망상에 대해 이야기하는 시간을 줄여 나간다.
            - 피해망상으로 음식을 거부하면 **개봉하지 않은 포장 음식**을 주거나 대상자가 직접 고르게 하고, 섭취량을 확인한다.
            - 피해망상이 심하면 공격성으로 이어질 수 있으므로 위험을 사정하고 안전한 환경을 유지한다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["신경생물학과 신경전달물질"],
            title: "신경전달물질과 뇌 구조 정리",
            body: #"""
            정신장애는 뇌의 구조와 기능, 신경전달물질의 불균형과 관련된다. 어떤 신경전달물질이 어떤 기능과 질환에 관여하는지, 어떤 뇌 부위가 어떤 기능을 맡는지를 짝지어 두면 약물의 작용과 부작용까지 함께 이해할 수 있다.

            # 국시 출제 경향
            - 2020~2026년에 **3문항**이 나왔다(2022, 2024, 2025년). 모두 2교시 76번 자리이다.
            - **신경전달물질과 질환**(2문항)
              - 2025-76 주요우울장애와 관련된 생물학적 요인 → **세로토닌 감소**
              - 2024-76 기분, 감정, 공격성, 각성, 수면, 강박장애, 조현병 음성증상에 영향을 주는 신경전달물질 → **세로토닌**
            - **뇌 구조와 기능**(1문항)
              - 2022-76 희로애락과 공격성 등 감정과 관련된 뇌 부위 → **변연계**
            - 오답 보기의 구성
              - 2025-76: 코티솔 감소, 갑상샘 기능 항진, 노르에피네프린 증가, 전두엽피질 활동 증가처럼 **우울증의 실제 변화와 방향이 반대인 보기**를 낸다.
              - 2024-76: 감마아미노부티르산, 도파민, 아세틸콜린, 노르에피네프린처럼 **다른 주요 신경전달물질**을 섞는다.
              - 2022-76: 중뇌, 연수, 뇌실, 소뇌처럼 **감정과 직접 관련이 적은 뇌 부위**를 섞는다.

            # 풀이 요령
            - 우울증은 **세로토닌·노르에피네프린 감소**, 코티솔 증가, 전두엽 활동 감소로 기억한다. "증가·항진"이 붙은 보기는 방향부터 확인한다.
            - 기분, 공격성, 수면, 식욕, 강박이 함께 나오면 **세로토닌**이다.
            - 조현병 양성증상과 운동(추체외로증상)은 **도파민**, 불안은 **GABA**, 기억과 알츠하이머병은 **아세틸콜린**이다.
            - 감정, 공격성, 공포, 기억이 나오면 **변연계**(편도체, 해마)이다.

            # 1. 주요 신경전달물질
            - **도파민**: 운동 조절, 보상과 동기, 사고에 관여한다. 과다하면 조현병의 양성증상과 관련되고, 부족하면 파킨슨병과 관련된다. 조증에서도 증가한다.
            - **세로토닌**: 기분, 감정, 공격성, 충동, 수면, 식욕, 통증 조절에 관여한다. 감소하면 우울, 불안, 강박장애와 관련되고, 조현병 음성증상에도 관여한다.
            - **노르에피네프린**: 각성, 주의, 스트레스 반응(투쟁-도피)에 관여한다. 감소하면 우울, 증가하면 조증이나 불안과 관련된다.
            - **GABA**: 대표적인 **억제성** 신경전달물질이다. 감소하면 불안과 관련되며, 벤조디아제핀은 GABA의 작용을 강화해 불안을 줄인다.
            - **아세틸콜린**: 기억, 학습, 인지에 관여한다. 알츠하이머병에서 감소하므로 콜린에스테라아제 억제제를 사용한다.
            - **글루타메이트**: 대표적인 **흥분성** 신경전달물질이다. 과다하면 신경세포를 손상시킬 수 있다.

            # 2. 질환별 신경전달물질 변화
            - **조현병**: 도파민 과다(양성증상). 세로토닌도 관여하여 도파민과 세로토닌 수용체를 함께 차단하는 비정형 항정신병약물이 음성증상에도 효과가 있다.
            - **우울증**: 세로토닌과 노르에피네프린 감소(모노아민 가설). 항우울제는 이들의 농도를 높인다.
            - **조증**: 노르에피네프린과 도파민 증가.
            - **불안장애**: GABA 감소, 노르에피네프린 증가, 세로토닌 이상.
            - **알츠하이머병**: 아세틸콜린 감소.

            # 3. 도파민 경로와 항정신병약물
            - **중뇌변연계 경로**: 도파민 과다가 양성증상(환각, 망상)과 관련된다. 이 경로의 차단이 항정신병약물의 치료 효과이다.
            - **중뇌피질 경로**: 도파민 부족이 음성증상과 인지 저하와 관련된다.
            - **흑질선조체 경로**: 운동을 조절한다. 이 경로가 차단되면 **추체외로증상**이 생긴다.
            - **결절누두 경로**: 프로락틴 분비를 억제한다. 차단되면 프로락틴이 증가해 유즙분비, 무월경이 생긴다.

            # 4. 뇌 구조와 기능
            - **전두엽**: 판단, 계획, 문제해결 같은 실행기능과 성격, 충동 조절을 맡는다. 조현병과 우울증에서 활동이 감소한다.
            - **측두엽**: 청각, 언어 이해, 기억에 관여한다.
            - **두정엽**: 감각 정보를 통합한다. **후두엽**은 시각을 처리한다.
            - **변연계**: 편도체, 해마, 시상하부 등으로 이루어진 '정서의 뇌'이다. 감정, 기억, 동기, 공격성을 조절한다. 편도체는 공포와 분노, 해마는 기억에 관여한다.
            - **시상하부**: 체온, 식욕, 수면, 성욕, 내분비(뇌하수체)를 조절한다.
            - **기저핵**: 운동 조절에 관여한다.
            - **소뇌**: 평형과 운동 협응을 맡는다. **연수**는 호흡과 심장박동 같은 생명 중추이다.
            - **뇌실**: 뇌척수액이 차 있는 공간이다. 조현병 대상자에게서 뇌실 확장이 관찰된다.

            # 5. 내분비와 정신장애
            - 우울증에서는 **시상하부-뇌하수체-부신 축**이 과활성화되어 **코티솔이 증가**한다.
            - **갑상샘 기능 저하**는 우울 증상과, 갑상샘 기능 항진은 불안이나 조증과 비슷한 증상과 관련된다. 리튬은 갑상샘 기능 저하를 일으킬 수 있다.
            - 멜라토닌은 수면-각성 주기를 조절하며, 계절성 우울과 관련된다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["항정신병약물과 부작용"],
            title: "항정신병약물과 부작용 정리",
            body: #"""
            항정신병약물은 도파민 D2 수용체를 차단해 환각, 망상 같은 양성증상을 줄이는 약물이다. 같은 도파민 차단 작용이 운동 조절 경로에서도 일어나면 추체외로증상이 생기고, 약물마다 무과립구증, 대사 이상, 항콜린 작용 같은 고유한 부작용이 있다. 간호사는 약물별 위험 부작용을 알고 정기 검사와 증상 관찰, 투약 교육을 맡는다.

            # 국시 출제 경향
            - 2020~2026년에 **5문항**이 나왔다(2020, 2022, 2023, 2025, 2026년). 2교시 76번, 78번, 85번 자리에 나왔다.
            - **클로자핀과 무과립구증**(3문항)
              - 2026-85 클로자핀 복용 환자에게 정기적으로 해야 하는 검사 → **전체혈구계산(CBC)**
              - 2023-78 클로자핀 복용 환자에게 CBC를 정기적으로 시행하는 이유 → **무과립구증 확인**
              - 2022-85 클로자핀 복용 조현병 환자의 간호중재 → **백혈구 수치를 정기적으로 확인한다**
            - **추체외로증상의 원인 신경전달물질**(2문항)
              - 2025-78 할로페리돌 복용 중 몸이 뻣뻣해지고 미세한 진전이 생김, 관련 신경전달물질 → **도파민**
              - 2020-76 추체외로 부작용은 어떤 신경전달물질의 차단으로 생기는가 → **도파민**
            - 오답 보기의 구성
              - 2026-85·2023-78·2022-85: 혈중약물농도(TDM), 갑상샘기능검사, 전해질처럼 **리튬 복용 시 확인하는 항목**, 고혈압성위기(MAO 억제제), 세로토닌 증후군(세로토닌 약물)처럼 **다른 약물의 부작용**을 섞는다.
              - 2022-85: 정좌불능증, 지연성 운동장애는 추체외로증상인데, 클로자핀은 추체외로증상이 거의 없어 오답이다.
              - 2025-78·2020-76: 아세틸콜린, 세로토닌, 노르에피네프린, 멜라토닌, 글루타메이트, GABA를 보기로 둔다. 아세틸콜린은 증상 완화(항콜린제)와 관련될 뿐 원인은 **도파민 차단**이다.

            # 풀이 요령
            - 클로자핀이 나오면 **무과립구증 → CBC(백혈구·호중구) 정기 확인**을 고른다.
            - 혈중농도 정기 측정, 갑상샘기능검사, 나트륨·다뇨는 **리튬**의 보기이므로 클로자핀 문항에서는 오답이다.
            - 할로페리돌 같은 정형 약물로 경직, 진전, 근긴장이상이 생기면 원인은 **도파민 차단**이다.
            - 추체외로증상 치료는 항콜린제(벤즈트로핀)이지만, 원인을 물으면 아세틸콜린이 아니라 도파민을 고른다.

            # 1. 항정신병약물의 분류

            # 정형(1세대) 항정신병약물
            할로페리돌, 클로르프로마진 등이다. 주로 D2 수용체를 차단해 양성증상에 효과가 있지만 음성증상에는 효과가 적다.
            - 고역가 약물(할로페리돌): 추체외로증상이 흔하다.
            - 저역가 약물(클로르프로마진): 진정, 기립성 저혈압, 항콜린 부작용이 흔하고 광과민성이 있다.

            # 비정형(2세대) 항정신병약물
            클로자핀, 리스페리돈, 올란자핀, 쿠에티아핀, 아리피프라졸 등이다. D2와 세로토닌(5-HT2A) 수용체를 함께 차단해 양성증상과 음성증상 모두에 효과가 있고 추체외로증상이 적다. 대신 체중 증가, 고혈당, 이상지질혈증 같은 **대사 부작용**이 문제가 된다.

            # 2. 추체외로증상(EPS)
            흑질-선조체 경로의 도파민이 차단되면 상대적으로 아세틸콜린이 우세해져 운동 이상이 생긴다.
            - **급성 근긴장이상**: 투약 초기(수시간~수일)에 목, 혀, 얼굴 근육이 갑자기 수축한다. 사경, 안구운동발작(눈이 위로 돌아감)이 나타나고 후두 경련은 응급이다. 항콜린제(벤즈트로핀)나 디펜히드라민을 투여한다.
            - **정좌불능증(좌불안석)**: 가만히 앉아 있지 못하고 계속 움직이려 한다. 불안이나 초조로 오인하기 쉽다. 베타차단제(프로프라놀롤), 벤조디아제핀, 약물 감량으로 조절한다.
            - **가성파킨슨증**: 근육 경직, 진전, 운동완만, 가면 같은 얼굴, 종종걸음이 나타난다. 항콜린제로 완화한다.
            - **지연성 운동장애**: 장기 복용 후 입맛 다시기, 혀 내밀기, 씹는 동작 같은 불수의 운동이 생긴다. 되돌리기 어려울 수 있어 조기 발견이 중요하고, 이상불수의운동척도(AIMS)로 정기 평가한다. 항콜린제는 효과가 없고 오히려 악화시킬 수 있다.

            # 3. 그 밖의 중요한 부작용

            # 신경이완제 악성증후군(NMS)
            드물지만 치명적인 응급상황이다. 고열, 심한 근육 강직, 자율신경 불안정(혈압 변동, 빈맥, 발한), 의식 변화가 나타나고 CPK가 상승한다. 즉시 약물을 중단하고 해열·수액 등 대증요법을 하며, 단트롤렌이나 브로모크립틴을 쓴다.

            # 항콜린 부작용
            입마름, 변비, 요정체, 시야 흐림이 나타난다. 수분 섭취, 무설탕 껌, 섬유질 섭취를 권하고 요정체를 관찰한다.

            # 기타
            - **기립성 저혈압**: 천천히 일어나도록 교육한다.
            - **고프로락틴혈증**: 유즙분비, 무월경, 여성형 유방이 생길 수 있다(리스페리돈, 정형 약물).
            - **대사증후군**: 체중, 허리둘레, 혈당, 지질을 정기적으로 확인한다(올란자핀, 클로자핀).
            - **진정, 경련 역치 저하, QT 간격 연장**

            # 4. 클로자핀
            치료저항성 조현병에 쓰는 비정형 약물로, 추체외로증상과 지연성 운동장애가 거의 없다.
            - **무과립구증**: 가장 중요한 부작용이다. 투약 초기에는 매주, 이후에도 정기적으로 CBC로 백혈구와 호중구 수를 확인한다. 발열, 인후통, 구내염 같은 감염 증상이 생기면 즉시 알리도록 교육한다.
              국시: 2026-85, 2023-78, 2022-85
            - 그 밖에 경련, 침 흘림, 체중 증가와 대사 이상, 심근염, 진정, 변비에 주의한다.

