            # 1. 항우울제

            # 선택적 세로토닌 재흡수 억제제(SSRI)
            플루옥세틴, 설트랄린, 에스시탈로프람, 파록세틴 등이다. 세로토닌 재흡수만 선택적으로 막아 부작용이 적고 과량 복용해도 비교적 안전해 1차 약물로 쓴다.
            - 부작용: 오심, 설사 같은 위장관 증상, 두통, 불면 또는 초조, 성기능 장애
            - 효과가 나타나기까지 보통 2~4주가 걸린다는 점을 미리 알려 임의 중단을 막는다.

            # 삼환계 항우울제(TCA)
            아미트립틸린, 이미프라민, 노르트립틸린 등이다.
            - 항콜린 부작용(입마름, 변비, 요정체, 시야 흐림), 기립성 저혈압, 진정, 체중 증가가 흔하다.
            - 과량 복용 시 부정맥 같은 **심장독성**으로 치명적일 수 있어, 자살 위험이 있는 대상자에게는 소량씩 처방하고 투약을 확인한다.

            # 단가아민 산화효소 억제제(MAO 억제제)
            단가아민을 분해하는 효소를 억제한다. 티라민이 많은 음식(숙성 치즈, 와인, 맥주, 훈제·절인 고기, 발효식품)을 먹으면 티라민이 분해되지 않아 **고혈압 위기**(심한 후두부 두통, 목 경직, 빈맥)가 올 수 있다. 우리나라에서는 항우울제로 거의 쓰이지 않아 다시 출제될 가능성은 낮다(파킨슨병에 쓰는 MAO-B 억제제는 따로 있다).
            국시: 2021-78

            # 그 밖의 항우울제
            - **SNRI(벤라팍신, 둘록세틴)**: 세로토닌과 노르에피네프린 재흡수를 함께 억제한다. 혈압 상승에 주의한다.
            - **부프로피온**: 성기능 장애와 체중 증가가 적지만 경련 위험이 있다.
            - **미르타자핀**: 진정과 식욕·체중 증가가 흔하다.

            # 2. 세로토닌 증후군
            SSRI를 다른 세로토닌 약물(다른 항우울제, 트라마돌, 트립탄 등)과 함께 쓰거나 용량을 올릴 때 생긴다. 초조, 혼돈, 고열, 발한, 빈맥, 설사, 근간대경련, 반사항진이 나타난다. 즉시 원인 약물을 중단하고 보고한다.

            # 3. 항우울제 복용 간호
            - 약효가 나타나며 에너지가 먼저 회복되는 시기에 **자살 위험이 높아질 수 있으므로** 초기 몇 주간 면밀히 관찰한다. 청소년과 젊은 성인에서 특히 주의한다.
            - 증상이 좋아져도 처방 기간 동안 계속 복용하게 하고, 끊을 때는 의사와 상의해 서서히 줄이게 한다.
            - 알코올을 피하게 한다.

            # 4. 항불안제

            # 벤조디아제핀
            로라제팜, 알프라졸람, 디아제팜 등이다. GABA의 억제 작용을 강화해 빠르게 불안을 줄인다.
            - 부작용: 졸림, 어지러움, 운동 실조, 기억력 저하. 노인은 낙상 위험이 크다.
            - 알코올 같은 중추신경억제제와 함께 먹으면 호흡억제 위험이 있다. 과량 복용 시 해독제는 플루마제닐이다.
            - 장기 복용하면 **내성과 신체의존**이 생긴다. 그래서 단기간 사용을 원칙으로 한다.
            - 갑자기 끊으면 불안, 불면, 진전, 초조가 생기고 심하면 경련이 올 수 있으므로 **서서히 감량**한다.
              국시: 2026-78 (로라제팜 효과가 줄어 두 배로 복용 → 내성)

            # 부스피론
            세로토닌 수용체에 작용하는 비벤조디아제핀 항불안제이다. 진정 작용이 적고 의존과 금단이 거의 없다. 효과가 나타나기까지 수주가 걸려 급성 불안에 필요할 때만 먹는 약으로는 맞지 않다.

            # 5. 헷갈리기 쉬운 용어
            - **내성**: 같은 효과를 얻으려면 용량을 계속 늘려야 하는 상태
            - **금단**: 물질을 끊거나 줄였을 때 나타나는 신체적·정신적 증상
            - **의존**: 물질을 계속 써야 정상적으로 기능할 수 있는 상태로, 끊으면 금단이 나타난다.
            - **진전섬망**: 알코올 금단의 심한 형태
