            지역사회 정신건강은 정신질환자를 병원에 오래 머물게 하는 대신 살던 지역사회 안에서 치료, 재활, 예방, 정신건강증진을 받도록 하는 접근이다. 대상은 환자 개인이 아니라 지역사회 전체이고, 여러 전문가와 비전문인력이 팀을 이루어 연속적이고 포괄적인 서비스를 제공한다.

