              - 2020-80 인지기능이 손상된 퇴원 예정 조현병 환자에게 24시간 관리·감독과 사회기술훈련을 하는 주거서비스 → **집단가정(group home)**
            - **우선 제공할 서비스**(1문항)
              - 2026-79 윗집 사람이 자기를 죽이려 한다며 다툰 조현병 대상자를 경찰이 의뢰 → **의료기관 연계**
            - 오답 보기의 구성
              - 2024-79·2023-79·2022-80·2021-79: 장기 입원, 병원·정신의료기관 기반, 개인 진단 중심, 급성환자 중심, 비전문인력 참여 제한, 간접 서비스 지양, 단편적·단기 집중 서비스, 멀고 조용한 곳에 센터 배치처럼 **병원 중심 의학모형의 특징**을 뒤집어 놓는다.
              - 2025-79: 의사가 치료방향 결정, 증상 경감에 초점, 취약점과 병리 강조, 입원과 약물치료 중심 → 모두 의학모형이다.
              - 2026-80: 동료지원, 위기관리, 직업재활, 사회기술훈련처럼 **다른 지역사회 서비스 이름**을 섞는다.
              - 2020-80: 위탁가정, 중간치료소, 지정아파트, 공동거주센터처럼 **다른 주거서비스**를 섞는다.
              - 2026-79: 주거 지원, 여가활동 지원, 직업재활 훈련, 일상생활기술 훈련은 **증상이 안정된 뒤의 재활 서비스**이다.

            # 풀이 요령
            - 특성 문항은 **지역사회 전체 대상, 다학제 팀, 비전문인력 참여, 예방과 증진, 연속적·포괄적 서비스**가 들어간 보기를 고른다. 병원, 입원, 개인 책임, 단편적, 참여 제한이 들어가면 오답이다.
            - "포괄적으로 사정하고 맞춤형 서비스를 계획·연계·지속 제공"은 **사례관리**이다.
            - 정신사회재활은 증상 제거가 아니라 **삶의 질, 독립, 강점**이다.
            - 망상 때문에 다툼이 생기는 등 **급성 악화로 위험한 상태**라면 재활보다 **의료기관 연계**가 먼저이다.
            - 주거서비스에서 **24시간 관리·감독**이 나오면 집단가정이다.

            # 1. 지역사회 정신건강의 특성
            탈원화 이후 장기 입원 중심의 치료를 반성하며 발전했다.
            - **지역사회 전체**가 대상이다. 정신질환자뿐 아니라 고위험군과 일반 주민도 포함한다.
            - 치료뿐 아니라 **예방과 정신건강증진**을 강조한다.
            - 정신건강간호사, 정신건강의학과 의사, 임상심리사, 사회복지사가 함께하는 **다학제 팀 접근**을 한다.
            - 자원봉사자, 동료지원가 같은 **비전문인력과 준전문인력**이 참여한다.
            - 직접 서비스뿐 아니라 자문, 교육 같은 **간접 서비스**도 제공한다.
            - 장기적이고 **연속적·포괄적** 서비스를 제공한다.
            - 정신질환을 개인이 아닌 **지역사회의 공동 책임**으로 보고, 가족과 가깝고 이용하기 쉬운 곳에서 치료한다.

            # 2. 의학모형과 정신사회재활모형
            - **의학모형**: 의사가 치료방향을 정하고, 증상과 병리에 초점을 두며, 입원과 약물치료가 중심이다.
            - **정신사회재활모형**: 대상자가 지역사회에서 가능한 한 독립적으로 생활하며 **삶의 질**을 높이도록 돕는다. 대상자의 **강점과 선택**을 존중하고, 기술 훈련과 환경 지원을 함께 제공한다. 증상이 남아 있어도 기능과 역할을 회복하는 것을 목표로 한다.
              국시: 2025-79

            # 3. 주요 지역사회 서비스

            # 사례관리
            대상자의 증상, 욕구, 강점과 취약점, 가족을 포함한 환경을 포괄적으로 사정하고, 맞춤형 서비스를 계획·연계·조정하며 지속적으로 점검한다. 만성 정신질환자가 지역사회에서 살아가도록 돕는 핵심 서비스이다.
            국시: 2026-80

            # 그 밖의 서비스
            - **위기관리**: 급성 위기 상황에 대한 단기 개입이다.
            - **적극적 지역사회치료(ACT)**: 다학제 팀이 대상자를 직접 찾아가 치료와 생활 지원을 집중적으로 제공한다. 재입원이 잦은 중증 대상자가 주 대상이다.
            - **낮병원**: 낮에는 치료 프로그램에 참여하고 밤에는 집으로 돌아간다.
            - **동료지원**: 회복 경험이 있는 당사자가 대상자를 돕는다.
            - **사회기술훈련**: 대인관계와 의사소통 기술을 가르친다.
            - **직업재활**: 취업 준비, 취업, 직업 유지를 돕는다.
            - **가족교육과 가족지원**: 질병 이해, 재발 징후, 대처 방법을 교육한다.

            # 4. 주거서비스
            - **집단가정(group home)**: 여러 명이 함께 살며 전문 인력이 **24시간 관리·감독**하고 일상생활기술과 사회기술훈련을 제공한다.
              국시: 2020-80
            - **중간치료소(halfway house)**: 입원과 지역사회 생활 사이의 과도기 시설이다.
            - **지정아파트(satellite apartment)**: 독립생활이 가능한 사람에게 최소한의 지원을 한다.
            - **위탁가정(foster house)**: 대상자를 일반 가정에 맡겨 함께 생활하게 한다.

