            # 풀이 요령
            - **아직 병이 없는 사람**에게 하는 교육, 훈련, 증진 활동은 1차 예방이다. 고위험군(실직자, 노숙자, 소방공무원)을 대상으로 해도 발생을 막는 교육이면 1차이다.
            - **선별검사, 조기검진, 위기 중재, 초기 환자 진료 연계, 응급 지원**은 2차 예방이다.
            - **만성, 퇴원, 재활, 재발 방지, 사례관리, 일상생활기술**이 나오면 3차 예방이다.
            - 같은 "교육"이라도 대상이 만성 정신질환자이고 기능 회복이 목적이면 3차 예방이다.

            # 1. 1차 예방
            정신질환의 **발생 자체를 막는** 활동이다. 발생률을 낮추는 것이 목표이다.
            - 건강증진: 정신건강 교육, 스트레스 관리 교육, 부모 역할 훈련, 또래 관계 증진 프로그램
            - 특정 질환 예방: 약물남용 예방교육, 임산부 우울증 예방 교육
            - 고위험군 지원: 실직자, 노숙자, 재난 경험자 같은 취약 집단에 대한 교육과 지원
            - 사회 환경 개선: 정책과 제도를 통해 스트레스 요인을 줄이는 활동
              국시: 2024-80, 2020-79

            # 2. 2차 예방
            질병을 **조기에 발견하고 조기에 치료**해 유병기간을 줄이는 활동이다. 유병률을 낮추는 것이 목표이다.
            - 선별검사와 조기검진: 우울증 선별검사, 생애주기별 정신건강 검진
            - 초기 정신질환자를 외래 진료에 연계하거나 신속하게 치료받도록 의뢰
            - **위기중재**: 위기에 처한 사람에게 즉시 개입해 더 큰 문제로 번지는 것을 막는다.
            - 응급입원 지원, 성폭력 피해자 긴급지원
              국시: 2022-79

            # 3. 3차 예방
            이미 생긴 정신장애로 인한 **기능 손상과 장애를 줄이고 재발을 막아** 사회에 복귀하도록 돕는 재활 활동이다.
            - 직업재활, 일상생활기술 교육, 사회기술훈련
            - 퇴원한 정신질환자의 사례관리, 약물 및 증상 관리 교육
