            위기는 스트레스 사건을 평소의 대처 방법으로 해결하지 못해 심리적 평형이 깨진 상태이다. 위기는 원인에 따라 성숙(발달)위기, 상황위기, 우발적(재난)위기로 나뉘며, 사건이 **예상 가능한지**와 **몇 명에게 닥치는지**로 구별한다. 위기는 대개 수주 안에 어떤 방향으로든 해소되므로 즉각적인 개입이 중요하다.

            # 국시 출제 경향
            - 2020~2026년에 **5문항**이 나왔다(2020, 2021, 2023, 2024, 2025년). 2교시 80번, 81번 자리에 나왔다.
            - **성숙(발달)위기 고르기**(3문항)
              - 2024-81 성숙(발달)위기에 해당하는 사건 → **입학**
              - 2021-81 성숙위기에 해당하는 사건 → **정년퇴직**
              - 2020-81 성숙과 관련해 위기를 유발할 수 있는 사건 → **정년퇴직**
