              - 2023-81 상황위기에 해당하는 사건 → **실직**
            - **우발적(재난)위기 고르기**(1문항)
              - 2025-80 우발적 위기(재난위기)에 해당하는 것 → **홍수**
            - 오답 보기의 구성
              - 모든 문항이 **세 유형의 사건을 섞어** 놓고 한 유형을 고르게 한다.
              - 성숙위기 보기: 결혼, 정년퇴직, 동생 출생, 자녀 탄생(2025-80, 2023-81)
              - 상황위기 보기: 이혼, 실직, 파산, 암진단, 불치병, 정신질환 진단, 사랑하는 사람의 죽음(2025-80, 2024-81, 2021-81, 2020-81)
              - 우발적 위기 보기: 화재, 비행기 추락(2024-81, 2020-81). 2021-81의 교통사고는 개인 사고라면 상황위기, 대형 사고라면 우발적 위기로 볼 수 있다.

            # 풀이 요령
            - 인생 주기에서 **누구나 예상할 수 있는 전환기**(입학, 사춘기, 결혼, 출산, 동생 출생, 정년퇴직)는 성숙위기이다.
            - **개인에게 예상치 못하게 일어난 사건**(실직, 이혼, 파산, 질병 진단, 사별)은 상황위기이다.
