            - 결혼과 이혼, 정년퇴직과 실직처럼 짝을 이룬 보기가 자주 나온다. 예상된 전환이면 성숙, 예상 못한 상실이면 상황이다.

            # 1. 위기의 개념과 특성
            - 위기 자체는 병이 아니라 누구에게나 올 수 있는 정상적인 반응이다.
            - 위기는 스스로 제한되는 경향이 있어 대개 **4~6주** 안에 해소된다. 이때 위기 이전보다 나은 수준, 같은 수준, 또는 더 낮은 수준으로 회복될 수 있다.
            - 위기는 위험이면서 동시에 성장의 기회이다.
            - 위기 상태의 사람은 불안이 높아 도움을 받아들이려는 마음이 커지므로 개입의 효과가 크다.

            # 2. 위기의 유형

            # 성숙(발달)위기
            에릭슨의 발달단계처럼 인생 주기에서 예상되는 전환기에 새로운 역할과 과업을 맡으며 생긴다. 입학, 사춘기, 결혼, 출산, 동생 출생, 자녀 독립, 정년퇴직이 해당한다.
            국시: 2024-81, 2021-81, 2020-81

            # 상황위기
            예상하지 못한 외부 사건으로 개인의 평형이 깨지는 위기이다. 실직, 이혼, 파산, 질병이나 불치병 진단, 사고, 사랑하는 사람의 죽음이 해당한다.
            국시: 2023-81

            # 우발적(재난, 사회적)위기
            예측할 수 없고 여러 사람과 지역사회 전체에 영향을 주는 사건이다. 홍수, 지진, 태풍 같은 자연재해, 화재, 비행기 추락 같은 대형사고, 전쟁, 테러가 해당한다.
            국시: 2025-80

            # 3. 위기 발생에 영향을 주는 균형 요인(Aguilera)
            스트레스 사건이 모두 위기가 되는 것은 아니다. 다음 세 가지 균형 요인 중 하나 이상이 부족하면 위기로 이어진다.
            - **사건에 대한 현실적인 지각**: 사건을 왜곡 없이 받아들이는가
            - **적절한 상황적 지지**: 도움을 줄 가족, 친구, 기관이 있는가
            - **적절한 대처기전**: 이전에 효과가 있었던 대처 방법이 있는가

            사정할 때도 이 세 가지를 확인한다.

            # 4. 위기중재의 원리
            위기중재의 목표는 대상자를 **최소한 위기 이전의 기능 수준으로 회복**시키는 것이다.
            - **즉각적**으로 개입한다. 위기가 해소되는 기간이 짧기 때문이다.
            - **안전을 먼저 확인**한다. 자살이나 타살 위험을 가장 먼저 사정한다.
            - **현재의 문제(지금-여기)**에 초점을 둔다. 과거의 성격 문제를 깊이 다루지 않는다.
            - 간호사는 **적극적이고 지시적**인 역할을 한다. 대상자가 스스로 결정하기 어려운 상태이기 때문이다.
            - **단기적**이고 목표가 구체적이며 현실적이다.
            - 대상자의 강점과 과거에 효과가 있었던 대처기전을 찾아 활용하고, 가족과 지역사회 자원 같은 지지체계를 연결한다.
            - 위기중재는 문제가 생긴 시점에 조기에 개입하는 것이므로 **2차 예방**에 해당한다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["조현병의 증상과 간호진단"],
            title: "조현병의 증상과 간호진단 정리",
            body: #"""
            조현병은 망상, 환각, 와해된 사고와 행동 같은 양성증상과 무감동, 무의욕, 사회적 위축 같은 음성증상이 함께 나타나며 현실 검증력과 사회적 기능이 떨어지는 정신병적 장애이다. 간호사는 증상을 양성과 음성으로 나누어 사정하고, 자료에 근거해 우선순위가 높은 간호진단을 세운 뒤 안전을 최우선으로 중재한다.

            # 국시 출제 경향
            - 2020~2026년에 **6문항**이 나왔다(2020, 2022, 2023, 2025년). 2교시 83~85번 자리에 나온다.
            - **사례를 보고 간호진단 고르기**(3문항)
              - 2025-83 "10년 동안 쓸모없는 삶"이라 말하고 자기 그림을 찢는 만성 환자 → **만성적 자존감 저하**
              - 2023-85 아무와도 대화하지 않고 표정 없이 혼자 지냄 → **사회적 고립**
              - 2022-83 환청에 반응해 다른 사람에게 주먹을 휘두름 → **타인에 대한 폭력의 위험**
            - **'타인에 대한 폭력의 위험' 간호중재**(2문항)
              - 2023-84 폭력 위험 진단을 받은 입원 환자 → **공격적 행동에 대한 제한 설정**
              - 2020-84 폭력 위험 진단을 받은 환자 → **행동화하면 직원이 상황을 통제할 수 있음을 알림**
            - **양성증상과 음성증상 구별**(1문항)
              - 2023-83 양성증상에 해당하는 것 → **피해망상**
            - 오답 보기의 구성
              - 2023-84·2020-84: 경쟁적 집단활동, 크고 신나는 음악(록·랩), 사람 많은 곳, 화려한 병실처럼 **자극을 늘리는 중재**와 **예방 목적의 24시간 억제·격리**가 반복된다.
              - 2023-83: 무감동, 언어빈곤, 무의욕증, 사회성 결여 등 **음성증상**을 오답으로 둔다.
              - 2025-83·2023-85·2022-83: 사회적 고립, 자기돌봄 결핍, 사고과정장애, 수면박탈, 상해의 위험, 부모역할장애, 만성 통증, 비활동적 생활양식, 언어적 의사소통 장애처럼 **사례에 근거 자료가 없는 진단**을 섞는다.
              - 2025-83: 그림을 찢은 행동을 '타인에 대한 폭력의 위험'으로 착각하게 만든다. 자기 작품을 찢는 것은 **자기비하 표현**이다.

            # 풀이 요령
            - 사례에서 이미 타인을 때리거나 위협하는 행동이 있으면 **타인에 대한 폭력의 위험**이 우선이다.
            - 폭력 위험 중재는 **제한설정, 자극 감소, 직원이 통제할 수 있다는 확신 제공**을 고른다. 자극을 늘리는 활동과 예방 목적의 장시간 억제는 오답이다.
            - 진단은 사례에 나온 단서와 정확히 맞는 것을 고른다. 혼자 지내고 대화하지 않음은 **사회적 고립**, 오랫동안 반복되는 자기 비하는 **만성적 자존감 저하**이다.
            - "더해진 것"(망상, 환각, 와해)은 양성, "없어지거나 줄어든 것"(무감동, 무의욕, 언어빈곤, 무쾌감, 사회적 위축)은 음성이다.

            # 1. 조현병의 개념과 경과
            조현병은 사고, 지각, 정서, 행동, 사회적 기능 전반에 장애가 나타나는 만성 정신질환이다. 주로 후기 청소년기에서 초기 성인기에 발병한다.
            - **진단 기준(DSM-5)**: 망상, 환각, 와해된 언어, 심하게 와해된 행동이나 긴장증, 음성증상 가운데 2가지 이상이 1개월 이상 뚜렷하고, 그중 하나는 망상·환각·와해된 언어여야 한다. 장애의 징후는 6개월 이상 지속된다.
            - **전구기**: 사회적 위축, 흥미 상실, 학업·직업 기능 저하, 위생 소홀, 기이한 생각이 서서히 나타난다.
            - **활성기**: 망상, 환각, 와해 같은 정신병적 증상이 뚜렷하다.
            - **잔류기**: 활성기 증상은 줄었지만 음성증상이나 약화된 형태의 증상이 남는다.
            - 원인으로는 유전, 도파민 가설(중뇌변연계 도파민 과활성은 양성증상, 중뇌피질 도파민 저하는 음성증상과 관련), 뇌 구조 이상, 스트레스-취약성 모델이 설명된다.

            # 2. 양성증상과 음성증상, Bleuler의 4A

            # 양성증상
            정상 기능에 무언가가 **더해지거나 왜곡된 것**이다. 항정신병약물에 비교적 잘 반응한다.
            - 망상(피해망상, 과대망상, 관계망상, 조종망상), 환각(환청이 가장 흔함), 와해된 언어, 와해된 행동, 긴장증적 행동

            # 음성증상
            정상 기능이 **줄어들거나 없어진 것**이다. 치료 반응이 낮고 사회적 기능 저하와 관련이 깊다.
            - 정동 둔마(무감동), 무언어증(언어빈곤), 무의욕증, 무쾌감증, 비사회성(사회적 위축)
            - 국시: 2023-83 (양성증상 → 피해망상, 나머지 보기는 모두 음성증상)

            # Bleuler의 4A
            - **연상이완(Association)**: 생각의 연결이 느슨해 말의 논리가 끊긴다.
            - **정동장애(Affect)**: 정동이 둔마되거나 상황에 맞지 않는다.
            - **양가감정(Ambivalence)**: 서로 반대되는 감정이나 생각을 동시에 가져 결정을 내리지 못한다.
            - **자폐증(Autism)**: 외부 현실보다 내부의 공상 세계에 몰두한다.

            # 3. 주요 증상 자세히 보기
            - **사고내용 장애**: 망상은 논리적 설득으로 바뀌지 않는 잘못된 확고한 믿음이다.
            - **사고형태 장애**: 연상이완, 사고이탈, 지리멸렬, 말비빔(word salad), 신어조작(neologism), 음향연상(clang association), 보속증, 사고차단
            - **지각 장애**: 환각은 외부 자극 없이 느끼는 지각이다. 환청이 가장 흔하며, 명령 환청은 자해나 타해로 이어질 수 있어 위험하다.
            - **행동 장애**: 긴장증(혼미, 납굴증, 거부증), 반향언어, 반향동작, 상동증, 기이한 행동
            - **정서 장애**: 정동 둔마, 부적절한 정동, 양가감정
            - **병식 결여**: 자신이 병에 걸렸다는 것을 인식하지 못해 치료와 약물 복용을 거부하기 쉽다.

            # 4. 주요 간호진단
            진단은 사례에 나온 자료에 근거하며, 안전과 관련된 문제가 가장 먼저이다.
            - **타인에 대한 폭력의 위험 / 자기 폭력의 위험**: 명령 환청, 피해망상, 흥분, 이미 나타난 공격 행동
              - 국시: 2022-83 (환청에 반응해 주먹을 휘두름)
            - **사회적 고립**: 대화하지 않음, 혼자 지냄, 무표정, 활동 불참
              - 국시: 2023-85
            - **만성적 자존감 저하**: 오랫동안 반복되는 부정적 자기평가, 자기 성과를 깎아내림
              - 국시: 2025-83
            - **감각지각 장애(환각)**, **사고과정장애(망상, 와해)**, **언어적 의사소통 장애**, **자기돌봄 결핍**, **비효과적 치료 이행**

            # 5. 간호중재

            # 폭력 위험이 있는 환자
            - 허용되는 행동과 허용되지 않는 행동을 분명히 알리는 **제한설정**을 한다.
            - 행동화하면 **직원이 상황을 통제하고 보호할 수 있음**을 알려 안전감을 준다.
            - 조용하고 자극이 적은 환경을 제공하고, 경쟁적 활동, 시끄러운 음악, 사람 많은 곳, 화려한 장식은 피한다.
            - 공격성 전조(서성거림, 목소리가 커짐, 주먹 쥠)를 관찰하고 초기에 언어적 중재와 감정 표현을 돕는다.
            - 격리와 억제는 다른 방법이 실패하고 급박한 위험이 있을 때만 **최후의 수단**으로 최소한의 시간 동안 사용한다.
            - 국시: 2023-84, 2020-84

            # 환각이 있는 환자
            - 환각 내용, 특히 **명령 환청**이 있는지 확인한다.
            - 환각을 인정하거나 논쟁하지 않고 "나에게는 들리지 않지만 당신에게는 들린다는 것을 안다"처럼 현실을 제시한다.
            - 환각 뒤에 있는 감정(두려움, 불안)에 초점을 두고, 현실에 기반한 활동으로 주의를 돌린다.

            # 망상이 있는 환자
            - 망상 내용에 논쟁하거나 동의하지 않는다.
            - 망상 밑에 있는 감정과 욕구를 다루고, 현실적인 주제로 대화를 이끈다.
            - 신뢰 관계를 위해 약속을 지키고 일관되게 행동한다.

            # 음성증상과 사회적 고립이 있는 환자
            - 짧고 자주 만나 신뢰를 쌓고, 일대일 관계에서 소집단 활동으로 점차 넓힌다.
            - 성공 경험을 할 수 있는 단순한 활동을 제공하고 작은 성취도 인정해 자존감을 높인다.
            - 사회기술훈련, 일상생활 기술훈련, 약물 복용 교육과 재발 징후 교육을 한다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["불안장애의 종류"],
            title: "불안장애의 종류와 간호",
            body: #"""
            불안장애는 실제 위험에 비해 지나친 불안과 공포가 지속되어 일상생활에 지장을 주는 장애의 묶음이다. 걱정의 대상, 공포를 일으키는 상황, 지속 기간을 보면 범불안장애, 공황장애, 광장공포증, 특정공포증, 사회불안장애, 분리불안장애를 구별할 수 있다.

            # 국시 출제 경향
            - 2020~2026년에 **3문항**이 나왔다(2023, 2025년). 2교시 91~92번 자리에 나온다.
            - **증상 사례로 진단명 고르기**(2문항)
              - 2025-92 가족의 교통사고, 아이들 점심 등 여러 일을 매일 걱정하며 1년 내내 생활이 어려움 → **범불안장애**
              - 2023-91 발표할 때 심계항진, 발한, 더듬거림이 1년 이상 나타남 → **사회불안장애**
            - **특정 장애의 행동특성 고르기**(1문항)
              - 2023-92 분리불안장애의 행동특성 → **주 애착대상과 떨어질 때 불안을 호소**
            - 오답 보기의 구성
              - 2025-92·2023-91: 특정공포증, 광장공포증, 범불안장애, 사회불안장애, 외상후 스트레스장애가 **서로 오답으로 번갈아** 나온다.
              - 2023-92: 예상치 못한 공황발작의 반복(공황장애), 심각한 병에 걸렸다는 두려움(질병불안장애), 둘 이상의 인격(해리성 정체성장애), 외모 결함 집착(신체이형장애)처럼 **다른 장애의 대표 특징**을 보기로 쓴다.

            # 풀이 요령
            - 걱정의 대상이 **하나가 아니라 여러 일상사**이고 오래 지속되면 범불안장애이다.
            - 공포가 **남에게 관찰되고 평가받는 상황**(발표, 남 앞에서 먹기)에 묶여 있으면 사회불안장애이다.
            - **빠져나가기 어렵거나 도움받기 어려운 장소**(대중교통, 군중, 밀폐 공간)가 두려우면 광장공포증, **특정 대상**(동물, 높은 곳, 주사)이면 특정공포증이다.
            - **애착대상과의 분리**가 핵심이면 분리불안장애, **예기치 못한 발작의 반복**이면 공황장애이다.
            - 외상 사건 이후의 재경험, 회피, 과각성이 있어야 외상후 스트레스장애이다.

            # 1. 불안의 개념과 수준
            불안은 막연한 위협에 대한 정서 반응이고, 공포는 구체적인 대상에 대한 반응이다. 불안이 적응을 돕지 못하고 지나치게 지속되면 장애가 된다.
            - **경증 불안**: 지각 영역이 넓어지고 학습 동기가 높아진다.
            - **중등도 불안**: 지각 영역이 좁아지지만 지시를 받으면 주의를 기울일 수 있다.
            - **중증 불안**: 지각 영역이 매우 좁아져 세부적인 것에만 몰두하고 문제해결이 어렵다.
            - **공황**: 지각이 극도로 왜곡되고 통제력을 잃으며 합리적 사고가 불가능하다.

            # 2. 주요 불안장애의 특징

            # 범불안장애 (GAD)
            - 일, 가족, 건강, 돈 등 **여러 사건과 활동에 대한 과도하고 통제하기 어려운 걱정**이 6개월 이상, 대부분의 날에 지속된다.
            - 안절부절, 쉽게 피로함, 집중 곤란, 과민성, 근육 긴장, 수면장애가 동반된다.
            - 국시: 2025-92

            # 공황장애
            - 예상치 못한 **공황발작이 반복**된다. 심계항진, 발한, 떨림, 호흡곤란, 흉통, 어지러움, 죽을 것 같은 두려움, 미칠 것 같은 두려움이 갑자기 나타나 수 분 안에 최고조에 이른다.
            - 발작 후 1개월 이상 또 발작이 올까 걱정하거나 발작을 피하려고 행동을 바꾼다.

            # 광장공포증
            - 공황 같은 증상이 생겼을 때 **빠져나가기 어렵거나 도움을 받기 어려운 장소**(대중교통, 열린 공간, 밀폐된 공간, 줄 서기나 군중, 혼자 집 밖에 있기)를 두려워하고 피한다.

            # 특정공포증
            - **특정 대상이나 상황**(동물, 높은 곳, 폭풍, 혈액·주사, 비행기)에 대해 즉각적이고 지나친 공포를 느끼고 피한다.

            # 사회불안장애 (사회공포증)
            - 다른 사람에게 **관찰되고 평가받는 상황**에서 창피를 당하거나 부정적 평가를 받을까 두려워하고 그 상황을 피한다. 발표, 대화, 남 앞에서 먹거나 글씨 쓰기가 해당한다.
            - 얼굴 붉어짐, 떨림, 발한, 심계항진, 말 더듬기가 나타난다.
            - 국시: 2023-91

            # 분리불안장애
            - **주 애착대상과 떨어지거나 떨어질 것을 예상할 때** 발달 수준에 맞지 않는 과도한 불안을 보인다.
            - 애착대상에게 나쁜 일이 생길까 걱정하고, 등교나 외출을 거부하고, 혼자 자지 못하고, 분리 시 두통이나 복통을 호소한다.
            - 국시: 2023-92

            # 선택적 함구증
            - 말할 수 있는데도 학교처럼 말이 기대되는 **특정 사회적 상황에서 지속적으로 말하지 않는다**.

            # 3. 불안장애 대상자의 간호중재

            # 공황이나 중증 불안 상태
            - 대상자 곁에 머물러 안전감을 주고, 조용하고 자극이 적은 환경으로 옮긴다.
            - 짧고 간단하며 분명한 말로 지시하고, 차분한 태도를 유지한다.
            - 천천히 깊게 숨 쉬도록 돕는다. 이 단계에서는 원인 탐색이나 통찰을 요구하지 않는다.

            # 불안이 가라앉은 뒤
            - 불안을 느낄 때의 감정과 상황을 말로 표현하게 하고, 불안의 유발 요인을 함께 찾는다.
            - 이완요법, 심호흡, 인지 재구성처럼 효과적인 대처 방법을 가르친다.
            - 공포증에는 **체계적 탈감작**이나 **노출치료**로 두려운 대상에 점진적으로 노출시킨다.
            - 분리불안 아동은 분리 시간을 조금씩 늘리고, 부모가 일관된 태도로 분리하도록 교육한다.

            # 약물
            - 선택적 세로토닌 재흡수 억제제(SSRI)가 흔히 1차 약물로 쓰인다.
            - 벤조디아제핀은 빠르게 불안을 줄이지만 의존과 내성, 진정 작용이 있어 단기간 사용하고 알코올과 함께 복용하지 않도록 교육한다. 갑자기 끊지 않는다.
            - 부스피론은 의존성이 적지만 효과가 나타나는 데 시간이 걸린다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["강박 및 관련 장애"],
            title: "강박장애와 관련 장애 정리",
            body: #"""
            강박장애는 원치 않는 생각이나 충동(강박사고)이 반복되어 불안이 생기고, 그 불안을 줄이려고 손 씻기나 확인하기 같은 반복 행동(강박행동)을 하는 장애이다. 강박행동은 불안을 줄이는 수단이므로, 간호는 처음에는 행동을 허용하고 신뢰가 생긴 뒤 점차 제한하는 순서로 진행한다.

            # 국시 출제 경향
            - 2020~2026년에 **6문항**이 나왔다(2020, 2021, 2022, 2023, 2024년). 2교시 91~94번 자리에 나온다.
            - **강박행동의 의미와 정신역동**(3문항)
              - 2023-94 강박장애 대상자의 특성 → **불안을 줄이기 위해 반복적인 행동을 함**
              - 2022-91 반복적으로 손을 씻는 행동의 원인 → **불안 완화**
              - 2020-93 반복적 손 씻기의 정신역동 → **받아들이기 어려운 충동으로 인한 불안을 완화하기 위함**
            - **입원 초기 간호중재**(2문항)
              - 2024-92 오염을 걱정해 항상 장갑을 끼는 환자의 초기 중재 → **요구대로 장갑 착용을 허용**
              - 2021-94 어제 입원해 물건을 만질 때마다 손을 씻는 환자 → **손 씻는 행동을 허용**
            - **강박 관련 장애 감별**(1문항)
              - 2022-94 거울 속 얼굴이 괴물처럼 보인다며 출근을 거부함 → **신체이형장애**
            - 오답 보기의 구성
              - 2024-92·2021-94: 금지, 벌칙, 참으라는 격려, 비합리적이라는 논리적 설명, 반복 행동 자체에 초점 둔 대화가 나온다. 시간표 제공과 대처 방법 학습은 **초기가 아니라 이후 단계**의 중재이다.
              - 2022-91·2020-93: 관심 요구, 분노 표현, 약물 부작용, 입원 저항, 청결 목적, 투사·동일시 방어기제, "비합리적이라고 인식하지 못함"이 오답이다.
              - 2023-94: 기억장애, 특정 상황에서 말하지 않음(선택적 함구증), 여러 인격(해리성 정체성장애), 외부세계를 낯설게 느낌(비현실감)이 섞인다.
              - 2022-94: 전환장애, 인위성장애, 질병불안장애, 해리성 정체성장애를 함께 제시한다.

            # 풀이 요령
            - 강박행동의 목적을 물으면 항상 **불안 완화**이다. 청결, 관심 끌기, 분노 표현은 오답이다.
            - "초기", "어제 입원한" 같은 단서가 있으면 **강박행동 허용**을 고른다. 금지, 벌칙, 논리적 설명은 언제나 오답이다.
            - 강박장애 환자는 대부분 자신의 생각과 행동이 **지나치고 비합리적이라는 것을 안다**(자아이질적).
            - 방어기제는 **격리, 취소, 반동형성**을 기억한다. 투사나 동일시가 보기에 있으면 오답이다.
            - 사소하거나 남에게 보이지 않는 **외모 결함에 대한 집착**은 신체이형장애이다.

            # 1. 강박사고와 강박행동
            - **강박사고(obsession)**: 반복적이고 지속적으로 떠오르는 원치 않는 생각, 충동, 심상이다. 오염, 의심, 대칭, 공격적·성적 내용이 흔하며 심한 불안을 일으킨다.
            - **강박행동(compulsion)**: 강박사고로 생긴 불안을 줄이거나 두려운 일을 막기 위해 반복하는 행동이나 정신 활동이다. 손 씻기, 확인하기, 정리하기, 숫자 세기, 기도하기가 있다.
            - 강박행동을 하면 불안이 잠시 줄어들어 그 행동이 **강화**되고 계속 반복된다.
            - 대부분 자신의 생각이 지나치다는 것을 알면서도 멈추지 못해 괴로워한다(자아이질적). 시간이 많이 걸려 일상생활, 직업, 대인관계에 지장을 준다.
            - 국시: 2023-94, 2022-91

            # 2. 정신역동과 방어기제
            정신역동적으로 강박증상은 받아들이기 어려운 공격적·성적 충동으로 생긴 불안을 다루기 위한 것이다.
            - **격리(isolation)**: 생각과 감정을 분리해, 불쾌한 생각을 감정 없이 떠올린다.
            - **취소(undoing)**: 받아들일 수 없는 생각이나 행동을 상징적인 행동으로 없었던 일처럼 만든다. 반복적인 손 씻기가 대표적이다.
            - **반동형성(reaction formation)**: 받아들일 수 없는 충동과 정반대로 행동한다. 지저분해지고 싶은 충동을 지나친 청결로 표현하는 식이다.
            - 국시: 2020-93 (받아들이기 어려운 충동으로 인한 불안 완화, 투사·동일시는 오답)

            # 3. 강박 및 관련 장애
            - **신체이형장애**: 남에게는 보이지 않거나 사소한 외모 결함에 지나치게 몰두한다. 거울을 반복해서 보거나 피하고, 결함을 가리거나 성형을 반복하며, 사회생활을 회피한다.
              - 국시: 2022-94
            - **수집광(저장장애)**: 실제 가치와 관계없이 물건을 버리지 못하고 쌓아 두어 생활공간이 어지러워진다.
            - **발모광(털뽑기장애)**: 자신의 털을 반복적으로 뽑아 털이 빠진다.
            - **피부뜯기장애**: 피부를 반복적으로 뜯어 상처가 생긴다.

            # 4. 간호중재

            # 입원 초기
            - 강박행동을 **허용**한다. 갑자기 막으면 불안이 극심해진다.
            - 강박행동을 할 시간을 일과 안에 확보해 주고, 식사, 수면, 위생 같은 기본 요구가 채워지는지 확인한다. 반복적인 손 씻기로 인한 피부 손상을 관찰하고 관리한다.
            - 비판하거나 벌을 주지 않고, 수용적이고 비심판적인 태도를 유지한다.
            - 국시: 2024-92, 2021-94

            # 신뢰 관계가 형성된 뒤
            - 강박행동의 횟수와 시간을 대상자와 함께 정해 **점차 제한**한다. 시간표를 제공하는 것도 이 단계의 방법이다.
            - 반복 행동 자체보다 **행동 밑에 있는 불안과 감정**에 초점을 두고 대화한다.
            - 불안을 다루는 대처 방법(이완요법, 사고중지)을 가르치고, 구조화된 활동으로 주의를 돌린다.
            - 강박행동을 하지 않고 견딘 것을 인정하고 칭찬한다.

            # 치료
            - **노출 및 반응방지**: 불안을 일으키는 자극에 노출시키되 강박행동을 하지 않고 불안이 가라앉는 것을 경험하게 하는 인지행동치료이다.
            - 약물은 선택적 세로토닌 재흡수 억제제(SSRI)와 클로미프라민이 쓰인다.
            """#
        ),
        // 설명이 없던 주제에 새로 쓴 설명
        TopicGuide(
            topics: ["신체증상 및 관련 장애, 해리장애"],
            title: "신체증상 관련 장애와 해리장애",
            body: #"""
            신체증상 및 관련 장애는 심리적 갈등과 스트레스가 신체 증상이나 건강에 대한 걱정으로 나타나는 장애이고, 해리장애는 견디기 어려운 경험에서 벗어나려고 기억, 정체성, 의식, 지각의 통합이 깨지는 장애이다. 간호의 핵심은 증상을 무시하지도 강화하지도 않으면서, 증상 밑에 있는 불안과 감정을 다루는 것이다.

            # 국시 출제 경향
            - 2020~2026년에 **8문항**이 나왔다(2020, 2022, 2023, 2024, 2025, 2026년). 2교시 94~95번 자리에 나온다.
            - **전환장애의 특성**(3문항)
              - 2025-94 사격 훈련을 앞두고 집게손가락이 마비된 군인 → **마비의 일차적 이득은 불안의 경감**
              - 2023-95 성적 스트레스로 오른손이 마비되었지만 걱정하지 않는 고등학생 → **만족스러운 무관심(la belle indifférence)**
              - 2022-95 전환장애 환자의 특성 → **기능손상에 대해 만족스러운 무관심을 나타냄**
            - **질병불안장애와 신체증상장애의 간호**(3문항)
              - 2026-95 검사가 정상인데 유방암에 걸렸다고 믿고 불안해함 → **불안을 말로 표현하게 함**
              - 2025-95 여러 신체 증상으로 여러 병원을 다니며 매우 걱정함 → **치료진이 검사 결과에 대해 일관된 정보 제공**
              - 2020-95 고부갈등이 심한 여성이 여러 신체 증상으로 병원을 전전함 → **비효과적 대처**
            - **인위성장애와 해리성 기억상실**(2문항)
              - 2024-94 의도적으로 근육이완제를 먹고 휠체어 생활을 하며 관심을 받음 → **인위(성)장애**
              - 2024-95 해리성 기억상실의 설명 → **과거의 상황과 위험으로부터 도피하기 위해 나타남**
            - 오답 보기의 구성
              - 2025-94: 합일화 방어기제, 마비에 대한 걱정이 많음, 원인이 심리적임을 앎, 사람이 없을 때 심해짐처럼 **전환장애와 반대되는 특성**을 둔다.
              - 2023-95는 상동증, 기억상실, 플래시백, 건강염려를, 2022-95는 질병불안장애(건강 불안, 질병 몰두), 인위성장애(의도적으로 아픈 척), 신체증상장애(다양한 신체 증상)의 특징을 오답으로 둔다.
              - 2026-95·2025-95: 병을 인정함, 원할 때마다 검사 반복, 증상에 초점 맞춘 대화, 증상 무시, 의존 욕구 무시, 전문용어로 결과 통보가 오답이다.
              - 2024-94: 전환장애, 질병불안장애, 신체증상장애, 이인성/비현실감 장애를 함께 제시한다.
              - 2024-95: 기질적 뇌 손상, 몸이 기계처럼 느껴짐(이인증), 새로운 학습 능력 장애, **억제**(의식적) 방어기제가 오답이다.
              - 2020-95: 급성 혼동, 자해의 위험성, 언어적 의사소통 장애, 전해질 불균형의 위험처럼 근거 자료가 없는 진단을 둔다.

            # 풀이 요령
            - 신경학적 원인 없는 **운동·감각 기능 상실**(마비, 실명)에 **걱정하지 않는 태도**가 있으면 전환장애이다.
            - 증상이 **의도적**인지 먼저 본다. 관심과 돌봄을 위해 의도적으로 만들면 인위성장애, 돈이나 병역 면제 같은 외적 보상이 목적이면 꾀병이다. 나머지는 의도적이지 않다.
            - 간호중재는 **증상보다 감정에 초점**, **일관된 정보 제공**, **불필요한 반복 검사 피하기**를 고른다. 증상을 무시하거나 병을 인정하는 보기는 오답이다.
            - 일차적 이득은 **불안 감소**, 이차적 이득은 관심, 책임 회피 같은 외부 보상이다.
            - 해리성 기억상실의 방어기제는 **억압**(무의식)이다. 억제(의식)와 헷갈리게 출제된다.

            # 1. 신체화와 이득의 개념
            - **신체화**: 심리적 갈등과 스트레스를 신체 증상으로 표현하는 것이다. 증상은 실제로 느끼는 고통이며 꾸며낸 것이 아니다.
            - **일차적 이득**: 증상으로 내적 갈등을 피해 **불안이 줄어드는 것**이다.
            - **이차적 이득**: 증상 덕분에 관심, 돌봄, 의무 면제 같은 **외부 보상**을 얻는 것이다.
            - 국시: 2025-94 (마비의 일차적 이득 → 불안의 경감)

            # 2. 신체증상 및 관련 장애의 구별

            # 신체증상장애
            - 하나 이상의 괴로운 신체 증상(통증, 소화기 증상 등)이 있고, 그 증상에 대한 **지나친 생각, 불안, 시간과 에너지 소모**가 6개월 이상 지속된다.
            - 검사에서 이상이 없어도 여러 병원을 전전한다(doctor shopping).
            - 국시: 2025-95, 2020-95

            # 질병불안장애 (건강염려증)
            - 신체 증상이 없거나 경미한데도 **심각한 병에 걸렸거나 걸릴 것이라는 생각에 몰두**한다. 검사가 정상이어도 안심하지 못한다.
            - 국시: 2026-95

            # 전환장애 (기능성 신경학적 증상장애)
            - 심리적 갈등이 신경학적 원인 없이 **수의적 운동이나 감각 기능의 이상**으로 나타난다. 마비, 실명, 실성증, 경련, 감각 상실이 해당한다.
            - 스트레스 사건 직후 갑자기 생기는 경우가 많고, 증상은 무의식적이며 의도적이지 않다.
            - 심각한 증상에도 태연한 **만족스러운 무관심(la belle indifférence)**을 보일 수 있다.
            - 사용되는 방어기제는 억압과 전환이다.
            - 국시: 2025-94, 2023-95, 2022-95

            # 인위성장애 (허위성장애)
            - 뚜렷한 외적 보상 없이 **환자 역할을 하려고 의도적으로 증상을 만들거나 꾸민다**. 스스로에게 하는 경우와 타인(주로 자녀)에게 증상을 만드는 경우가 있다.
            - **꾀병**은 돈, 병역 면제, 법적 처벌 회피 같은 외적 보상을 위해 꾸미는 것으로 정신장애로 분류하지 않는다.
            - 국시: 2024-94

            # 3. 해리장애
            - **해리성 기억상실**: 외상이나 스트레스와 관련된 중요한 개인 정보를 기억하지 못한다. 견디기 어려운 상황에서 **심리적으로 도피**하는 것이며, 기질적 손상이 없고 새로운 학습 능력은 유지된다. 갑자기 집을 떠나 방황하는 해리성 둔주가 동반될 수 있다.
              - 국시: 2024-95
            - **해리성 정체성장애**: 둘 이상의 뚜렷한 인격 상태가 존재하고, 인격이 바뀐 동안의 일을 기억하지 못한다. 아동기의 심한 외상과 관련이 깊다.
            - **이인성/비현실감 장애**: 이인증은 자신이 낯설게 느껴지거나 몸 밖에서 자신을 관찰하는 느낌(몸이 기계 같음), 비현실감은 외부세계가 꿈처럼 낯설게 느껴지는 것이다. **현실 검증력은 유지**된다.

            # 4. 간호중재

            # 신체증상장애, 질병불안장애
            - 먼저 신체적 원인을 배제한 뒤, 증상 호소를 **무시하지 않고 인정**하되 증상에 대한 대화는 제한한다.
            - 대화의 초점을 신체 증상에서 **불안, 스트레스, 감정**으로 옮기고, 감정을 말로 표현하게 한다.
            - 치료진 모두가 검사 결과에 대해 **일관된 정보**를 쉬운 말로 제공한다. 불필요한 검사를 반복하지 않는다.
            - 의존 욕구는 초기에 어느 정도 충족시키면서 점차 줄이고, 스트레스를 다루는 효과적인 대처 방법을 가르친다.
            - 주요 간호진단은 비효과적 대처, 불안, 만성 통증 등이다.

            # 전환장애
            - 증상 자체에 관심을 집중하지 않아 이차적 이득을 줄이고, 증상이 아닌 적응적 행동에 관심을 준다.
            - 증상은 꾸민 것이 아니므로 "꾀병"으로 대하거나 직면하지 않는다.
            - 기능을 유지하도록 돕고, 갈등과 감정을 말로 표현하게 한다.

            # 해리장애
            - 안전을 확보하고, 조용하고 지지적인 환경을 제공한다.
            - 잃어버린 기억을 억지로 떠올리게 하지 않고, 대상자의 속도에 맞추어 외상 경험과 감정을 다룬다.
            - 해리를 유발하는 스트레스 요인을 확인하고 대처 방법을 가르친다. 이인증에는 현실감을 되찾도록 그라운딩 기법을 쓴다.
            """#
        ),
