            body: #"""
            주의력결핍과잉행동장애(ADHD)는 발달 수준에 맞지 않는 부주의, 과잉행동, 충동성이 아동기부터 여러 환경에서 지속되어 학업과 사회생활에 지장을 주는 신경발달장애이다. 치료는 중추신경자극제 약물과 구조화된 환경, 일관된 규칙, 긍정적 강화 같은 행동중재를 함께 쓰며, 부모와 교사 교육이 중요하다.

            # 국시 출제 경향
            - 2020~2026년에 **4문항**이 나왔다(2021, 2023, 2024, 2025년). 2교시 104~105번 자리에 나온다.
            - **간호중재와 부모교육**(2문항)
              - 2024-105 ADHD 아동을 위한 간호중재 → **한 번에 한 가지 과제를 하도록 함**
              - 2023-104 부모 교육 내용 → **"아이에게 말할 때는 단순하고 명확하게 하세요."**
            - **약물**(1문항)
              - 2025-105 충동성과 산만함을 완화하려고 처방하는 약물 → **메틸페니데이트**
            - **간호진단**(1문항)
              - 2021-104 수업 중 뛰어다니고 질문 전에 불쑥 대답하며 순서를 기다리지 못함 → **비효과적 역할수행**
            - 오답 보기의 구성
              - 2024-105·2023-104: 다양한 변화 추구, 자극적인 환경, 추상적인 과제, 주의를 끄는 행동에 관심 주기, 경쟁적 놀이, 복잡하고 어려운 과제, 무조건 허용, 한 번에 여러 과제처럼 **구조화·단순화 원칙과 반대되는 보기**가 나온다.
              - 2025-105: 레세르핀(항고혈압제), 다이설피람(알코올 혐오제), 도네페질(치매 치료제), 프로프라놀롤(베타차단제)처럼 **다른 영역의 약물**을 섞는다.
              - 2021-104: 자존감 저하, 방어적 대처, 자기돌봄 결핍, 언어적 의사소통 장애처럼 사례에 근거가 없는 진단을 둔다.

            # 풀이 요령
            - 중재와 부모교육 문항은 **단순하게, 하나씩, 구조화, 자극 감소, 일관성**의 방향을 고른다. 변화, 자극, 경쟁, 여러 과제, 무조건 허용은 오답이다.
            - ADHD 약물을 물으면 중추신경자극제인 **메틸페니데이트**이다.
            - 부적절한 관심 끌기 행동에는 관심을 주지 않고, **바람직한 행동을 즉시 칭찬**하는 보기를 고른다.
            - 학생으로서 수업을 듣고 순서를 지키는 일을 못하는 사례에는 **비효과적 역할수행**을 고른다.

            # 1. ADHD의 개념과 진단
            - 부주의 또는 과잉행동-충동성 증상이 **12세 이전**에 시작되고, **6개월 이상** 지속되며, 가정과 학교처럼 **두 곳 이상의 환경**에서 나타난다.
            - 각 영역에서 증상이 6개 이상(17세 이상은 5개 이상) 있어야 한다.
            - 유형은 **부주의 우세형, 과잉행동-충동 우세형, 복합형**으로 나눈다.
            - 남아에게 더 많고, 전두엽 기능과 도파민·노르에피네프린 체계의 이상, 유전적 요인이 관련된다.
            - 학습장애, 적대적 반항장애, 품행장애, 틱장애가 함께 나타나기 쉽다.

            # 2. 핵심 증상
            - **부주의**: 세부 사항을 놓쳐 실수가 잦고, 주의를 지속하기 어렵고, 말을 걸어도 듣지 않는 것처럼 보인다. 과제를 끝까지 하지 못하고, 물건을 자주 잃어버리고, 쉽게 산만해지며 잘 잊어버린다.
            - **과잉행동**: 손발을 가만두지 못하고, 앉아 있어야 할 때 자리를 뜨고, 부적절하게 뛰어다니거나 기어오르며, 말이 지나치게 많다.
            - **충동성**: 질문이 끝나기 전에 불쑥 대답하고, 차례를 기다리지 못하며, 다른 사람의 활동을 방해하거나 끼어든다.
            - 국시: 2021-104 (뛰어다님, 불쑥 대답, 순서를 기다리지 못함)

            # 3. 약물치료와 교육

            # 중추신경자극제
            - **메틸페니데이트**가 대표 약물이다. 도파민과 노르에피네프린을 증가시켜 주의 집중을 높이고 과잉행동과 충동성을 줄인다. 암페타민 계열도 쓰인다.
            - 국시: 2025-105

            # 부작용
            - 식욕 저하, 체중 감소, 불면이 가장 흔하다.
            - 두통, 복통, 빈맥, 혈압 상승, 과민성이 나타날 수 있고, 장기 복용 시 성장 지연이 생길 수 있다. 틱이 악화될 수 있다.

            # 복용 교육
            - 식욕 저하를 줄이기 위해 **아침 식사 중이나 식사 후**에 복용한다.
            - 불면을 막기 위해 **늦은 오후나 저녁에는 복용하지 않는다**.
            - 키와 체중을 정기적으로 측정해 성장을 확인한다. 의사의 판단에 따라 주말이나 방학에 약을 쉬는 약물 휴일을 두기도 한다.
            - 남용 가능성이 있으므로 보호자가 약을 관리하고, 임의로 끊거나 용량을 바꾸지 않는다.

            # 비자극제
            - 아토목세틴은 노르에피네프린 재흡수 억제제로, 자극제에 반응하지 않거나 부작용이 심할 때 쓴다.

            # 4. 간호중재와 부모교육

            # 환경과 과제
            - 자극이 적고 **구조화된 환경**을 제공하고, 일과를 예측할 수 있게 일정하게 유지한다.
            - 과제는 작게 나누어 **한 번에 한 가지씩**, 짧고 구체적으로 제시한다.
            - 지시는 눈을 맞추고 **단순하고 명확하게** 하며, 이해했는지 따라 말하게 한다.
            - 경쟁적인 놀이보다 에너지를 발산할 수 있는 비경쟁적 신체활동을 제공한다.
            - 국시: 2024-105, 2023-104

            # 행동수정
            - 규칙과 제한을 분명히 정하고 **일관되게** 적용한다. 모든 행동을 허용하지 않는다.
            - 바람직한 행동은 즉시 칭찬하거나 토큰으로 보상하는 **긍정적 강화**를 쓴다.
            - 관심을 끌기 위한 부적절한 행동은 무시하고, 규칙 위반에는 타임아웃 같은 결과를 일관되게 적용한다.
            - 성공 경험을 통해 자존감을 높이고, 부모와 교사가 같은 방식으로 대하도록 협력한다.

            # 5. 주요 간호진단
            - **비효과적 역할수행**: 학생으로서 기대되는 역할(수업 참여, 순서 지키기)을 하지 못한다.
              - 국시: 2021-104
            - **상해의 위험**: 충동적이고 부주의한 행동으로 다칠 수 있다.
            - **사회적 상호작용 장애**: 끼어들기와 충동성으로 또래 관계가 어렵다.
            - **자존감 저하**: 반복되는 실패와 꾸중으로 자신을 부정적으로 본다.
            - **가족과정 장애**, **비효과적 양육**: 양육 부담과 가족 갈등이 커진다.
            """#
